<template>
  <section>
    <div class="row m-0">
      <div class="heading-border">
        <h5 class="h5">
          <span>{{ $t('Event') }} {{ $t('Gallery') }}</span>
          <small href="javascript:;" class="float-right cursorpointer" @click="openAdd"><i class="fa fa-plus pr-2"></i>{{ $t('Add') }}</small>
        </h5>
      </div>
      <div class="col-12 p-0 mt-2">
        <div class="row" v-if="images && images.length">
          <div class="col-md-4 col-lg-3 p-2" v-for="(img, i) in images" :key="img.id || i">
            <div class="card border"><img :src="img.url || img.URL" class="card-img-top" style="height:150px;object-fit:cover" /><div class="card-body p-2"><small>{{ img.caption || img.CAPTION || '—' }}</small></div></div>
          </div>
        </div>
        <div v-else class="text-center py-4"><span class="text-danger no-record">{{ $t('NoRecordfound') }}</span></div>
      </div>
    </div>
    <AddGallery v-if="showAddModal" :event-id="eventId" @close="showAddModal = false" @saved="fetch" />
  </section>
</template>

<script>
import DataService from '@/services/DataService';
import AddGallery from '../Modals/AddGallery.vue';

export default {
  name: 'EventGalleryPortion',
  components: { AddGallery },
  props: { eventId: { type: [Number, String], required: true } },
  data() { return { images: [], showAddModal: false, PageSize: 10, PageNumber: 1 }; },
  created() { this.fetch(); },
  methods: {
    async fetch() {
      try {
        const res = await DataService.EventGalleryListing(`projectId=${this.eventId}&pageSize=${this.PageSize}&pageNumber=${this.PageNumber}`);
        this.images = (res.data && res.data.result && res.data.result.data) ? res.data.result.data : (res.data && res.data.result && Array.isArray(res.data.result)) ? res.data.result : [];
      } catch (_) { this.images = []; }
    },
    openAdd() { this.showAddModal = true; }
  }
};
</script>
