<template>
    <section>
        <div>
            <tg-list  
                ref="tgList" 
                :listType="['List']" 
                :IsShowAction="true" 
                :showCheckBox="true" 
                ModuleName="PROJECT" 
                SubModuleCode="Client" 
                IdentityColumn="QUOTATION_ID" 
                :HeaderText="$t('QUOTES')"
                :ListData="ListingData" 
                :HeaderData="Headers" 
                :widgets="widgets" 
                :HeaderButtons="Buttons"
                :TotalRecords="TotalRecords"  
                :RenderRowActionMethod="renderActions"
                :ListDataCallBackFunction="QuotesList" 
                :SortExp="SortExp" 
                :SortBy="SortBy" 
                :NorecordfoundText="$t('NoRecordfound')"  
                v-on:PagerButtonClick="pagerMethod"
                v-on:HeaderButtonClick="commonHeaderButtonClick" 
                v-on:ActionButtonClick="actionButtonClick"
                v-on:SortdataButtonClick="sortdata" :Key="Key">  
                 <template v-slot:slotdata="{ data }">
                 <template v-if="data.column.COLUMN_NAME == 'START_DATE'">
                    <span :title="$d(data.row.START_DATE)">{{ $d(data.row.START_DATE) }}</span>
                </template>          
                <template v-if="data.column.COLUMN_NAME == 'END_DATE'">
                    <span :title="$d(data.row.END_DATE)">{{ $d(data.row.END_DATE)}}</span>
                </template>  
                  <template v-if="data.column.COLUMN_NAME == 'CLIENT_NAME'">
                    <span>{{ data.row.CLIENT_NAME || '--'}}</span>
                </template>  
                  <template v-if="data.column.COLUMN_NAME == 'PROJECT_REQUEST_TITLE'">
                    <span>{{data.row.PROJECT_REQUEST_TITLE || '--'}}</span>
                </template> 
                   <template v-if="data.column.COLUMN_NAME == 'NET_PAYABLE_AMOUNT'">
                  
                    <span>  {{$n(data.row.NET_PAYABLE_AMOUNT,'currency',$getLocaleByCurrency(CurrencyCode))  }}</span>
                </template>  
                
                 </template>    
            </tg-list>
        </div>
    </section>
</template>
<script>
import Schema from './QuotesListingSchema'
import DataService from '../../../../services/DataService';
export default { 
    components: {  },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        projectCurrency:{
            type: String,
        }, checkPmUser: {
            type: Boolean,
            required: true
        },
        ProjectOwner: {
            type: String
        }
    },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            statusId: '',
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            ProjectName:'',
            taskId: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: Schema.buttons,
            IsEditTeamShow: false,
            QuotesListingSchema: false,
            CurrencyCode:'PKR',
            ProjectId:0,
            Key:0
        };
    },

    created: async function() {   
        
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.userId = this.GetUserInfo.ID;
        this.ProjectId = this.projectId;
        this.CurrencyCode = this.projectCurrency;
        this.Headers[5].DISPLAY_NAME=`Amount (${this.CurrencyCode})`;
        this.ProjectOverview();
        this.QuotesList();  
    },    
    methods: {
        ProjectOverview:async function(){
            var vm = this;
            var params = `projectId=${this.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {                
                   if(response.data != null > 0)
                   {                      
                      vm.ProjectName=response.data.projecT_NAME;
                   }
            });
        }, 
        renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {                    
                    case 'Edit':
                        action.isVisible = true;
                        break;   
                        case 'DeleteClientData':
                        action.isVisible = true;
                        break;                      
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchTaskList();
        },
        actionButtonClick: function (callbackfunction, item) {
            
            switch (callbackfunction) {       
                case 'DeleteClientData':
                    this.commonDeleteData(item.QUOTATION_ID);
                    break;  
                     case 'Edit':
                    this.EditQuote(item);
                    break;        
            }
        },
       async EditQuote(data)
        {
            var vm=this;
           var url='controller=Quotation&action=Edit'
             await DataService.CheckPrivilege(url).then(async function (response) {                
                 if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    const title = encodeURIComponent(data.QUOTATION_TITLE || '');
                    const url = `/Quotation/Create/${vm.ProjectId}/1/${data.CREATED_BY}/${title}/0/${vm.CurrencyCode}/ProjectRequest`;
                    localStorage.setItem("EditQuoteData", JSON.stringify(data));
                    window.open(url, '_blank');
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                } 
            });  
        },
        commonHeaderButtonClick: async function(event) {            
            var vm=this;            
            switch (event.callbackfunction) {
                case "AddQuotes":
                vm.AddQuotes();
                    break;
                case "EditProject":
                vm.EditProject();
                    break;
                case "BackToList":
                    this.BackToList();
                    break;
                case "DeleteClientData":
                    vm.commonDeleteData();
                    break;
            }
        },
    
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchTaskList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
          commonDeleteData:async function (id) {
            var vm = this;
            var val = "";
            vm.isLoading = true;

            var url='controller=Quotation&action=Delete'
             await DataService.CheckPrivilege(url).then(async function (response) {                
                 if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    if (id == null) {
                $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                    if (val.length > 0)
                        val += ',';
                    val += $(this).val();
                });
            }
            else {
                val = id;
            }
            if (val != null) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                    var postJSON = {
                        ids: val,
                        moduleName: "PROJECT",
                        refCode: "TALYGEN_QUOTE"
                    };
                    var objectPostString = JSON.stringify(postJSON);
                    DataService.CommonCommonDelete(objectPostString).then(function (response) {

                        vm.isLoading = false;
                        if (response.status == 200) {
                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Quote')]), "success", true, vm.$t("Alert"));
                            vm.QuotesList();
                            vm.Key++;
                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Quote')]), "warning", true, vm.$t("Alert"));
                        }
                    });
                });
            }
            else {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
            }
            vm.isLoading = false;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                } 
            }); 
            vm.isLoading = false; 
        },
        BackToList: function () { 
            this.$router.push({ name: 'ProjectList' });
        },
        AddQuotes:async function() {               
            var vm = this;         
            var url='controller=Quotation&action=Create'
             await DataService.CheckPrivilege(url).then(async function (response) {                
                 if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    const title = encodeURIComponent(vm.ProjectName || '');
                    const url = `/Quotation/Create/${vm.projectId}/6/0/${title}/0/${vm.CurrencyCode}/Project`;
                    window.open(url, '_blank');  
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                } 
            });  
        },
        QuotesList: async function() {  
            this.isLoading = true;
            const params = `quotationType=Project&projectId=${this.projectId}&clientId=&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&search=`;
            await DataService.GetQuoteList(params).then(response => {            
                const data = response.data.result.data;
               if (data.length > 0) {
                    this.ListingData = response.data.result.data;
                   this.ListingData.forEach((item) => {
                       if (item.START_DATE != null) {
                           item.START_DATE = new Date(item.START_DATE)
                       }
                       if (item.END_DATE != null) {
                           item.END_DATE = new Date(item.END_DATE)
                       }
                   });
                    this.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
            });
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        },
     
    }
};
</script>

