<template>
    <section>
        <loader :is-visible="isLoading"></loader>
        <div class="ticketsmallfix theme-primary partition p-actions-expand mt-2" style="overflow: visible;">
            <span class="p-name text-white">{{ $t(NewTabName) }}</span>
            <span class="p-actions float-right">
                <a title="Import To Issue" href="javascript:;" class="p-action-btn text-white " @click="BulkAction">
                    <em class="fa fa-plus pr-2"></em> <br>
                    <span>{{ $t('Bulk Action') }}</span>
                </a>
                <a v-if="SprintButton" title="Create Sprint" @click="CreateSprint" href="javascript:;"
                    class="p-action-btn text-white">
                    <em class="fa fa-plus pr-2 "></em> <br><span>{{ $t('CreateSprint') }}</span></a>
                <a v-if="CheckDisabled()" title="Add Backlog" @click="AddBacklog" href="javascript:;"
                    class="p-action-btn text-white">
                    <em class="fa fa-plus pr-2 "></em> <br><span>{{ $t('Add') }} {{ $t(NewTabName == 'BackLog' ?
                        'Backlog' : NewTabName) }}</span></a>
                <a title="Delete" href="javascript:;" @click="commonDeleteData($event, 'Head')"
                    class="p-action-btn text-white">
                    <em class="fa fa-trash-o pr-2 "></em> <br><span>{{ $t('Delete') }}</span></a>
                <a title="" @click="BackToList" class="p-action-btn text-white float-right"
                    data-toggle-tooltip="tooltip" data-original-title="Back to list"><i aria-hidden="true"
                        class="fa fa-angle-double-left"></i><br>{{ $t('BacktoList') }}</a>
            </span>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0 top-menu-tab border p-3">
            <div class="row p-0 pt-2 colcontrol">

                <div class="col float-left">
                    <div class="form-group mb-2">
                        <input class="form-control" :placeholder="dynamicPlaceholderr" @keyup.enter="SearchByTaskName"
                            v-model="IsTaskName">
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="TypeFilter" :options="ProjectBacklogType" placeholder="Type"
                            :multiple="true" :limit="1" :limitText="getFilterLimitText"
                            v-on:input="SearchBacklog(TypeFilter)"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="QuickFilter" :options="QuickfilterBacklogType" placeholder="Assignee"
                            :multiple="true" :limit="1" :limitText="getFilterLimitText"
                            v-on:input="QuickFilterbacklog(QuickFilter)"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="selectedStatus" :options="StatusData" placeholder="Status" :multiple="true"
                            :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchBacklogListing(selectedStatus, 'TASK_BY_STATUS')">
                        </Treeselect>

                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="PriorityFilter" :options="FilterPriorityData" placeholder="Priority"
                            :limit="1" :limitText="getFilterLimitText" :multiple="true"
                            v-on:input="FetchBacklogListing(PriorityFilter, 'TASK_BY_PRIORITY')">
                        </Treeselect>
                    </div>
                </div>

                <div class="col float-left">
                    <div class="background-0 text-left form-check-inline">
                        <!-- <a title="" id="Go" href="javascript:;" data-toggle-tooltip="tooltip"
                                data-original-title="Search" class="btn btn-success mr-1 px-4" @click="SearchFilter">
                                <em class="fa fa-search"></em>{{ $t('Search') }}
                            </a> -->
                        <a href="javascript:void(0);" title="" data-toggle-tooltip="tooltip"
                            data-original-title="Clear all " class="btn btn-danger clearsearchtext px-4"
                            @click="ResetFilter">
                            <em class="fa fa-refresh"></em>{{ $t('Clear') }}
                        </a>
                    </div>
                </div>

            </div>
        </div>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="true" ModuleName="PROJECT"
            SubModuleCode="Task" IdentityColumn="task_id" :HeaderText="$t('Backlog')" :LegendArray="LegendArray"
            :ListData="ListingData" :HeaderData="Headers" :widgets="widgets" :TotalRecords="TotalRecords"
            :RenderRowActionMethod="renderActions" :SearchFields="false" :ListDataCallBackFunction="FetchBacklogListing"
            :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')"
            v-on:PagerButtonClick="pagerMethod" v-on:ActionButtonClick="actionButtonClick"
            v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'key'">
                    <span class="d-flex">
                        <span v-if="data.row.task_type == 'T'" class="text-primary mr-2" title="Task"><i
                                class="fa fa-check-square"></i></span>
                        <span v-if="data.row.task_type == 'S'" class="text-success mr-2" title="Story"><i
                                class="fa fa-film"></i></span>
                        <span v-if="data.row.task_type == 'B'" class="text-danger mr-2" title="Bug"><i
                                class="fa fa-warning"></i>
                        </span>
                        <span :title="data.row.task_name"
                            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">{{
                                data.row.task_name }}</span>
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'created_at'">
                    <div :title="data.row.created_at == null ? '--' : $d(data.row.created_at)">

                        {{
                            data.row.created_at == null ? '--' : $d(data.row.created_at)
                        }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'modified_at'">
                    <div :title="data.row.modified_at == null ? '--' : $d(data.row.modified_at)">

                        {{
                            data.row.modified_at == null ? '--' : $d(data.row.modified_at)
                        }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'status_name'">
                    <listing-status :isfor="'PROJECTBACKLOCKSTATUS'" ref="updatestatus" v-bind:dataid="data.row.task_id"
                        data-controller="Task" v-bind:statuslist="StatusList" v-bind:item="data"
                        v-bind:parentid="data.row.task_id" dataController="Project" dataAction="BacklogStatusUpdate"
                        v-bind:dataselected="data.row.status_name" v-bind:callbackfunction="FetchBacklogListing"
                        v-bind:isselectedvaluestring="true">
                    </listing-status>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'priority_name'">
                    <div class="cstm-drop-btn" v-if="data.row.priority_name != null">
                        <select id="crmlistingStatus_span" v-model="data.row.Priority_id" class="w-100"
                            :style="{ backgroundColor: data.row.color_code, color: '#ffffff' }"
                            @change="CommonPriortyUpdate(data.row, $event)">
                            <option v-for="(item, index) in PriorityData" :key="index" :value="item.value">{{ item.name
                            }}</option>
                        </select>
                    </div>
                    <span class="d-block text-center" v-else>
                        {{ $t('NA') }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'task_description'">
                    <span class="d-block" v-if="data.row.task_description == '' || data.row.task_description == null">
                        {{ $t('NA') }}
                    </span>
                    <span v-else>
                        {{ TruncateStr(data.row.task_description, 25) }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'sprint_name'">
                    <select v-model="data.row.sprint_id" class="form-control"
                        v-on:change="updateTaskStatus(data.row.task_id, data.row.sprint_id, 'PROJECTBACKLOGSPRINTSTATUS')">
                        <option value="null" selected>{{ $t('Select') }} {{ $t(tbName) }}</option>
                        <option v-for="opt in SprintData" :key="opt.sprint_id" :value="opt.sprint_id">
                            {{ opt.sprint_name }}
                        </option>
                    </select>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'Epic_name'">
                    <select v-model="data.row.epic_id" class="form-control"
                        v-on:change="updateEpicStatus(data.row.task_id, data.row.epic_id, 'PROJECTBACKLOGSEPICSTATUS')">
                        <option :value="0" selected>{{ $t('Select Epic') }}</option>
                        <option v-for="opt in EpicData" :key="opt.value" :value="opt.value">
                            {{ opt.name }}
                        </option>
                    </select>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'Assign'">
                    <span v-if="data.row.Assign == null">
                        <a @click="AssignedUser(data.row.task_id, data.row.User_id)" class="text-dark single-action"
                            href="javascript:;" data-placement="left">
                            <em class="fa fa-user-plus"></em>
                        </a>
                    </span>
                    <span v-else>
                        <a @click="AssignedUser(data.row.task_id, data.row.User_id)" class="text-dark single-action"
                            href="javascript:;">
                            <em class="fa fa-user"></em>
                            <span class="noti-circle noti-green" @mouseover="showAssignUser(data.row)"
                                @mouseleave="hideAssignUser(data.row)">{{ data.row.Number }}</span>
                        </a>
                    </span>
                    <div class="viewmoretagsbase_ptl showTags" v-if="data.row.ispopover">
                        <div class="popover-arrowss_ptl"></div>
                        <div class="viewmoretags_ptl">
                            <span class="head" title="Prashant shukla QA">Users</span>
                            <div class="outerbase">
                                <span v-for="(item, index) in data.row.AssignUser" :key="index" title="test">
                                    {{ index + 1 }}. {{ TruncateStr(item, 15) }}
                                </span>
                            </div>

                        </div>
                    </div>
                </template>
            </template>
        </tg-list>

        <div v-if="IsShowTypeCheck" class="add-backlog-btn border bg-light float-left w-100 p-3 mb-5">
            <table id="tablelistingdata_534131" class="table table-bordered mt-0 mb-0" style="width: 100%;">
                <tr class="border-0">
                    <td style="width:80px;" class="py-0 pl-0 pr-3">
                        <div class="d-inline">
                            <div class="checklist-icon bg-light checklist-icon">
                                <div v-if="IsTask" class="text-primary fa fa-check-square"></div>
                                <div v-if="IsBug" class="text-danger fa fa-warning"></div>
                                <div v-if="IsStory" class="text-success fa fa-film"></div>
                                <a class="dropdown pl-2">
                                    <em class="fa fa-angle-down" id="dropdownMenu2" data-toggle="dropdown"
                                        aria-haspopup="true" aria-expanded="false" aria-hidden="true"></em>
                                    <div class="dropdown-menu" aria-labelledby="dropdownMenu2">
                                        <button @click="TypeCheck('T')" class="dropdown-item" type="button"><em
                                                class="fa fa-check-square text-primary pr-2"></em>{{ $t('Task')
                                                }}</button>
                                        <button @click="TypeCheck('B')" class="dropdown-item" type="button"><em
                                                class="fa fa-warning text-danger pr-2"></em>{{ $t('Issue') }}</button>
                                        <button @click="TypeCheck('S')" class="dropdown-item" type="button"><em
                                                class="fa fa-film text-success pr-2"></em>{{ $t('Story') }}</button>
                                    </div>
                                </a>
                            </div>
                        </div>
                    </td>
                    <td colspan="8" class="p-0">
                        <div class="email-alert">
                            <input class="form-control" v-model="IsTypeDescription" rows="2"
                                @keydown.enter="onEnterPressed" :placeholder="dynamicPlaceholder">
                        </div>
                    </td>
                    <td class="p-0" style="width: 130px;">
                        <div class="col-sm-12 pt-1 float-left mt-1">
                            <a class="actions-onclick" title="Save" @click="onEnterPressed"><em
                                    class="fa fa-save action-icon text-success"></em></a>
                            <a @click="IsHideTypeCheck" class="actions-onclick"><em
                                    class="fa fa-close action-icon text-danger"></em></a>
                        </div>
                    </td>
                </tr>
            </table>
        </div>
        <div class="add-backlog-btn border bg-light float-left w-100 p-3" v-if="CheckDisabled() && !IsShowTypeCheck">
            <a class="w-100 text-dark" @click="ShowTypeCheck" type="button"><em class="fa fa-plus pr-2"></em>
                {{ $t('Add') }} {{ $t(NewTabName) }}
            </a>
        </div>
        <AddBacklog v-if="IsAddBacklog" :BacklogId="BacklogId" :NewTabName="NewTabName" :AssignTabTabName="AssignTab"
            :AssignSprintTab="tbName"></AddBacklog>
        <CreateSprint v-if="IsCreateSprint" :IsSprintTabType="IsSprintTabType" :SprintData="SprintData"
            :NewTabName="NewTabName"></CreateSprint>
        <AssignedUser v-if="IsAssignedUser" :BacklogId="BacklogId" :AssigenedUser="AssigenedUser"
            @CallbackFunction="FetchBacklogListing" :NewTabName="NewTabName" :AssignTabTabName="AssignTab"
            :TabsArray="TabsArray" :AssignSprintTab="tbName"></AssignedUser>
        <BacklogManageTasks v-if="IsManageTasks" :BackLogData="BackLogData" :NewTabName="NewTabName"
            :AssignTabTabName="AssignTab" :AssignSprintTab="tbName">
        </BacklogManageTasks>
        <TaskBulkAction v-if="IsBulkAction" @CloseBulkAction="CloseBulkAction" :BulkActionTaskIds="BulkActionTaskIds"
            :MainProjectData="BuldData" @RefreshTaskList="FetchBacklogListing" Type="Backlog"></TaskBulkAction>
    </section>
</template>
<script>
import Schema from './BacklogSchema'
import AddBacklog from '../../../../components/Modal/AddBacklog.vue'
import CreateSprint from '../../../../components/Modal/CreateSprint.vue'
import AssignedUser from '../../../../components/Modal/AssignedUserModal.vue'
import BacklogManageTasks from '../../../../components/Modal/BacklogManageTasks.vue'
import DataService from '../../../../services/DataService';
import Treeselect from '@riophae/vue-treeselect'
import TaskBulkAction from '../../../../components/Modal/TaskBulkAction.vue'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
export default {
    components: { CreateSprint, AddBacklog, AssignedUser, BacklogManageTasks, Treeselect, TaskBulkAction },
    props: {
        checkPmUser: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array,
            default: () => []
        },
        ProjectOwner: {
            type: String
        }
    },
    data() {
        return {
            BulkActionTaskIds: '',
            IsBulkAction: false,
            isLoading: false,
            options: [
                {
                    id: 'a',
                    label: 'Assigned To Me'
                },
                {
                    id: 'b',
                    label: 'Recently Updated',
                }
            ],
            QuickFilter: null,
            TypeFilter: null,
            EpicFilter: null,
            IsShowTypeCheck: false,
            IsAddBacklog: false,
            IsTask: true,
            IsStory: false,
            IsBug: false,
            BacklogId: null,
            IsTypeDescription: '',
            IsCreateSprint: false,
            ListingData: [],
            widgets: [],
            TotalRecords: 0,
            noRecord: false,
            PageSize: 10,
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            LegendArray: [{
                class: 'text-primary fa fa-check-square mr-1',
                text: (this.$t('Task'))
            },
            {
                class: 'text-danger fa fa-warning ml-2 mr-1',
                text: (this.$t('Issue'))
            },
            {
                class: 'text-success fa fa-film text-success ml-2 mr-1',
                text: (this.$t('Story'))
            }
            ],
            SortBy: '',
            SortExp: '',
            taskId: '',
            searchCondition: '',
            Headers: [],
            Buttons: Schema.buttons,
            listActions: Schema.listActions,
            StatusList: [],
            PriorityData: [],
            CompanyId: null,
            isShowLoader: true,
            PriorityId: null,
            containerName: '',
            blobUrl: '',
            IsAssignedUser: false,
            AssigenedUser: '',
            IsPriority: null,
            IssueTypeId: 'T',
            IsManageTasks: false,
            ProjectId: 0,
            BackLogData: null,
            IsSprintTabType: '',
            ProjectBacklogType: [],
            QuickfilterBacklogType: [{ label: 'Un Assign', id: 'UnAssign' }],
            EpicData: [],
            SprintData: null,
            TemplateName: '',
            SprintButton: true,
            UserType: null,
            IsType: '',
            IsTaskName: '',
            isSavingTask: false,
            UserIds: '',
            tbName: '',
            AssignTab: '',
            FilterPriorityData: [],
            PriorityFilter: null,
            StatusData: [],
            selectedStatus: null,
            BuldData: [],
        }
    },
    watch: {
        NewTabName: {
            handler(newTabName) {
                if (newTabName) {
                    this.updateHeaders(newTabName);
                }
            },
            immediate: true
        },
        TabsArray: {
            handler(newTabsArray) {
                if (newTabsArray && newTabsArray.length > 0 && this.NewTabName) {
                    this.$nextTick(() => {
                        this.updateHeaders(this.NewTabName);
                    });
                }
            },
            immediate: false
        }
    },
    created() {
        var ths = this;
        ths.containerName = ths.GetUserInfo.ContainerName;
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.ProjectId = ths.$route.params.projectId;
        ths.UserType = ths.GetUserInfo.UserType;
        ths.CheckDisabled();
        ths.GetProjectSprint();
        ths.GetProjectDetails();
        ths.StatusDropdown();
        ths.getBlobUrl();
        ths.GetProjectPriority();
        ths.FetchBacklogListing();
        ths.GetProjectBacklogType();
        ths.FetchMemberListing();
        ths.GetEpic();
        if (!ths.Headers || ths.Headers.length === 0) {
            ths.Headers = JSON.parse(JSON.stringify(Schema.TableHeader));
        }
        if (ths.NewTabName) {
            ths.updateHeaders(ths.NewTabName);
        }
    },
    computed: {
        dynamicPlaceholder() {
            return `Enter ${this.$t(this.NewTabName)} Name...`;
        },
        dynamicPlaceholderr() {
            return `${this.$t(this.NewTabName)} Name...`;
        }
    },
    methods: {
        getFilterLimitText(count) {
            return `+${count}`;
        },
        BulkAction() {
            var val = '';
            $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                if (val.length > 0)
                    val += ',';
                val += $(this).val();
            });
            if (val.length > 0) {
                this.BulkActionTaskIds = val;
                this.IsBulkAction = true;
            } else {
                this.ShowAlert(this.$t('Selectanyrecordtodelete'), "failure", true, "Alert");
            }

        },
        CloseBulkAction() {
            this.IsBulkAction = false;
        },
        CommonPriortyUpdate(data, evt) {
            var vm = this;
            var postJSON = {
                ID: data.task_id,
                StatusId: evt.target.value,
                IsFor: 'UPDATE_PROJECT_PRIORTY'
            };
            var objectPostString = JSON.stringify(postJSON);
            DataService.CommonUpdateStatus(objectPostString).then(function (response) {
                if (response.data != null) {
                    if (response.data.status === 'Success') {
                        vm.FetchBacklogListing();
                        vm.ShowAlert(vm.$t("RecordUpdatedSuccessfully"), "success", vm.$t('Alert'));
                    } else {
                        vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                    }
                } else {
                    vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                }

            }, function () {

            });
        },
        updateHeaders(newTabName) {
            var ths = this;
            ths.Headers = JSON.parse(JSON.stringify(Schema.TableHeader));

            if (newTabName && ths.Headers && ths.Headers.length > 0) {
                ths.Headers.forEach(header => {
                    if (newTabName !== 'key') {
                        if (header.COLUMN_NAME === 'key') {
                            header.DISPLAY_NAME = `${ths.$t('Key')} / ${ths.$t(ths.TabsArray.find(t => t.displayCode === "PROJECT_BACKLOG")?.displayName || 'Backlog')} ${ths.$t('Name')}`;
                        }
                        if (header.COLUMN_NAME === 'sprint_name') {
                            if (ths.TabsArray && Array.isArray(ths.TabsArray) && ths.TabsArray.length) {
                                ths.tbName = ths.TabsArray.find(t => t.displayCode === "PROJECT_SPRINT").displayName;
                                header.DISPLAY_NAME = `${ths.$t(ths.tbName?.displayName || 'Sprint Name')}`;
                            }
                        }
                        if (header.COLUMN_NAME === 'Assign') {
                            ths.AssignTab = ths.TabsArray.find(t => t.displayCode === "PROJECT_TEAM").displayName;
                            header.DISPLAY_NAME = `${ths.$t(ths.AssignTab?.displayName || 'Team')} ${ths.$t('Assign')}`;
                        }
                    }
                });
            }
        },
        // CheckDisabled() {
        //     if ((this.UserType == 'CL' || this.UserType == 'NU') && this.checkPmUser) {
        //         return true;
        //     }
        //     else {
        //         if (this.UserType == 'CA' || this.UserType == 'PM') {
        //             return true;
        //         }
        //         else {
        //             return false;
        //         }
        //     }
        // },
        CheckDisabled() {
            const type = this.UserType;
            const hasAccess = this.checkPmUser || this.ProjectOwner;
            const isClient = type === 'CL' || type === 'NU';
            const isAdmin = type === 'CA' || type === 'PM';
            const result = isAdmin || (isClient && hasAccess);
            return result;
        },
        showAssignUser(row) {
            row.ispopover = true;
            this.updateRowData(row);
        },
        hideAssignUser(row) {
            row.ispopover = false;
            this.updateRowData(row);
        },
        updateRowData(updatedRow) {
            const index = this.ListingData.findIndex(row => row.task_id === updatedRow.task_id);
            if (index !== -1) {
                this.$set(this.ListingData, index, updatedRow);
            }
        },
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.ProjectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                debugger
                if (response.data.result != null && response.data.result != '') {
                    vm.BuldData.PLANNED_END_DATE = response.data.result.PROJECTOVERVIEW[0].PLANNED_START_DATE;
                    vm.BuldData.PLANNED_END_DATE = response.data.result.PROJECTOVERVIEW[0].PLANNED_END_DATE;
                    vm.TemplateName = response.data.result.PROJECTOVERVIEW[0].Template_Name;
                    vm.SprintButton = vm.TemplateName == 'Kanban' || 'Scrum' ? false : true;
                }
            });
        },
        FetchTeamListing: function () {
            var ths = this;
            ths.isLoading = true;
            let url = '';
            if (ths.searchCondition !== '') {
                url = `projectId=${ths.projectId}&projectName=${ths.projectName}&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}&${ths.searchCondition}`;
            } else {
                url = `projectId=${ths.projectId}&projectName=${ths.projectName}&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}`;
            }
            DataService.GetTeamListing(url).then((response) => {
                ths.isLoading = false;
                if (response.data?.result?.data?.length > 0) {
                    ths.TotalRecords = response.data.result.data[0].Total_Count;
                    ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
                    ths.CurrentPage = ths.PageNumber;
                    resolve(response.data.result.data);
                }
            });
        },
        FetchMemberListing: async function () {
            var url = `id=${this.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    id: element.value,
                                    label: element.name
                                }
                                this.QuickfilterBacklogType.push(obj);
                            })
                        }
                        else {
                            ths.QuickfilterBacklogType = [];
                        }
                    }
                }
            });
        },
        ShowTypeCheck() {
            this.IsShowTypeCheck = true;
        },
        IsHideTypeCheck() {
            this.IsShowTypeCheck = false;
        },
        TypeCheck(val) {
            var ths = this;
            if (val == 'B') {
                ths.IsTask = false;
                ths.IsBug = true;
                ths.IsStory = false;
                ths.IssueTypeId = 'B';
            } else if (val == 'T') {
                ths.IsTask = true;
                ths.IsBug = false;
                ths.IsStory = false;
                ths.IssueTypeId = 'T';
            } else {
                ths.IsTask = false;
                ths.IsBug = false;
                ths.IsStory = true;
                ths.IssueTypeId = 'S';
            }
        },
        GetProjectPriority() {
            var ths = this;
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            ths.PriorityData = response.data.DATA;
                            ths.PriorityData.forEach(function (item) {
                                var obj = {
                                    id: item.value,
                                    label: item.name
                                }
                                ths.FilterPriorityData.push(obj);
                            });
                            var Pdata = ths.PriorityData.filter(item => item.name === 'Low');
                            if (Pdata.length > 0) {
                                ths.IsPriority = Pdata[0].value;
                            }
                        }
                    }
                }
            })
        },
        async onEnterPressed() {
            var ths = this;
            if (ths.isSavingTask || !ths.IsTypeDescription.trim()) return;
            ths.isSavingTask = true;
            var obj = {
                BackLogId: 0,
                Project_id: ths.$route.params.projectId,
                Subject: ths.IsTypeDescription,
                IssueTypeId: ths.IssueTypeId,
                SprintId: null,
                PriorityId: ths.IsPriority,
                StatusId: 1001,
                UserId: null,
                BackLogDescription: '',
                IsBacklog: true,
                EpicId: null,
                ParentId: null
            }
            await DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
                if (response.data.result.DATA.length > 0) {
                    if (response.data.result.DATA[0].VALUE == 'UPDATE') {
                        ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t(ths.NewTabName)]), "success", true, ths.$t("Alert"));
                    }
                    else if (response.data.result.DATA[0].VALUE == 'EXISTS') {
                        ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t(ths.NewTabName)]), "failure", true, ths.$t("Alert"));
                    }
                    else {
                        ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t(ths.NewTabName)]), "success", true, ths.$t("Alert"));
                    }
                    ths.FetchBacklogListing();
                    ths.$emit('UpdateWidgetTaskData');
                    ths.IsTypeDescription = '';
                    ths.IsShowTypeCheck = false;
                } else {
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            });
            ths.isSavingTask = false;
        },
        getBlobUrl() {
            DataService.GetBlobUrl().then((response) => {
                this.blobUrl = response.data[0].CONFIG_DATA_VALUE;
            }).catch((error) => {
                console.error('Error fetching avatar URL:', error);
            });
        },
        StatusDropdown() {
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response) => {
                if (response.data != null && response.data != "") {
                    vm.StatusList = response.data.result.data;
                    vm.StatusList.forEach(function (item) {
                        var obj = {
                            id: item.STATUS_ID,
                            label: item.STATUS
                        }
                        vm.StatusData.push(obj);
                    });
                }
            });
        },
        SearchBacklog(type) {
            if (type.length > 0) {
                this.IsType = type.join(",");
            } else {
                this.IsType = '';
            }
            this.FetchBacklogListing();
        },
        QuickFilterbacklog(type) {
            var vm = this;
            if (type.length > 0) {
                vm.UserIds = '';
                vm.UserIds = type.join(",");
                vm.FetchBacklogListing();
            }
            else {
                vm.UserIds = '';
                // Only clear assignee filter; keep other selections intact.
                vm.FetchBacklogListing();
            }
        },
        SearchByTaskName() {
            var vm = this;
            vm.FetchBacklogListing();
        },
        ResetFilter() {
            var vm = this;
            vm.TypeFilter = null;
            vm.QuickFilter = null;
            vm.IsType = '';
            vm.IsTaskName = '';
            vm.selectedStatus = null;
            vm.PriorityFilter = null;
            vm.UserIds = '';
            vm.PageNumber = 1;
            vm.FetchBacklogListing();
        },
        SearchFilter() {
            var vm = this;
            vm.PageNumber = 1;
            vm.FetchBacklogListing();
        },
        async FetchBacklogListing(SearchValue = null, SerachType = null) {
            var vm = this;
            if (SerachType === 'TASK_BY_STATUS') vm.selectedStatus = SearchValue;
            if (SerachType === 'TASK_BY_PRIORITY') vm.PriorityFilter = SearchValue;
            if (SerachType === 'TASK_BY_ASSIGN_USER') vm.UserIds = SearchValue;

            const csv = (val) => {
                if (val == null) return '';
                if (Array.isArray(val)) return val.length ? val.join(',') : '';
                return String(val);
            };

            var url = 'controller=Project&action=ProjectBacklog'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {

                    vm.isLoading = true;
                    var url = `ProjectId=${vm.ProjectId}&type=${vm.IsType}&TaskName=${encodeURIComponent(vm.IsTaskName || '')}` +
                        `&UserIds=${vm.UserIds || ''}` +
                        `&statusId=${csv(vm.selectedStatus)}` +
                        `&priority=${csv(vm.PriorityFilter)}&sortBy=${vm.SortBy}&sortExp=${vm.SortExp}&pageSize=${vm.PageSize}&pageNumber=${vm.PageNumber}`;
                    DataService.FetchBacklogListing(url).then((response) => {

                        vm.isLoading = false;
                        if (response.data.result.DATA.length > 0) {
                            vm.ListingData = response.data.result.DATA;
                            vm.TotalRecords = response.data.result.DATA[0]?.TOTAL_RECORDS || 0;
                            vm.TotalPages = Math.max(1, Math.ceil(vm.TotalRecords / vm.PageSize));
                            vm.ListingData.forEach((x) => {
                                if (x.created_at != null) {
                                    x.created_at = new Date(x.created_at);
                                }
                                if (x.modified_at != null) {
                                    x.modified_at = new Date(x.modified_at);
                                }
                                x.epic_id = x.epic_id == null || x.epic_id == 0 ? 0 : x.epic_id;
                                x.ispopover = false;
                                x.AssignUser = x.Assign != null ? x.Assign.split(',') : '';
                            });
                        } else {
                            vm.ListingData = [];
                            vm.TotalRecords = 0;
                        }
                    })
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        renderActions: function () {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Move Backlog':
                        action.isVisible = true;
                        break;
                    case 'Assigned Tasks':
                        action.isVisible = true;
                        break;
                    case 'Edit':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {
                case 'ManageTasks':
                    this.ManageTasks(item)
                    break;
                case 'AssignedTasks':
                    this.commonDeleteData(item.task_id, 'List');
                    break;
                case 'EditProjectBacklog':
                    this.EditProjectBacklog(item.task_id);
                    break;
            }
        },
        ManageTasks(itm) {
            var vm = this;
            vm.BackLogData = itm;
            vm.IsManageTasks = true;
        },
        pagerMethod(value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchBacklogListing();
        },
        commonHeaderButtonClick: function () { },
        commonDeleteData: async function (evt, type) {
            var vm = this;
            var val = "";

            var url = 'controller=Project&action=DeleteBacklog'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.isLoading = true;
                    if (type == 'Head') {
                        if (evt.target.value == undefined) {
                            $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                                if (val.length > 0)
                                    val += ',';
                                val += $(this).val();
                            });
                        }
                        else {
                            val = "";
                        }
                    }
                    else {
                        val = evt;
                    }
                    if (val != null && val != "") {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                            var postJSON = {
                                ids: val,
                                moduleName: "PROJECT",
                                subModuleCode: "PROJECT_DETAIL",
                                refCode: 'Project_backlog'
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                vm.isLoading = false;
                                if (response.data.length > 0) {
                                    if (response.data[0].Status == 'Success') {
                                        if (response.data[0].Code == 'BACKLOG_ASSIGN') {
                                            vm.ShowAlert(vm.$t('proceedingwithdeletion', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                        } else {
                                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                                        }
                                        vm.$emit('UpdateWidgetTaskData');
                                        vm.FetchBacklogListing();
                                    }
                                    else {
                                        vm.ShowAlert(vm.$t('DeletedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                    }
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), "warning", true, vm.$t("Alert"));
                    }
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
            vm.isLoading = false;
        },
        EditProjectBacklog: async function (val) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateBacklog'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.BacklogId = val;
                    vm.IsAddBacklog = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        AddBacklog: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateBacklog'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwnera) {
                    vm.BacklogId = 0;
                    vm.IsAddBacklog = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        CreateSprint: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateSprint'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    this.IsCreateSprint = true;
                    this.IsSprintTabType = 'BackLog';
                    this.SprintData = null;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchBacklogListing();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        AssignedUser: async function (val, users) {
            var vm = this;
            var url = 'controller=Project&action=AddMemberInTask'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.BacklogId = val;
                    vm.AssigenedUser = users;
                    vm.IsAssignedUser = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        GetEpic() {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=PROJECT&type=PROJECT_Epic&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            ths.EpicData = response.data.DATA;
                        }
                    }
                }
            })
        },
        GetProjectBacklogType() {
            var vm = this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_BACKLOG&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach((item) => {
                                var obj = {
                                    id: item.value,
                                    label: item.name
                                }
                                vm.ProjectBacklogType.push(obj);
                            })
                        }
                    }
                }
            })
        },
        BackToList: function () {
            var ths = this;
            ths.$router.push({ name: 'ProjectList' });
        },
        GetProjectSprint() {
            var vm = this;
            vm.SprintData = [];
            var url = `id=&moduleName=PROJECT&type=PROJECT_SPRINT&search=&refId=${vm.ProjectId}`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(item => {
                                var Obj = {
                                    sprint_name: item.name,
                                    sprint_id: item.value
                                }
                                vm.SprintData.push(Obj);
                            })
                        }
                    }
                }
            })
        },
        updateTaskStatus(task_id, sprint_id, isfor) {
            var vm = this;
            var msg = vm.$t("ConfirmUpdateStatusRecord");
            vm.confirmR(
                msg,
                true,
                vm.$t('UpdateCommonStatus'),
                function (result) {
                    var obj = {
                        ID: task_id,
                        StatusId: sprint_id,
                        IsFor: isfor
                    };
                    var objectPostString = JSON.stringify(obj);
                    DataService.CommonUpdateStatus(objectPostString).then((response) => {
                        if (response.data?.status === 'Success') {
                            vm.ShowAlert(vm.$t("RecordUpdatedSuccessfully"), "success", vm.$t('Alert'));
                            if (typeof vm.callbackfunction != 'undefined' && vm.callbackfunction != null) {
                                vm.callbackfunction();
                                vm.$emit('UpdateWidgetTaskData');
                                vm.FetchBacklogListing();
                            }
                        } else {
                            vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                        }
                        vm.FetchBacklogListing();
                    });
                },
                function (result) {
                    vm.FetchBacklogListing();
                }
            );
        },
        updateEpicStatus(task_id, epic_id, isfor) {
            var vm = this;
            var msg = vm.$t("ConfirmUpdateStatusRecord");
            vm.confirmR(
                msg,
                true,
                vm.$t('UpdateCommonStatus'),
                function (result) {
                    var obj = {
                        ID: task_id,
                        StatusId: epic_id,
                        IsFor: isfor
                    };
                    var objectPostString = JSON.stringify(obj);
                    DataService.CommonUpdateStatus(objectPostString).then((response) => {
                        if (response.data?.status === 'Success') {
                            vm.ShowAlert(vm.$t("RecordUpdatedSuccessfully"), "success", vm.$t('Alert'));
                            vm.FetchBacklogListing();
                            if (typeof vm.callbackfunction != 'undefined' && vm.callbackfunction != null) {
                                vm.callbackfunction();
                            }
                        } else {
                            vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                        }
                    });
                },
                function (result) {
                    vm.FetchBacklogListing();
                }
            );
        }
    }
}
</script>
