<template>
  <div class="my-popups">
    <loader :is-visible="isLoading"></loader>
    <div class="modal d-block">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header theme-primary partition-full  d-flex">
            <h4 class="modal-title">{{ $t('Associate') }} {{ $t(NewTabName) }} </h4>
            <button type="button" class="close" v-on:click="CloseStage">
              <em class="fa fa-times" aria-hidden="true"></em>
            </button>
          </div>

          <div class="modal-body">
            <div class="heading-border mb-3">
              <h5 class="h5">
                <span> {{ $t('Stage') }}</span>


                <small class="float-right" v-if="!IsAddStage">
                  <a href="javascript:void(0)" @click="Addstage()" data-toggle-tooltip="tooltip"
                    data-original-title="Add User">
                    <i class="fa fa-plus pr-1"></i>{{ $t('Add') }} {{ $t(NewTabName) }}
                  </a>
                </small>


              </h5>
            </div>

            <div v-if="IsAddStage">
              <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm"
                :mandatorytext='MandatoryString' v-on:OnSubmit="OnSubmit"></dynamic-form>
            </div>
            <div v-else>
              <Form ref="form" v-slot="{ values, meta }">
                <div class="d-flex flex-wrap">
                  <div class="col-md-12 p-0">
                    <div class="row">
                      <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left">

                        <div class="listing">
                          <div class="table-responsive overflow-visible"> <!-- table-fix-header -->
                            <table id="tblStage" class="table table-bordered dt-responsive nowrap mt-0 mb-0">
                              <thead class="thead-bg">
                                <tr>
                                  <th style="width:50px !important;" id="nonresize">
                                    <div class="custom-control custom-checkbox">
                                      <input class="chkItems setcheckall custom-control-input" type="checkbox"
                                        id="chkAll" name="checkbox" data-parent="no" style="display: none;"
                                        v-model="selectAll" v-on:change="checkAllSelected($event)">
                                      <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="chkAll"></label>
                                    </div>
                                  </th>
                                  <th style="width:400px;"><span href="javascript:;">{{ $t(NewTabName) }} {{ $t('Name')
                                      }}</span>
                                  </th>
                                  <th style="width:400px;"><span href="javascript:;">{{ $t(Phase_Name) }} {{ $t('Name')
                                      }}</span>
                                  </th>
                                  <th v-if="ProjectIndusrtyType !== 'Construction'" style="width:240px;"><span
                                      href="javascript:;">{{
                                        $t(Task_Name) }}</span></th>
                                  <th v-if="ProjectIndusrtyType !== 'Construction'" class="text-center"
                                    style="width:120px;"><span href="javascript:;">{{
                                      $t('Task') }} {{ $t('Hour') }}</span></th>
                                  <th style="width:340px;"><span href="javascript:;">{{
                                    $t('StartDate') }}
                                      <!-- ({{ $t('ProjectStartDate')}}: {{ ProjectStartDate }}) -->
                                    </span></th>
                                  <th style="width:340px;"><span href="javascript:;">{{
                                    $t('EndDate') }}
                                      <!--({{ $t('ProjectEndDate') }} : {{ProjectEndDate }}) -->
                                    </span></th>
                                </tr>
                              </thead>
                              <tbody>
                                <tr v-for="(item, index) in AddEditStageListing" v-if="!noRecordForTab" :key="index">
                                  <td>
                                    <div class="custom-control custom-checkbox">
                                      <input class="chkItems setcheckall custom-control-input" :value="item.STAGE_ID"
                                        :disabled="item.START_DATE_SELECTED != null" type="checkbox"
                                        :id="'chkAll_' + index" name="checkbox" data-parent="no" style="display: none;"
                                        v-model="item.selected" @change="PhaseChange(item)">
                                      <label class="custom-control-label universal-custom-control-label pt-1"
                                        :for="'chkAll_' + index"></label>
                                    </div>
                                  </td>
                                  <td>
                                    <input type="text"
                                      :class="{ 'form-control': true, 'highlight-stage': EditStageId === item.STAGE_ID || AddStageId === item.STAGE_ID }"
                                      v-model="item.STAGE_NAME" style="min-width: 120px;" />
                                  </td>
                                  <td>
                                    <input type="text" :class="{ 'form-control': true }" disabled
                                      v-model="item.PHASE_NAME" style="min-width: 120px;" />
                                  </td>
                                  <td v-if="ProjectIndusrtyType !== 'Construction'">
                                    <multiselect
                                      :key="'task-select-' + item.STAGE_ID + '-' + index + '-' + allSelectedTaskIds"
                                      placeholder="Select Task" :max-height="150" v-model="item.NEW_TASK_ID"
                                      label="name" track-by="value" :limit="2" :options="getFilteredTaskList(item)"
                                      :multiple="true" mode="tag" :close-on-select="false" :clear-on-select="false"
                                      :preserve-search="true" :taggable="false" :allow-empty="true"
                                      :show-labels="false">
                                    </multiselect>
                                  </td>
                                  <td v-if="ProjectIndusrtyType !== 'Construction'" class="text-center">
                                    <span class="startspan text-center"
                                      v-if="item.STAGE_HOURS != '' && item.STAGE_HOURS != null">{{ item.STAGE_HOURS
                                      }}</span>
                                    <span class="startspan text-center" v-else>0</span>
                                  </td>
                                  <td>
                                     <div class="input-group table_datepickerfix">
                                       <Field :name="'startdate' + index"
                                         :rules="{ required: item.selected == true ? true : false }"
                                         v-slot="{ errors, changed }">

                                         <v-date-picker :minute-increment="5" class="input-group"
                                           v-model.string="item.START_DATE" @update:modelValue="changed"
                                           :min-date="ProjectStartDate" :max-date="ProjectEndDate">
                                           <template v-slot="{ inputValue, inputEvents, togglePopover }">
                                             <input :placeholder="'MM/DD/YYYY'"
                                               v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                               :value="inputValue" v-on="inputEvents" />
                                             <div @click="togglePopover()" class="input-group-append"><span
                                                 class="input-group-text"><em class="fa fa-calendar"></em></span>
                                             </div>
                                           </template>
                                         </v-date-picker>
                                         <span v-if="errors[0]" :name="'startdate' + index"
                                           class="invalid-feedback d-block">
                                           {{ $t('StartDateReq') }}</span>
                                       </Field>
                                     </div>
                                  </td>
                                   <td>
                                     <div class="input-group table_datepickerfix">
                                       <Field :name="'enddate' + index"
                                         :rules="{ required: item.selected == true ? true : false }"
                                         v-slot="{ errors, changed }">
                                         <v-date-picker :minute-increment="5" class="input-group" v-model.string="item.END_DATE"
                                           @update:modelValue="changed" :min-date="item.START_DATE || ProjectStartDate"
                                           :max-date="ProjectEndDate">
                                           <template v-slot="{ inputValue, inputEvents, togglePopover }">
                                             <input :placeholder="'MM/DD/YYYY'"
                                               v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                               :value="inputValue" v-on="inputEvents" />
                                             <div @click="togglePopover()" class="input-group-append"><span
                                                 class="input-group-text"><em class="fa fa-calendar"></em></span>
                                             </div>
                                           </template>
                                         </v-date-picker>
                                         <span v-if="errors[0]" :name="'enddate' + index"
                                           class="invalid-feedback d-block">{{ $t('EndDateReq') }}</span>
                                       </Field>
                                     </div>
                                   </td>
                                </tr>
                                <tr v-if="noRecordForTab">
                                  <td colspan="4">
                                    <div class="text-center text-danger">{{
                                      $t('NoRecordfound') }}</div>
                                  </td>
                                </tr>
                              </tbody>
                            </table>
                          </div>
                        </div>

                      </div>
                    </div>
                  </div>
                </div>
              </Form>
              <div class="modal-footer">
                <a href="javascript:;" v-on:click="SaveStage($event)" class="btn btn-success formbtn">
                  <i class="fa fa-save"></i> {{ $t('Save') }}
                </a>
              </div>
            </div>


          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import DataService from '../../services/DataService'
export default {
  components: {},
  props: {
    stageList: {
      type: Array,
      required: true
    },
    NewTabName: {
      type: Number,
      required: true
    },
    ProjectIndusrtyType: {
      type: String,
      required: true
    },
    EditStageId: {
      type: Number,
      required: false
    },
    TabsArray: {
      type: Array
    }
  },
  data() {
    return {
      isLoading: false,
      AddStageId: null,
      options: [],
      selectedStage: '',
      ProjectId: null,
      ProjectEndDate: '',
      ProjectStartDate: '',
      TreeValue: null,
      noRecordForTab: false,
      ProjectName: '',
      AddEditStageListing: [],
      MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
      TaskList: [],
      FindalTaskArray: [],
      selectAll: false,
      IsAddStage: false,
      FormSchema: [
        {
          layoutType: "double",
          Data: [
            {
              astype: "TextField",
              label: this.$t('Stage Name'),
              name: "StageName",
              value: "",
              placeholder: this.$t('Enter Stage Name'),
              validationRules: { "required": true, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t('Project Phase'),
              value: "",
              config: {
                options: []
              },
              placeholder: this.$t('Select Phase Name'),
              validationRules: { "required": false, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t('Type'),
              value: "",
              disabled: true,
              config: {
                options: []
              },
              placeholder: this.$t('Select Type'),
              validationRules: { "required": false, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t('Status'),
              name: "Tag",
              value: "",
              config: {
                options: []
              },
              placeholder: this.$t('Select Status'),
              validationRules: { "required": true, max: 100 },
            },
            {
              astype: "ColorField",
              label: this.$t('Color Code'),
              name: "Color Code",
              value: "",
              placeholder: "",
              validationRules: {
                "required": true
              },
              disabled: false,
            }
          ]
        },
        {
          layoutType: "single",
          Data: [
            {
              astype: "TextAreaField",
              label: this.$t('Description'),
              name: "Description",
              value: "",
              validationRules: { "required": false, max: 4000 },
              config: {
                rows: 5
              }
            }
          ]
        }
      ],
      buttons: [
        {
          type: "submit",
          class: "btn btn-success",
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: true,
        },
        {
          type: "button",
          class: "btn btn-danger",
          text: "<i class='fa fa-close pr-2'></i>Cancel",
          onClick: this.CloseAddStage,
        },
      ],
      Phase_Name: '',
      Task_Name: '',
      _isFetchingAddEditStage: false
    }
  },
  computed: {
    allSelectedTaskIds() {
      const selectedIds = [];
      this.AddEditStageListing.forEach(stage => {
        if (stage.NEW_TASK_ID && Array.isArray(stage.NEW_TASK_ID) && stage.NEW_TASK_ID.length > 0) {
          stage.NEW_TASK_ID.forEach(task => {
            const taskId = (task && typeof task === 'object' && task.value !== undefined)
              ? String(task.value)
              : String(task);
            if (taskId && taskId !== 'null' && taskId !== 'undefined') {
              selectedIds.push(taskId);
            }
          });
        }
      });
      return selectedIds.sort().join(',');
    }
  },
  created: function () {
    var ths = this;
    const stageName = ths.TabsArray.find(t => t.displayCode === "PROJECT_STAGE")?.displayName || "Stage Name";
    const phaseName = ths.TabsArray.find(t => t.displayCode === "PROJECT_PHASE")?.displayName || "Phase";
    const taskName = ths.TabsArray.find(t => t.displayCode === "PROJECT_TASKS")?.displayName || "Tasks Name";
    ths.Phase_Name = ths.$t(phaseName);
    ths.Task_Name = ths.$t(taskName);
    ths.FormSchema[0].Data[0].label = ths.$t(stageName);
    ths.FormSchema[0].Data[0].placeholder = `Enter ${ths.$t(stageName)}`;
    ths.FormSchema[0].Data[1].label = ths.$t(ths.Phase_Name);
    ths.FormSchema[0].Data[1].placeholder = `Enter ${ths.$t(ths.Phase_Name)}`;
    ths.NewTabName = ths.$t(stageName || "Project Stage");
    ths.ProjectId = ths.$route.params.projectId;
    ths.ProjectOverview();
    ths.refreshStageData();
  },
  methods: {
    refreshStageData: async function () {
      var vm = this;
      await vm.FetchTaskListByProjectId();
      await vm.FetchAddEditStage();
    },
    getFilteredTaskList(currentStage) {
      const selectedTaskIds = new Set();
      this.AddEditStageListing.forEach(stage => {
        if (stage.STAGE_ID === currentStage.STAGE_ID) {
          return;
        }
        if (stage.NEW_TASK_ID && Array.isArray(stage.NEW_TASK_ID) && stage.NEW_TASK_ID.length > 0) {
          stage.NEW_TASK_ID.forEach(task => {
            const taskId = (task && typeof task === 'object' && task.value !== undefined)
              ? String(task.value)
              : String(task);
            if (taskId && taskId !== 'null' && taskId !== 'undefined') {
              selectedTaskIds.add(taskId);
            }
          });
        }
      });
      return this.TaskList.filter(task => {
        const taskId = String(task.value);
        const isSelectedInCurrentStage = currentStage.NEW_TASK_ID &&
          Array.isArray(currentStage.NEW_TASK_ID) &&
          currentStage.NEW_TASK_ID.some(selectedTask => {
            const selectedTaskId = (selectedTask && typeof selectedTask === 'object' && selectedTask.value !== undefined)
              ? String(selectedTask.value)
              : String(selectedTask);
            return selectedTaskId === taskId;
          });

        return !selectedTaskIds.has(taskId) || isSelectedInCurrentStage;
      });
    },
    isDisabled(id) {
      this.selectedStage = this.stageList.some(p => p.STAGE_ID === id);
      return this.stageList.some(p => p.STAGE_ID === id);
    },
    FetchTaskListByProjectId: async function () {
      var vm = this;
      var url = `id=${this.ProjectId}&refId=`;
      await DataService.GetTaskDDLData(url).then(function (response) {
        vm.FindalTaskArray = [];
        vm.TaskList = [];
        if (response.data != '' && response.data.DATA.length > 0) {
          response.data.DATA.forEach((item) => {
            var Obj = {
              value: item.value || item.id,
              name: item.label || item.name || item.text
            };
            vm.TaskList.push(Obj);
          });
        }
      });
    },
    ProjectOverview: async function () {
      var vm = this;
      var params = `projectId=${this.ProjectId}`;
      await DataService.ProjectOverview(params).then(function (response) {
        if (response.data != null > 0) {
          vm.ProjectStartDate = new Date(response.data.planneD_START_DATE)
          vm.ProjectEndDate = new Date(response.data.planneD_END_DATE)
          vm.ProjectName = response.data.projecT_NAME;
        }
      });
    },
    CloseStage: function () {
      this.$parent.IsAddAssociateStage = false
    },
    checkAllSelected(evt) {
      const isChecked = evt.target.checked;
      this.AddEditStageListing.forEach(item => {
        if (item.START_DATE_SELECTED == null) {
          item.selected = isChecked;
        }
      });
      this.selectAll = isChecked;
      this.$nextTick(() => {
        this.$refs.form.validate();
      });
    },
    PhaseChange() {
      const allSelected = this.AddEditStageListing.filter(it => it.START_DATE_SELECTED == null).every(it => it.selected);
      this.selectAll = allSelected;
    },
    FetchAddEditStage: function () {
      var ths = this;
      if (ths._isFetchingAddEditStage) {
        return;
      }
      ths._isFetchingAddEditStage = true;
      var url = `projectId=${ths.ProjectId}`;
      DataService.FetchAddEditStage(url).then((response) => {
        if (response.data.result.DATA.length > 0) {
          ths.AddEditStageListing = response.data.result.DATA.map(item => ({
            ...item,
            selected: false,
            NEW_TASK_ID: [] // Initialize as empty array for multiselect
          }));
          ths.AddEditStageListing.forEach(item => {
            item.CheckedValue = false;
            if (item.START_DATE != null) {
              // Edit case - convert TASK_ID to array of task objects
              item.START_DATE = new Date(item.START_DATE);
              item.END_DATE = new Date(item.END_DATE);
              item.selected = false;
              item.CheckedValue = false;
              item.START_DATE_SELECTED = 'selected';
              this.selectedStage = item;
              // Handle TASK_ID - could be single value, array, or comma-separated string
              var taskIds = [];
              if (item.TASK_ID != null && item.TASK_ID !== '') {
                if (Array.isArray(item.TASK_ID)) {
                  taskIds = item.TASK_ID.map(id => String(id));
                } else if (typeof item.TASK_ID === 'string' && item.TASK_ID.includes(',')) {
                  taskIds = item.TASK_ID.split(',').map(id => id.trim()).filter(id => id !== '');
                } else {
                  taskIds = [String(item.TASK_ID)];
                }

                // Map task IDs to task objects from TaskList - ensure exact object match
                // Create a map for faster lookup to get exact object references
                var taskMap = {};
                ths.TaskList.forEach(task => {
                  taskMap[String(task.value)] = task;
                });

                // Get exact objects from TaskList to ensure vue-multiselect can track them correctly
                item.NEW_TASK_ID = taskIds
                  .map(id => taskMap[String(id)])
                  .filter(task => task != null && task !== undefined);
              } else {
                item.NEW_TASK_ID = [];
              }
            } else {
              // New case - ensure it's an empty array
              item.NEW_TASK_ID = [];
            }
          })
          // Move the matching record to first position if EditPhaseId matches
          if (ths.EditStageId != null) {
            var matchIndex = ths.AddEditStageListing.findIndex(item => item.STAGE_ID === ths.EditStageId);
            if (matchIndex > 0) {
              var matchedItem = ths.AddEditStageListing.splice(matchIndex, 1)[0];
              ths.AddEditStageListing.unshift(matchedItem);
            }
          }
          ths.noRecordForTab = false;
        } else {
          ths.noRecordForTab = true;
        }
      }).finally(() => {
        ths._isFetchingAddEditStage = false;
      });
    },
    SaveStage: function () {
      var vm = this;
      var postString = [];
      vm.$refs.form.validate().then((result) => {
        if (result) {
          // Validate: if user entered any date without selecting checkbox, show error and stop
          const hasDatesWithoutSelection = vm.AddEditStageListing.some(item => !item.selected && item.START_DATE_SELECTED == null && (item.START_DATE || item.END_DATE));
          if (hasDatesWithoutSelection) {
            vm.ShowAlert("Please select the checkbox for rows where dates are entered", "warning", true, vm.$t("Alert"));
            return;
          }

          var selectedArray = vm.AddEditStageListing.filter(item => item.selected);
          var filteredArray = vm.AddEditStageListing.filter(item => item.selected || item.START_DATE_SELECTED == 'selected');
          if (selectedArray.length === 0 && filteredArray.length === 0) {
            vm.ShowAlert("Please check at least one checkbox", "warning", true, vm.$t("Alert"));
            return;
          }

          if (vm.ProjectIndusrtyType !== 'Construction') {
            var missingTasks = [];
            $.each(filteredArray, function (idx, item) {
              var hasTasks = item.NEW_TASK_ID && Array.isArray(item.NEW_TASK_ID) &&
                item.NEW_TASK_ID.length > 0;
              if (!hasTasks) {
                missingTasks.push(item.STAGE_NAME || ('Stage ' + (idx + 1)));
              }
            });

            if (missingTasks.length > 0) {
              vm.ShowAlert("Please select at least one task for: " + missingTasks.join(', '), "warning", true, vm.$t("Alert"));
              return;
            }
          }

          const invalidDates = filteredArray.some(item => {
            return item.START_DATE && item.END_DATE && new Date(item.END_DATE) < new Date(item.START_DATE);
          });

          if (invalidDates) {
            vm.ShowAlert(vm.$t('Enddatecannotbeearlierthanstartdate'), "warning", true, vm.$t("Alert"));
            return false;
          }
          $.each(filteredArray, function (idx, item) {
            // Extract task IDs from multiselect array
            var taskIds = [];
            if (item.NEW_TASK_ID && Array.isArray(item.NEW_TASK_ID) && item.NEW_TASK_ID.length > 0) {
              // Extract value property from selected task objects
              taskIds = item.NEW_TASK_ID.map(task => {
                // Handle both object format {value, name} and direct value
                return (task && typeof task === 'object' && task.value !== undefined) ? task.value : task;
              }).filter(id => id != null && id !== '');
            } else if (item.NEW_TASK_ID && !Array.isArray(item.NEW_TASK_ID)) {
              // Fallback for single value
              taskIds = [item.NEW_TASK_ID].filter(id => id != null && id !== '');
            }

            var obj = {
              StageId: item.STAGE_ID,
              ProjectId: vm.ProjectId,
              SD: item.START_DATE,
              ED: item.END_DATE,
              TaskId: taskIds.length > 0 ? taskIds.join(',') : null,
              StageName: item.STAGE_NAME
            }
            postString.push(obj);
          });
          let clashDates = false;
          if (postString.length > 0) {
            $.each(postString, function (idx, item) {
              if (idx > 0) {
                var chkData = $.grep(postString, function (element) {
                  return (
                    (new Date(element.SD).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                      new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                    (new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.SD).setHours(0, 0, 0, 0) &&
                      new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                    (new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                      new Date(element.ED).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0))
                  );
                });
                if (chkData.length > 1) {
                  clashDates = true;
                }
              }
            });
          }
          if (!clashDates) {
            var objectPostString = JSON.stringify(postString);
            DataService.SaveStage(objectPostString).then((response) => {
              vm.isLoading = false;
              if (response.data.status == 'Success') {
                vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                this.$parent.IsAddAssociateStage = false
                vm.$parent.FetchProjectStageListing();
              }
              else if (response.data.status == 'Failiure') {
                vm.isLoading = false;
                vm.ShowAlert(vm.$t('Duplicate stage name it should be different!'), "warning", true, vm.$t("Alert"));
              }
              else {
                vm.ShowAlert(vm.$t('AddedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
              }
            });
          } else {
            vm.ShowAlert(vm.$t('DateValidationOnStage'), "warning", true, vm.$t("Alert"));
          }
        }
      });
      //}
    },
    async Addstage() {
      var vm = this;
      var url = 'controller=Project&action=AddUpdatePhase'
      await DataService.CheckPrivilege(url).then(async function (response) {
          if (response.data) {
              vm.IsAddStage = true;
              vm.BindPhaseDropdown();
              vm.GetStageType();
              vm.GetStatusList();
          }
          else {
              vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
          }
      }); 
    },
    CloseAddStage() {
     this.FormSchema[0].Data[0].value='',
     this.FormSchema[0].Data[1].value='',
     this.FormSchema[0].Data[3].value='1001',
     this.FormSchema[1].Data[0].value='',
      this.IsAddStage = false;
    },
    BindPhaseDropdown: function () {
      var ths = this;
      ths.FormSchema[0].Data[1].config.options=[];
      var url = `id=&moduleName=&type=PHASE_NAME&search=&refId=${this.ProjectId}`;
      DataService.GetDDLData(url).then((response) => {
        if (response.data.DATA.length > 0) {
          response.data.DATA.forEach((item) => {
            let obj = {
              name: item.name,
              value: item.value
            }
            ths.FormSchema[0].Data[1].config.options.push(obj);
          })
          ths.$refs.AssignTagForm.UpdateKeyValue();
        }
      })
    },
    GetStageType: function () {
      var ths = this;
      DataService.GetStageType().then((response) => {
        if (response.data.result.DATA.length > 0) {
          response.data.result.DATA.forEach((item) => {
            let obj = {
              name: item.MODULE_NAME,
              value: item.MODULE_NAME
            }
            ths.FormSchema[0].Data[2].config.options.push(obj);
            const statusField = this.FormSchema[0].Data[2];
            const activeOption = statusField.config.options.find(o => o.name.toLowerCase() === "project");
            if (activeOption) {
              statusField.value = activeOption.value;
            } else if (statusField.config.options.length > 0) {
              statusField.value = statusField.config.options[0].value;
            }

          })
          ths.$refs.AssignTagForm.UpdateKeyValue();
        }
      })
    },
    GetStatusList: async function () {
      var vm = this;
      vm.FormSchema[0].Data[3].config.options=[];
      var params = `statusType=${"Project"}&hasglobal=${false}`;
      DataService.GetStatusList(params).then(async (response) => {
        if (response.data.length > 0) {
          var statusList = [];
          statusList = response.data;
          statusList.forEach((item) => {
            var obj = {
              name: item.STATUS,
              value: item.STATUS_ID
            }
            vm.FormSchema[0].Data[3].config.options.push(obj);


            const statusField = this.FormSchema[0].Data[3];
            const activeOption = statusField.config.options.find(o => o.name.toLowerCase() === "active");
            if (activeOption) {
              statusField.value = activeOption.value;
            } else if (statusField.config.options.length > 0) {
              statusField.value = statusField.config.options[0].value;
            }

          })
          vm.$refs.AssignTagForm.UpdateKeyValue();
        }
      });
    },
    OnSubmit: function () {
      var vm = this;
      var postString = {
        StageId: 0,
        StageName: vm.FormSchema[0].Data[0].value,
        PhaseId: vm.FormSchema[0].Data[1].value,
        StatusId: vm.FormSchema[0].Data[3].value,
        StageDescription: vm.FormSchema[1].Data[0].value,
        TypeCode: vm.FormSchema[0].Data[2].value,
        ColorCode: vm.FormSchema[0].Data[4].value
      };

      var objectPostString = JSON.stringify(postString);
      DataService.AddSaveStage(objectPostString).then(async (response) => {

        vm.isLoading = false;
        if (response.data.result.DATA[0].VALUE != null && response.data.result.DATA[0].VALUE != '' && response.data.result.DATA[0].VALUE != undefined) {

          vm.AddStageId = response.data.result.DATA[0].VALUE;
          vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
          vm.CloseAddStage();
          vm.refreshStageData();

        } else if (response.data.result.DATA[0].VALUE == 'UPDATE') {
          vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
        } else {
          vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t(vm.NewTabName)]), "warning", true, vm.$t("Alert"));
        }
      })
    },
  }
}
</script>
