<template>
    <div class="my-popups">
      <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered">
          <div class="modal-content">
  
            <!-- Header -->
            <div class="modal-header theme-primary partition-full d-flex">
              <h4 class="modal-title">{{ Type }}</h4>
              <button type="button" class="close" @click="onCloseAddModal">
                <em class="fa fa-times" aria-hidden="true"></em>
              </button>
            </div>
  
            <!-- Body -->
            <div class="modal-body">
              <tg-list
                ref="tgList"
                :listType="['List']"
                :IsShowAction="false"
                :showCheckBox="false"
                ModuleName="PROJECT"
                SubModuleCode="ProjectEnvirement"
                IdentityColumn="environment_id"
                :ListData="fullList"
                :HeaderData="Headers"
                :widgets="widgets"
                :TotalRecords="TotalRecords"
                :SearchFields="false"
                :LegendArray="legendArray"
                :PageSize="pageSize"
                :CurrentPageNumber="pageNum"
                :SortExp="SortExp"
                :SortBy="SortBy"
                :RenderRowActionMethod="renderActions"
                :NorecordfoundText="$t('NoRecordfound')"
                :ListDataCallBackFunction="listDataCallback"
                @ActionButtonClick="actionButtonClick"
                @SortdataButtonClick="sortdata"
                @PagerButtonClick="pagerMethod"
              >
                <template v-slot:slotdata="{ data }">
                    <template v-if="data.column.COLUMN_NAME === 'planned_start_date'">        
                        <span :title="$d(new Date(data.row.planned_start_date))">
                          {{ $d(new Date(data.row.planned_start_date))  }} </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME === 'planned_end_date'">        
                        <span :title="$d(new Date(data.row.planned_end_date))">
                          {{ $d(new Date(data.row.planned_end_date))  }} </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME === 'priority_name'">        
                        <span class="text-center text-white d-block" :title=" data.row.priority_name"
                          :style="{ backgroundColor: data.row.color_code}">
                          {{  data.row.priority_name  }} </span>
                    </template>
                  <template v-if="data.column.COLUMN_NAME === 'status_name'">
                    <listing-status :title="data.row.status_name"
                      :isfor="'PROJECTTASKDETAIL'"
                      ref="updatestatus"
                      :dataid="rowIdentity(data.row)"
                      data-controller="Task"
                      :statuslist="StatusList"
                      :item="data"
                      :parentid="rowIdentity(data.row)"
                      dataController="Project"
                      dataAction="BacklogStatusUpdate"
                      :dataselected="data.row.status_name"
                      :callbackfunction="listDataCallback"
                      :isselectedvaluestring="true"
                    />
                  </template>  
                </template>  
              </tg-list>
            </div>  
          </div>
        </div>
      </div>
    </div>
  </template>
  
  <script>
  import DataService from '../../services/DataService';
  export default {
  props: {
    Id: {
      type: [String, Number],
      required: true
    },
    Type: {
      type: String,
      required: true
    }
  },
  data() {
    return {
      EnvironmentId:0,
      isTaskModal:false,
      legendArray: [],
      searchFieldsEmpty: [],
      EnvireomentData: null,
      isLoading: false,
      widgets: [],
      envirementNameFilter: '',
      selectedStatus: null,
      isAddEnvironmentModal: false,
      statusOptions: [],
      StatusList: [],
      fullList: [],
      TotalRecords: 0,
      CompanyId: null,
      _fetchInProgress: false,
      _pendingFetch: false,
      listActions:[{
        title: 'Edit',
        callbackfunction: 'Edit',
        icon: 'fa fa-pencil action-icon',
        additionalSpan: ''
    }, {
        title: 'Delete',
        callbackfunction: 'Delete',
        icon: 'fa fa-trash-o text-danger',
        additionalSpan: ''
    }],
      Headers: [
        {
          COLUMN_NAME: 'task_name',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Task Name',
          DISPLAY_ORDER: 1
        },
        {
          COLUMN_NAME: 'NAME',
          DATA_TYPE: 'string',
          SORTABLE: false,
          VISIBLE: true,
          DISPLAY_NAME: 'Component Name',
          DISPLAY_ORDER: 4
        },
        {
          COLUMN_NAME: 'planned_start_date',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Start Date',
          DISPLAY_ORDER: 2,
          settings: {
            isInSlot: true
          }
        },
        {
          COLUMN_NAME: 'planned_end_date',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'End Date',
          DISPLAY_ORDER: 2,
          settings: {
            isInSlot: true
          }
        },
        {
          COLUMN_NAME: 'priority_name',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Priority',
          DISPLAY_ORDER: 2,
          settings: {
            isInSlot: true
          }
        },
        {
          COLUMN_NAME: 'status_name',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Status',
          DISPLAY_ORDER: 2,
          settings: {
            isInSlot: true
          }
        }
        
      ],
      headerButtons: [],
      pageSize:10,
      pageNum: 1,
      SortBy: '',
      SortExp: ''
    }
  },
  created() {
    if (this.GetUserInfo && this.GetUserInfo.CompanyId != null) {
      this.CompanyId = this.GetUserInfo.CompanyId
    }
    
    const header = this.Headers?.find(x => x.COLUMN_NAME === "NAME");
    if (header) {
    header.DISPLAY_NAME = `${this.Type} Name`;
    }
    this.FetchData()
    this.bindStatusOptions()
  },
  methods: {
    OpenTaskModel(id){
      this.EnvironmentId=id;
      this.isTaskModal=true;
    },
    rowIdentity(row) {
      if (!row) return 0
      var id = row.environment_id != null ? row.environment_id : row.ENVIRONMENT_ID != null ? row.ENVIRONMENT_ID : row.ID != null ? row.ID : row.id
      var n = Number(id)
      return isNaN(n) ? 0 : n
    },
    listDataCallback() {
      this.FetchData()
    },
    getFilterLimitText(count) {
      return `+${count}`
    },
    statusIdsCsv(val) {
      var ids = this.normalizeSelectIds(val)
      return ids.length ? ids.join(',') : ''
    },
    normalizeSelectIds(value) {
      if (value == null) return []
      var arr = Array.isArray(value) ? value : [value]
      return arr
        .map(function (v) {
          if (v == null) return null
          if (typeof v === 'object') return v.value != null ? v.value : (v.id != null ? v.id : null)
          return v
        })
        .filter(function (v) { return v !== null && v !== '' })
    },
    renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Edit':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
    pagerMethod: function (value) {
      if (!value) return
      this.pageSize = value.PageSize != null ? value.PageSize : this.pageSize
      this.pageNum = value.PageNumber != null ? value.PageNumber : this.pageNum
      this.FetchData()
    },
    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {
          case 'Delete':
              this.deleteSelected(this.rowIdentity(item));
              break;
              case 'Edit':
              this.Edit(item);
              break;
      }
        },
        Edit(item){
          this.EnvireomentData=item;
          this.isAddEnvironmentModal=true;
        },
    sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.pageNum = 1
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
    SearchByEnvirementName() {
      this.pageNum = 1
      this.FetchData()
    },
    FetchData(searchValue = null, searchType = null) {
      var ths = this
      
      if (searchType === 'ENVIRONMENT_BY_STATUS') {
        ths.selectedStatus = searchValue
        ths.pageNum = 1
      }
      if (ths._fetchInProgress) {
        ths._pendingFetch = true
        return
      }
      ths._fetchInProgress = true
      ths.isLoading = true
      const taskName = (ths.envirementNameFilter || '').trim()
      const statusParam = ths.statusIdsCsv(ths.selectedStatus)
      const params = `projectId=${ths.$route.params.projectId}
            &taskName=${encodeURIComponent(taskName)}
            &RefId=${ths.Id}
            &type=${ths.Type.trim()}
            &sortBy=${ths.SortBy}
            &sortExp=${ths.SortExp}
            &pageSize=${ths.pageSize}
            &pageNum=${ths.pageNum}`;
      DataService.GetComponetAndEnvirementBasedTask(params).then((response) => {
        
        ths.fullList = response && response.data && response.data.result && response.data.result.DATA || [];
        if ( ths.fullList.length > 0) {
         //= rows
          ths.TotalRecords =  ths.fullList[0].TotalRecords != null ?  ths.fullList[0].TotalRecords :  ths.fullList.length
        } else {
          ths.fullList = []
          ths.TotalRecords = 0
        }
      }).catch(() => {
        ths.fullList = []
        ths.TotalRecords = 0
      }).finally(() => {
        ths.isLoading = false
        ths._fetchInProgress = false
        if (ths._pendingFetch) {
          ths._pendingFetch = false
          ths.FetchData()
        }
      })
    },
    bindStatusOptions: function () {
      var vm = this
      if (vm.CompanyId == null && vm.GetUserInfo && vm.GetUserInfo.CompanyId != null) {
        vm.CompanyId = vm.GetUserInfo.CompanyId
      }
      var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
      DataService.StatusListing(url).then((response) => {
        if (response.data != null && response.data !== '') {
          vm.StatusList = response.data.result.data
          vm.statusOptions = []
          vm.StatusList.forEach(function (item) {
            vm.statusOptions.push({
              id: item.STATUS_ID,
              label: item.STATUS
            })
          })
        }
      })
    },
    clearFilters() {
      this.envirementNameFilter = ''
      this.selectedStatus = null
      this.pageNum = 1
      this.FetchData()
    },
    openAddModal() {
      this.EnvireomentData = null
      this.isAddEnvironmentModal = true
    },
    onCloseAddModal() {
      this.Id=null;
      this.$parent.isTaskModal=false;
    },
    goBackToList() {
      this.$router.push({ name: 'ProjectList' })
    },
    deleteSelected: async function (id) {
      var val = ''
      var vm = this
      if (id == null || id === '') {
        $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
          if (val.length > 0) val += ','
          val += $(this).val()
        })
      } else {
        val = String(id)
      }
      if (val != null && val !== '') {
        vm.confirmR(vm.$t('ConfirmDelete'), true, (vm.$t('Delete') + '  ' + vm.$t('Group')), function () {
          vm.isLoading = true
          var postJSON = {
            ids: val,
            moduleName: 'PROJECT',
            refCode: 'TALYGEN_ENVIROMENT'
          }
          var objectPostString = JSON.stringify(postJSON)
          DataService.CommonCommonDelete(objectPostString).then(function (response) {
            vm.isLoading = false
            if (response.data.length > 0) {
              if (response.data[0].Status === 'Success') {
                vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Enviroment')]), 'success', true, vm.$t('Alert'))
                vm.FetchData()
              } else {
                vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Enviroment')]), 'failure', true, vm.$t('Alert'))
              }
            } else {
              vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Enviroment')]), 'failure', true, vm.$t('Alert'))
            }
          }).catch(function () {
            vm.isLoading = false
            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Enviroment')]), 'failure', true, vm.$t('Alert'))
          })
        })
      } else {
        vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), 'failure', true, vm.$t('Alert'))
      }
    }
  }
}
  </script>
  