<template>
  <div class="my-popups">
    <loader :is-visible="isLoading"></loader>
    <div class="modal d-block">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header theme-primary partition-full  d-flex">
            <h4 class="modal-title">{{ $t('Project Details') }}</h4>
            <button type="button" class="close" @click="Close">
              <em class="fa fa-times" aria-hidden="true"></em>
            </button>
          </div>
          <div class="modal-body">
            <div class="row" v-for="(item, idx) in ProjectDetailData" :key="idx">
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.PROJECT_NAME">
                    <b>{{ $t('ProjectName') }}:</b>
                    {{ item.PROJECT_NAME }}
                  </label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.PROJECT_MODE"><b>{{ $t('ProjectMode') }}:</b> {{ item.PROJECT_MODE }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group" :title="item.STATUS_NAME">
                  <label><b>{{ $t('Status') }}: </b>
                    <span class="badge h-25" :style="{ backgroundColor: item.status_bg_color }">{{
                      item.STATUS_NAME }}</span>
                  </label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.PLANNED_START_DATE != null ? $d(item.PLANNED_START_DATE) : '--'"><b>{{
                    $t('PlanStartDate') }}:</b>
                    {{ item.PLANNED_START_DATE != null ? $d(item.PLANNED_START_DATE) : '--' }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.PLANNED_END_DATE != null ? $d(item.PLANNED_END_DATE) : '--'"><b>{{
                    $t('PlanEndDate') }}:</b>
                    {{ item.PLANNED_END_DATE != null ? $d(item.PLANNED_END_DATE) : '--' }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.FIRST_BUILD_ON != null ? $d(item.FIRST_BUILD_ON) : 'N/A'"><b>{{ $t('LastBilledOn')
                      }}:</b>
                    {{ item.FIRST_BUILD_ON != null ? $d(item.FIRST_BUILD_ON) : 'N/A' }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group" :title="item.HOURS_SPENT">
                  <label><b>{{ $t('TimeTracked') }}:</b> {{ item.HOURS_SPENT }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="convertSecondsToHHMMSS(item.ESTIMATED_HOURS * 3600)"><b>{{ $t('TotalHours') }}:</b>
                    {{ convertSecondsToHHMMSS(item.ESTIMATED_HOURS * 3600) }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.ESTIMATED_HOURS * 3600 < item.HOURS_SPENT ? '00:00 Hrs' :
                    convertSecondsToHHMMSS(item.ESTIMATED_HOURS * 3600 - item.HOURS_SPENT)"><b> {{
                            $t('TotalHoursLeft') }}:</b>
                    {{
                      item.ESTIMATED_HOURS * 3600 < item.HOURS_SPENT ? '00:00 Hrs' :
                        convertSecondsToHHMMSS(item.ESTIMATED_HOURS * 3600 - item.HOURS_SPENT) }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.IndustryType_Name"><b>{{ $t('IndustryType_Name') }}:</b> {{
                    item.IndustryType_Name }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.Template_Name"><b>{{ $t('Template_Name') }}:</b> {{ item.Template_Name }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.PROJECT_MANAGER"><b>{{ $t('PROJECT_MANAGER') }}:</b>
                    {{
                      item.PROJECT_MANAGER ? item.PROJECT_MANAGER : 'N/A'
                    }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.PROJECT_CREATED_BY"><b>{{ $t('CREATED_BY') }}:</b> {{ item.PROJECT_CREATED_BY
                    }}</label>
                </div>
              </div>
              <div class="col-md-6 col-lg-4 detailsfix">
                <div class="form-group">
                  <label :title="item.Project_Owner_Name"><b>{{ $t('ProjectOwner') }}:</b> {{
                    item.Project_Owner_Name == null ? 'N/A' : item.Project_Owner_Name }}</label>
                </div>
              </div>
              <div class="col-md-12 col-lg-12">
                <div class="form-group descbx">
                  <label :title="cleanText(item.PROJECT_DESCRIPTION)">
                    <b>{{ $t('Description') }}:</b>
                    {{ cleanText(item.PROJECT_DESCRIPTION) }}
                  </label>
                </div>
              </div>

            </div>
            <button type="button" class="btn btn-danger mr-3 mb-2" style="float: right;" @click="Close">
              <em class="fa fa-close pr-2"></em> {{ $t('Close') }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import DataService from '../../services/DataService';
export default {
  props: {
    projectId: {
      type: Number,
      require: true,
    },
  },
  data() {
    return {
      isLoading: false,
      limit: 50,
      showMore: {},
      charLimit: 150,
      showMoreDescription: {},
      showMoreProjectName: {},
      ProjectDetailData: [],
      TemplateId: 0,
      IndustryTypeId: 0,
      IsAIAnalysis: false,
      Key: 0,
      secondsPerMinute: 60,
      minutesPerHour: 60,
    }
  },
  created() {
    this.GetProjectDetails();
  },
  methods: {
    cleanText(text) {
      return text ? text.replace(/<[^>]*>/g, '') : 'N/A';
    },
    getShortText(text) {
      const cleaned = this.cleanText(text);
      return cleaned.slice(0, this.charLimit);
    },
    getRemainingText(text) {
      const cleaned = this.cleanText(text);
      return cleaned.slice(this.charLimit);
    },
    needsTruncate(text) {
      const cleaned = this.cleanText(text);
      return cleaned.length > this.charLimit;
    },
    toggleReadMoreProjectName(id) {
      this.$set(this.showMoreProjectName, id, !this.showMoreProjectName[id]);
    },
    toggleReadMoreDescription(id) {
      this.$set(this.showMoreDescription, id, !this.showMoreDescription[id]);
    },
    GetProjectDetails: async function () {      
      var vm = this;
      vm.isLoading = true;
      var params = `projectId=${vm.projectId}`;
      await DataService.GetProjectDetails(params).then(function (response) {
        if (response.data.result != null && response.data.result != '') {
          vm.ProjectDetailData = [];
          vm.ProjectDetailData.push(response.data.result.PROJECTOVERVIEW[0]);
          vm.ProjectDetailData.forEach((item) => {
            if (item.PLANNED_END_DATE != null || item.PLANNED_END_DATE != '') {
              item.PLANNED_END_DATE = new Date(item.PLANNED_END_DATE)
            }
            if (item.PLANNED_START_DATE != null || item.PLANNED_START_DATE != '') {
              item.PLANNED_START_DATE = new Date(item.PLANNED_START_DATE)
            }
            if (item.CREATED_AT != null || item.CREATED_AT != '') {
              item.CREATED_AT = new Date(item.CREATED_AT)
            }
            if (item.FIRST_BUILD_ON != null) {
              item.FIRST_BUILD_ON = new Date(item.FIRST_BUILD_ON)
            }
            if (item.project_analysis == null) {
              item.project_analysis = 'No Analysis';
            }
            else {
              vm.AIAnalysis = item.project_analysis;
            }
            vm.TemplateId = item.Template_id;
            vm.IndustryTypeId = item.IndustryType_id;
            vm.IsAIAnalysis = true;
            vm.Key++;

          });
        }
        vm.isLoading = false;
      });
    },
    convertSecondsToHHMMSS: function (intSecondsToConvert) {      
      if (intSecondsToConvert == 0) return '0.00 Hrs';
      var hours = this.convertHours(intSecondsToConvert);
      var minutes = this.getRemainingMinutes(intSecondsToConvert);
      var seconds = this.getRemainingSeconds(intSecondsToConvert);
      var formattedHours = this.formatIndianNumber(hours);
      if (hours < 10) formattedHours = '0' + hours;
      if (minutes < 10) minutes = '0' + minutes; if (seconds < 10) seconds = '0' + seconds;
      return formattedHours + '.' + minutes + ' Hrs';
    },
    formatIndianNumber: function (num) {
      var str = num.toString();

      if (str.length <= 3) return str;

      var lastThree = str.slice(-3);
      var remaining = str.slice(0, -3);

      remaining = remaining.replace(/\B(?=(\d{2})+(?!\d))/g, ',');

      return remaining + ',' + lastThree;
    },
    convertHours: function (intSeconds) {
      var minutes = this.convertMinutes(intSeconds);
      var hours = Math.floor(minutes / this.minutesPerHour);
      return hours;
    },
    convertHoursTwoDecimal: function (intSeconds) {
      var minutes = this.convertMinutes(intSeconds);
      var hours = (minutes / this.minutesPerHour).toFixed(2);
      return hours;
    },
    convertMinutes: function (intSeconds) {      
      return Math.floor(intSeconds / this.secondsPerMinute);
    },
    getRemainingMinutes: function (intSeconds) {
      var intTotalMinutes = this.convertMinutes(intSeconds);
      return intTotalMinutes % this.minutesPerHour;
    },
    getRemainingSeconds: function (intTotalSeconds) {
      return intTotalSeconds % this.secondsPerMinute;
    },
    Close() {
      this.$parent.isProjectDeatil = false;
    }
  }
}
</script>