<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('Add') }} {{ $t('Task') }}</h4>
                        <button type="button" class="close" v-on:click="CloseAddBacklog">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>   
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default {    
    data(){
        return{
             MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            isLoading:false,
            FormSchema: [               
                {
                    layoutType: "double",
                    Data: [ 
                        {
                            astype: "TextField",                                                
                            label: this.$t('TaskName'),
                            name: "TaskName",
                            value: "",               
                            placeholder: this.$t('Enter Task Name'),
                            validationRules: { "required": true, max: 100 },
                        },                   
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Stage'),
                            name: "Stage",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Stage'),
                            validationRules: { "required": true, max: 100 },
                        },                        
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Assign'),
                            name: "Assign",
                            value: "", 
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Assign'),
                            validationRules: { "required": false, max: 100 },
                        },
                        {
                            astype: "NumericField",                                                
                            label: this.$t('DurationInHours'),
                            disabled: true,
                            name: "Tag",
                            value: "0",                                                      
                            placeholder: this.$t('Duration'),
                            validationRules: { "required": false, max: 100 },
                        },
                        {
                            astype: "DateField",
                            label: this.$t("Start Date"),
                            disabled: false,
                            name: "StartDate",
                            value: new Date(),
                            placeholder: this.$t("StartDate"),
                            validationRules: {
                                required: true,
                            },
                            config: { mode: "date", format: "M/D/YYYY", 
                            minDate:'', maxDate: '',
                            onChange:this.checkEndMinDate
                            },
                        }, 
                        {
                            astype: "DateField",
                            label: this.$t("End Date"),
                            disabled: false,
                            name: "EndDate",
                            value: new Date(),
                            placeholder: this.$t("EndDate"),
                            validationRules: {
                                required: true,
                            },
                            config: { mode: "date", format: "M/D/YYYY",   minDate: '', maxDate: '', onChange:this.calculateDuration},
                        }, 
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Priority'),
                            name: "Priority",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Priority'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Construction Manager'),
                            name: "ConstructionManager",
                            value: "", 
                            visibility:false,
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Construction Manager'),
                            validationRules: { "required": false, max: 100 },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Quality'),
                            name: "Quality",
                            visibility:false,
                            value: "", 
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Quality'),
                            validationRules: { "required": false, max: 100 },
                        },
                                                           
                    ]
                },                
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",                 
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",  
                            validationRules: { "required": false, max: 4000 },
                            config: {
                                rows:3
                            }
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseAddBacklog,
                },
            ],
            ProjectId:''
        }
    },
    created:function(){
        
        var vm =this;
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.userId = vm.GetUserInfo.ID;  
        vm.ProjectId= this.$route.params.projectId;
        vm.GetUsers();
        vm.GetStage();
        vm.GetProjectPriority();
        vm.ProjectOverview();
    },
    methods:{
        ProjectOverview: async function () {
            var vm = this;            
            var params = `projectId=${vm.$route.params.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {
                if (response.data != null > 0) {                    
                    vm.ProjectStartDate = response.data.planneD_START_DATE;
                    vm.ProjectEndDate = response.data.planneD_END_DATE;
                    vm.FormSchema[0].Data[4].config.minDate= vm.ProjectStartDate;
                    vm.FormSchema[0].Data[4].config.maxDate= vm.ProjectEndDate;
                    vm.FormSchema[0].Data[5].config.minDate= vm.ProjectStartDate;
                    vm.FormSchema[0].Data[5].config.maxDate= vm.ProjectEndDate;
                }
            });
        },
        checkEndMinDate()
        {
            var vm=this;
            var  selectedDate= vm.FormSchema[0].Data[4].value;
            vm.FormSchema[0].Data[4].config.minDate=selectedDate;
            vm.FormSchema[0].Data[5].config.minDate=selectedDate;
            vm.calculateDuration();
        },
        calculateDuration() {            
            const startDate = new Date(this.FormSchema[0].Data[4].value); 
            const endDate = new Date(this.FormSchema[0].Data[5].value);  
            if (isNaN(startDate) || isNaN(endDate)) {
            return;
            }
            const diffInMilliseconds = endDate - startDate;
            const durationInHours = diffInMilliseconds / (1000 * 60 * 60); 
            this.FormSchema[0].Data[3].value = Math.floor(durationInHours);
        },
        GetProjectPriority(){
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            var PriorityData=response.data.DATA;
                            PriorityData.forEach(element => {
                                let obj={
                                    name:element.name,
                                    value:element.value
                                }
                                this.FormSchema[0].Data[6].config.options.push(obj);
                            });
                            this.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
            })
        },
        GetStage() {
            var vm = this;
            var url = `id=${vm.ProjectId}&moduleName=PROJECT&type=PROJECT_PROJECT_STAGE&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {                        
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(element => {
                                let obj = {
                                    name: element.name,
                                    value: element.value
                                }
                                vm.FormSchema[0].Data[1].config.options.push(obj);
                            });
                            vm.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
            })
        },    
        GetUsers(){
            var vm=this;       
            var url = `id=${vm.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    value: element.value,
                                    name: element.name
                                }
                                vm.FormSchema[0].Data[2].config.options.push(obj);
                                vm.FormSchema[0].Data[5].config.options.push(obj);
                            })
                        }
                        else {
                            vm.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
            });             
        },
        CloseAddBacklog(){
            this.$emit('CloseAddBacklog')
        },
        OnSubmit:async function(){            
            var ths = this;
            
            ths.isLoading=true;
            var obj = {
                BackLogId: 0,
                Project_id:ths.ProjectId,
                Subject:ths.FormSchema[0].Data[0].value,
                StageId:ths.FormSchema[0].Data[1].value,
                UserId:ths.FormSchema[0].Data[2].value,
                Duration:ths.FormSchema[0].Data[3].value,
                Date:ths.FormSchema[0].Data[4].value,
                PriorityId: ths.FormSchema[0].Data[6].value,
                ConstructionManager: ths.FormSchema[0].Data[7].value,
                Quality: ths.FormSchema[0].Data[8].value,
                BackLogDescription:ths.FormSchema[1].Data[0].value,
                StatusId:1001,
                Type: 'ConstructionTask'
               
            }            
            await DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {                
                ths.isLoading=false;
                if(response.data.result.DATA.length>0){ 
                    if(response.data.result.DATA[0].VALUE=='CONSTRUCTIONTASK') {
                        ths.ShowAlert(ths.$t('UpdatedSuccess',[ths.$t('Stage Task')]),"success", true, ths.$t("Alert"));
                    }else{
                        ths.ShowAlert(ths.$t('AddedSuccess',[ths.$t('Stage Task')]), "success", true,  ths.$t("Alert"));
                    } 
                    ths.CloseAddBacklog();
                    ths.$emit('FetchConstructionTask')
                }else{
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            })
        }
    }
}
</script>