<template>
    <section>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="false" ModuleName="Event"
            SubModuleCode="Client" IdentityColumn="ID" :HeaderText="$t('EmailInvitation')" :ListData="list"
            :HeaderData="Headers" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
            :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="GetEventDonationListing"
            :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')"
            v-on:ActionButtonClick="actionButtonClick" v-on:PagerButtonClick="pagerMethod"
            v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'SUBJECT'">
                    <a class="task-dec" :title="data.row.SUBJECT"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.SUBJECT }}
                    </a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'SENDDATE'">
                    <span :title="data.row.SENDDATE"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ $d(new Date(data.row.SENDDATE)) }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'STATUS'">
                    <a :title="data.row.STATUS"
                        style="cursor: pointer; white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.STATUS }}
                    </a>
                </template>
            <template v-if="data.column.COLUMN_NAME == 'SENDDATE'">
                <span :title="data.row.SENDDATE"
                    style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                    {{ $d(new Date(data.row.SENDDATE)) }}
                </span>
            </template>
            <template v-if="data.column.COLUMN_NAME == 'STATUS'">
                <a :title="data.row.STATUS"
                    style="cursor: pointer; white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                    {{ data.row.STATUS }}
                </a>
            </template>
</template>
</tg-list>
</section>
</template>

<script>
import DataService from '@/services/DataService';
import Schema from './EmailInvitationPortionSchema'
export default {
    name: 'EmailInvitationPortion',
    props: { eventId: { type: [Number, String], required: true } },
    data() {
        return {
            list: [],
            TotalRecords: 0,
            PageSize: 10,
            PageNumber: 1,
            SortBy: '',
            SortExp: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            Buttons: Schema.buttons,
            CompanyId: 0,
            userId: 0,
        };
    },
    created() {
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.userId = this.GetUserInfo.ID;
        this.fetch();
    },
    methods: {
        async fetch() {
            try {
                const res = await DataService.GetEmailInvitationListing(`eventId=${this.eventId}&companyId=${this.CompanyId}&userId=${this.userId}&&pageSize=${this.PageSize}&pageNumber=${this.PageNumber}`);
                const d = res.data && res.data.result;
                this.list = (d && d.data) ? d.data : (Array.isArray(d) ? d : []);
                this.TotalRecords = (d && d.totalRecords) ? d.totalRecords : this.list.length;
            } catch (_) { this.list = []; this.TotalRecords = 0; }
        },
        renderActions: function () {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'AddEmail':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.fetch();
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {
                case 'EditEmail':
                    this.AdddEmail(item);
                    break;
                case 'DeleteEmail':
                    this.commonDeleteData(item);
                    break;
            }
        },
        commonHeaderButtonClick: async function (event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "AddEmail":
                    vm.AdddEmail();
                    break;
                case "BackToList":
                    vm.BackToList();
                    break;
                case "DeleteEmail":
                    vm.commonDeleteData();
                    break;
            }
        },
        async AdddEmail() {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateEmailInvitation';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    //vm.showAddModal = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        BackToList: function () {
            this.$router.push({ name: 'ProjectList' });
        },
        async commonDeleteData() {
            var vm = this;
            var url = 'controller=Project&action=DeleteEmailInvitation';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    //vm.showAddModal = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.fetch();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
    }
};
</script>
