<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title" v-if="wishListData">{{ $t('Add') }} {{ $t('WishList') }}</h4>
                        <h4 class="modal-title" v-else>{{ $t('Edit') }} {{ $t('WishList') }}</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default{
    props:{
        wishListData:{
            type:Object || Array
        },
        projectId:{
            type:String
        }
    },
    data(){
        return{
            isLoading:false,
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [               
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "TextField",                                                
                            label: this.$t('Item Type'),
                            name: "ItemType",
                            value: "",                            
                            placeholder: this.$t('Item Type'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "TextField",                                                
                            label: this.$t('Online Url'),
                            name: "OnlineUrl",
                            placeholder: this.$t('Online Url'),
                            validationRules: { "required": true, max: 100 ,url:true},
                        } 
                    ]
                },
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",                 
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",  
                            validationRules: { "required": true, max: 4000 },
                            config: {
                                rows:5
                            }
                        },
                        {
                            astype: "FileField",
                            label: this.$t('Attachment'),
                            name: "attachments",
                            value: "",
                            visibility: true,
                            placeholder: "Select",
                            FieldIndex: 0,
                            config: {
                                maxSize: 5,
                                accept: [{ fileType: 'jpg', iconClass: 'fa-file-image-o' },
                                    { fileType: 'jpeg', iconClass: 'fa-file-image-o' },
                                    { fileType: 'png', iconClass: 'fa-file-image-o' },
                                    { fileType: 'pdf', iconClass: 'fa-file-archive-o' },
                                    { fileType: 'mp4', iconClass: 'fa-video-camera' },
                                    { fileType: 'doc', iconClass: 'fa-file-text-o' },
                                    { fileType: 'docx', iconClass: 'fa-file-text-o' },
                                    { fileType: 'xlsx', iconClass: 'fa-file-excel-o' },
                                    { fileType: 'txt', iconClass: 'fa-file-text-o' },
                                    { fileType: 'xls', iconClass: 'fa-file-excel-o' }
                                ],
                                showSelectedFiles: [],
                                onChange: this.GetBase64String,
                                onDeleteSelectedFiles:this.onDeleteSelectedFiles,
                                options: [],
                                multiple: true
                            },
                            validationRules: {
                                "required": false
                            }
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Close,
                },
            ],
        }
    },
    created:function(){
     if(this.wishListData) this.EditData(this.wishListData)
    },

    methods:{
        EditData(data){
            
            var ths=this;
            ths.FormSchema[0].Data[0].value=data.item_type;
            ths.FormSchema[1].Data[0].value=data.description;
            ths.FormSchema[0].Data[1].value=data.online_url
        },
        OnSubmit(){
            var ths=this;
            ths.isLoading=true;
            var obj = {
                wishListId: this.wishListData?.wish_list_id ?? 0,  
                itemType: ths.FormSchema[0].Data[0].value,
                description: ths.FormSchema[1].Data[0].value,
                onlineUrl: ths.FormSchema[0].Data[1].value,
                itemImage: '',
                eventId: ths.projectId,
                giftedByEmialId: '',
                attendeeId: 0,
                attachement_mime: '',
                containerName: '',
                base64String: '',
                moduleName: "EVENT",
                subModuleCode: "EVENT_WISHLIST"
        }
        DataService.SaveWishList(JSON.stringify(obj)).then((response)=>{  
                ths.isLoading=false;        
                      
                if(response.data.result.length>0){
                    if(response.data.status=="Success" && response.data.code=='1' ){                        
                        ths.ShowAlert(ths.$t('AddedSuccess',[ths.$t('WishList')]), "success", true,  ths.$t("Alert"));    
                        ths.$parent.RefreshData(); 
                    }
                   else if(response.data.result=='ALREADYEXIST'){   
                    ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('WishList')]), "warning", true, ths.$t("Alert"));                        
                    }
                    else if(response.data.result=='UPDATED'){                        
                        ths.ShowAlert(ths.$t('UpdatedSuccess',[ths.$t('WishList')]), "success", true,  ths.$t("Alert"));   
                        ths.$parent.RefreshData(); 
                    }
                }
            });
        },
        Close(){this.$parent.Iswishlist=false}
    }
}
</script>