<template>
    <div class="col-md-12 p-0">
        <loader :is-visible="isLoading"></loader>
        <div class="ticketsmallfix theme-primary partition p-actions-expand mt-2" style="overflow: visible;">
            <span class="p-name text-white">{{ $t("Board") }}</span>
            <span class="p-actions float-right d-flex">
                <a v-if="CheckDisabled()" title="Add Board" href="javascript:;" class="p-action-btn text-white"
                    @click="AddStatus()">
                    <em class="fa fa-plus pr-2 "></em> <br><span>{{ $t("Add Board") }}</span></a>
                <router-link to="/Project/Index">
                    <a title="Back to list" href="javascript:;" class="p-action-btn text-white">
                        <em class="fa fa-angle-double-left pr-2 "></em> <br><span>{{ $t("BacktoList") }}</span></a>
                </router-link>
                <select id="ddlUserCurrentStatus" v-model="groupBy" asp-custom-tabindex="1" name="ddlUserCurrentStatus"
                    class="form-control m-2" style="width: 130px;" @change="onGroupByChange">
                    <option value="">{{ $t('GroupBy') }}</option>
                    <option value="priority">{{ $t('Priority') }}</option>
                    <option value="assignee">{{ $t('Assignee') }}</option>
                </select>
            </span>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0 top-menu-tab border p-3 mb-2">
            <div class="row p-0 pt-2 colcontrol">
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <input class="form-control" :placeholder="`${$t(NewTabName)} Name...`"
                            @keyup.enter="TaskData(IsTaskName, 'TASK_BY_NAME')" v-model="IsTaskName">
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="TypeFilter" :options="ProjectBacklogType" placeholder="Task Type"
                            :limit="1" :limitText="getFilterLimitText" :multiple="true"
                            v-on:input="TaskData(TypeFilter, 'TASK_BY_TYPE')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="QuickFilter" :options="ProjectUsers" placeholder="Task Assignee" :limit="1"
                            :limitText="getFilterLimitText" :multiple="true"
                            v-on:input="TaskData(QuickFilter, 'TASK_BY_ASSIGN_USER')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="PriorityFilter" :options="FilterPriorityData" placeholder="Priority"
                            :limit="1" :limitText="getFilterLimitText" :multiple="true"
                            v-on:input="TaskData(PriorityFilter, 'TASK_BY_PRIORITY')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="StatusFilter" :options="StatusData" placeholder="Status" :limit="1"
                            :limitText="getFilterLimitText" :multiple="true"
                            v-on:input="TaskData(StatusFilter, 'TASK_BY_STATUS')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="SprintFilter" :options="SprintData" placeholder="Sprint" :multiple="true"
                            :limit="1" :limitText="getFilterLimitText"
                            v-on:input="TaskData(SprintFilter, 'TASK_BY_SPRINT')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="background-0 text-left form-check-inline">
                        <a href="javascript:void(0);" title="" data-toggle-tooltip="tooltip"
                            data-original-title="Clear all " class="btn btn-danger clearsearchtext px-4"
                            @click="Clearsearch">
                            <em class="fa fa-refresh"></em>{{ $t('Clear') }}
                        </a>
                    </div>
                </div>
            </div>
        </div>
        <div class="listing mt-2 thispagebod-full">
            <div class="onlyd-view ht_630" :class="{ 'board-matrix-view': !!groupBy }">
                <draggable v-if="!groupBy" class="canvan-view-list vuejs kvlistview proj_kv newdes_kvlist mt-2"
                    v-model="StatusList" :sort="true" :animation="200" handle=".board-header-drag"
                    ghost-class="ghost-task" chosen-class="chosen-task" drag-class="dragging-task"
                    :draggable="'.board-column'" tag="ul" item-key="board_id" :force-fallback="true"
                    :fallback-on-body="true" @start="onBoardOrderDragStart" @end="onBoardOrderDragEnd">
                    <li v-for="(stem, sindex) in StatusList" :key="stem.board_id" class="board-column">
                        <div class="kb-col-header board-header-drag" :style="{ borderTopColor: stem.board_color }">
                            <div class="kb-col-title-row">
                                <em class="fa fa-bars kb-drag-icon text-muted" title="Drag to reorder"></em>
                                <span class="kb-col-dot" :style="{ backgroundColor: stem.board_color }"></span>
                                <span class="kb-col-name" :title="stem.board_name">{{ TruncateStr(stem.board_name, 16)
                                    }}</span>
                                <span class="kb-col-count">{{ stem.count }}</span>
                                <div class="wip ml-auto" v-if="stem.wip_limit<stem.count">
                                    ⚠ WIP
                                </div>
                            </div>
                            <div class="kb-col-actions">
                                <span class="kb-wip-info" :title="$t('WIP Limit')">{{ stem.count }}/{{ stem.wip_limit ||
                                    '0' }}</span>
                                <a v-if="!stem.isSynthetic" class="kb-icon-btn kb-icon-success" title="Add Task"
                                    @click="AddTask(stem, sindex)"><em class="fa fa-plus text-success"></em></a>
                                <a v-if="!stem.isSynthetic" class="kb-icon-btn kb-icon-info" title="Edit Board"
                                    @click="AddStatus(stem)"><em class="fa fa-pencil text-info"></em></a>
                                <a v-if="!stem.isSynthetic" class="kb-icon-btn kb-icon-danger" title="Delete Board"
                                    @click="DeleteStatus(stem)"><em class="fa fa-trash-o text-danger"></em></a>
                            </div>
                        </div>
                        <div class="w-100 float-left my-0"
                            v-if="!stem.isSynthetic && TaskMode && activeTaskIndex === sindex">
                            <div class="add-backlog-btn border bg-light float-left w-100">
                                <div class="input-group w-100 pb-3 px-3 pt-3 ">
                                    <div class="input-group-prepend border-right-0 flex-grow-1">
                                        <span id="basic-addon1" class="input-group-text bg-white px-2">
                                            <em class="fa fa-check-square epic-timeline"></em>
                                        </span>
                                        <input type="text" placeholder="Enter task" aria-label=""
                                            aria-describedby="basic-addon1"
                                            class="form-control px-1 bg-white border-left-0 newdescolor"
                                            v-model="TaskFieldValue" @keydown.enter="SaveTaskt" />
                                    </div>

                                    <div class=" d-flex pt-2" @click="SaveTaskt">
                                        <a title="Save" class="actions-onclick">
                                            <em class="fa fa-save action-icon text-success font-18"></em>
                                        </a>
                                        <a title="Close" class="actions-onclick" @click="Close">
                                            <em class="fa fa-close action-icon text-danger font-18"></em>
                                        </a>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div class="kb-column-wrapper" style="max-height: 60vh; overflow-y: auto;">
                            <draggable class="kb-column h-auto" v-model="stem.tasks" :group="draggableGroupOptions"
                                :sort="true" :disabled="stem.isSynthetic || isBoardDragging" :draggable="'.task-card'"
                                :animation="200" ghost-class="ghost-task" chosen-class="chosen-class"
                                drag-class="dragging-task" :data-board-name="stem.board_name" :data-board-id="stem.board_id"
                                item-key="task_id" @start="onDragStart" @end="onDragEnd" @add="onDragAdd"
                                :key="'drop-' + stem.board_id">
                            <!-- Task Cards -->
                                <div v-for="(ttem, tindex) in stem.tasks" :key="ttem.task_id" class="kb-task-card task-card"
                                    :data-task-id="ttem.task_id">
                                    <a href="javascript:void(0)"
                                        style="color: inherit; display: block; text-decoration: none;"
                                        @click.prevent="OpenEditTaskModel(ttem)">
                                        <div class="kb-card-top">
                                            <span class="kb-priority-pill"
                                                :style="{ backgroundColor: (ttem.color_code || '#6c757d') + '35', color: ttem.color_code || '#6c757d' }">
                                                {{ ttem.priority_name || 'N/A' }}
                                            </span>
                                            <span v-if="getTaskAge(ttem)" class="kb-age-badge"
                                                :class="getTaskAgeClass(ttem)" title="Task age since planned start">
                                                <em class="fa fa-clock-o"></em> {{ getTaskAge(ttem) }}
                                            </span>
                                        </div>
                                        <div class="kb-card-title">
                                            <span class="kb-task-num">{{ ttem.task_number }}</span>
                                            <span class="text-primary" :title="ttem.task_name">{{
                                                TruncateStr(ttem.task_name, 38) }}</span>
                                        </div>
                                        <div v-if="getTaskDesc(ttem)" class="kb-card-desc" :title="getTaskDesc(ttem)">
                                            {{ TruncateStr(getTaskDesc(ttem), 70) }}
                                        </div>
                                        <div class="kb-card-dates">
                                            <em class="fa fa-calendar-o mr-1"></em>
                                            <span>{{ ttem.planned_start_date !== "" ?
                                                $options.filters.formatDate(ttem.planned_start_date) : "N/A" }}</span>
                                            <span class="mx-1">—</span>
                                            <span>{{ ttem.planned_end_date !== "" ?
                                                $options.filters.formatDate(ttem.planned_end_date) : "N/A" }}</span>
                                        </div>
                                        <div v-if="ttem.TotalTask > 0" class="kb-card-progress">
                                            <div class="kb-progress-wrap">
                                                <div class="kb-progress-bar"
                                                    :style="{ width: getTaskProgress(ttem) + '%', backgroundColor: stem.board_color || '#28a745' }">
                                                </div>
                                            </div>
                                            <span class="kb-progress-label">{{ ttem.CompleteTask }}/{{ ttem.TotalTask
                                                }}</span>
                                        </div>
                                        <div class="kb-card-footer">
                                            <div class="kb-avatars">
                                                <div class="kb-avatar" v-for="(item, index) in ttem.Assign" :key="index"
                                                    :style="{ background: assigneeAvatarColor(index) }" :title="item">
                                                    {{ item.split(" ")[0]?.charAt(0) }}{{ item.split(" ")[1]?.charAt(0) }}
                                                </div>
                                            </div>
                                            <div class="kb-card-meta-icons">
                                                <!-- <span class="kb-meta-icon" title="Comments">
                                                    <em class="fa fa-comment-o"></em> {{ ttem.COMMENT_COUNT || 0 }}
                                                </span> -->
                                                <span class="kb-task-type-badge">
                                                    <em class="fa fa-check-square-o"></em>
                                                    {{ ttem.ParentTask != null ? 'Sub' : 'Task' }}
                                                </span>
                                            </div>
                                        </div>
                                    </a>
                                </div>
                            </draggable>
                        </div>
                    </li>
                    <li v-if="StatusList.length < 4" class="board-static-item">
                        <div class="list-group h-auto addsection text-center" @click="AddStatus()">
                            <a>
                                <em class="fa fa-plus mr-2"></em>Add Section
                            </a>
                        </div>
                    </li>
                </draggable>

                <!-- Group by: swimlanes (rows) × status columns (boards) -->
                <div v-else-if="swimlaneMatrix && swimlaneMatrix.columns.length" class="board-matrix-wrap">
                    <div class="board-matrix-scroll">
                        <table class="board-matrix-table ">
                            <thead class="thead-bg">
                                <tr>
                                    <th class="matrix-corner">{{ swimlaneMatrix.axisLabel }}</th>
                                    <th v-for="col in swimlaneMatrix.columns" :key="'mh-' + col.board_id"
                                        class="matrix-col-head">
                                        <div class="matrix-head-inner">
                                            <div class="roundball_des matrix-head-dot"
                                                :style="{ backgroundColor: col.board_color }"></div>
                                            <span class="matrix-head-title">{{ col.board_name }}</span>
                                            <span class="matrix-wip wip small ml-auto">
                                                Wip {{ getBoardTaskCount(col.board_id) }} / {{ col.wip_limit || 0 }}
                                            </span>
                                        </div>
                                    </th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr v-for="(row, ri) in swimlaneMatrix.rows" :key="'mr-' + row.rowKey + '-' + ri">
                                    <th class="matrix-row-head">
                                        <div v-if="groupBy === 'priority'" class="matrix-row-priority">
                                            <span class="matrix-row-dot"
                                                :style="{ backgroundColor: row.dotColor }"></span>
                                            <div class="matrix-row-text">
                                                <span class="matrix-row-label">{{ row.label }}</span>
                                                <span class="matrix-row-count text-muted">{{ row.totalCount }} {{
                                                    $t('Task') }}</span>
                                            </div>
                                        </div>
                                        <div v-else class="matrix-row-assignee">
                                            <div class="matrix-avatar" :style="{ background: row.avatarBg }">{{
                                                row.initials }}</div>
                                            <div class="matrix-row-text">
                                                <span class="matrix-row-label">{{ row.label }}</span>
                                                <span class="matrix-row-count text-muted">{{ row.totalCount }} {{
                                                    $t('Task') }}</span>
                                            </div>
                                        </div>
                                    </th>
                                    <td v-for="(cell) in row.cells" :key="'mc-' + row.rowKey + '-' + cell.board_id"
                                        class="matrix-cell">
                                        <div class="matrix-cell-wrapper" style="max-height: 60vh; overflow-y: auto;">
                                            <draggable v-model="cell.tasks" :group="matrixRowDraggableGroup()" :sort="true"
                                                :disabled="isBoardDragging" :draggable="'.task-card'"
                                                class="matrix-cell-drop list-group h-auto" :animation="200"
                                            ghost-class="ghost-task" chosen-class="chosen-task" item-key="task_id"
                                            drag-class="dragging-task" :data-board-name="cell.board_name"
                                            :data-board-id="cell.board_id" :data-row-key="row.rowKey"
                                            :data-row-user-id="row.userId || ''" @start="onDragStart" @end="onDragEnd"
                                            @add="onDragAdd">
                                                <div v-if="!cell.tasks.length" class="matrix-empty">—</div>
                                                <div v-for="(ttem, tindex) in cell.tasks" :key="ttem.task_id"
                                                    class="kb-task-card task-card" :data-task-id="ttem.task_id">
                                                    <a href="javascript:void(0)"
                                                        style="color: inherit; display: block; text-decoration: none;"
                                                        @click.prevent="OpenEditTaskModel(ttem)">
                                                        <div class="kb-card-top">
                                                            <span class="kb-priority-pill"
                                                                :style="{ backgroundColor: (ttem.color_code || '#6c757d') + '35', color: ttem.color_code || '#6c757d', borderColor: (ttem.color_code || '#6c757d') + '80' }">
                                                                {{ ttem.priority_name || 'N/A' }}
                                                            </span>
                                                            <span v-if="getTaskAge(ttem)" class="kb-age-badge"
                                                                :class="getTaskAgeClass(ttem)"
                                                                title="Task age since planned start">
                                                                <em class="fa fa-clock-o"></em> {{ getTaskAge(ttem) }}
                                                            </span>
                                                        </div>
                                                        <div class="kb-card-title">
                                                            <span class="kb-task-num">{{ ttem.task_number }}</span>
                                                            <span class="text-primary" :title="ttem.task_name">{{
                                                                TruncateStr(ttem.task_name, 32) }}</span>
                                                        </div>
                                                        <div v-if="getTaskDesc(ttem)" class="kb-card-desc"
                                                            :title="getTaskDesc(ttem)">
                                                            {{ TruncateStr(getTaskDesc(ttem), 60) }}
                                                        </div>
                                                        <div class="kb-card-dates">
                                                            <em class="fa fa-calendar-o mr-1"></em>
                                                            <span>{{ ttem.planned_start_date !== "" ?
                                                                $options.filters.formatDate(ttem.planned_start_date) : "N/A"
                                                                }}</span>
                                                            <span class="mx-1">—</span>
                                                            <span>{{ ttem.planned_end_date !== "" ?
                                                                $options.filters.formatDate(ttem.planned_end_date) : "N/A"
                                                                }}</span>
                                                        </div>
                                                        <div v-if="ttem.TotalTask > 0" class="kb-card-progress">
                                                            <div class="kb-progress-wrap">
                                                                <div class="kb-progress-bar"
                                                                    :style="{ width: getTaskProgress(ttem) + '%', backgroundColor: cell.board_color || '#28a745' }">
                                                                </div>
                                                            </div>
                                                            <span class="kb-progress-label">{{ ttem.CompleteTask }}/{{
                                                                ttem.TotalTask }}</span>
                                                        </div>
                                                        <div class="kb-card-footer">
                                                            <div class="kb-avatars">
                                                                <div class="kb-avatar" v-for="(item, index) in ttem.Assign"
                                                                    :key="index"
                                                                    :style="{ background: assigneeAvatarColor(index) }"
                                                                    :title="item">
                                                                    {{ item.split(" ")[0]?.charAt(0) }}{{ item.split("
                                                                    ")[1]?.charAt(0) }}
                                                                </div>
                                                            </div>
                                                            <div class="kb-card-meta-icons">
                                                                <span class="kb-meta-icon" title="Comments">
                                                                    <em class="fa fa-comment-o"></em> {{ ttem.COMMENT_COUNT
                                                                    || 0 }}
                                                                </span>
                                                                <span class="kb-task-type-badge">
                                                                    <em class="fa fa-check-square-o"></em>
                                                                    {{ ttem.ParentTask != null ? 'Sub' : 'Task' }}
                                                                </span>
                                                            </div>
                                                        </div>
                                                    </a>
                                                </div>
                                            </draggable>
                                        </div>                         
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>

                <div v-if="!groupBy && StatusList.length == 0" class="mt-3">
                    <div class="text-center text-danger">
                        {{ $t('NoRecordfound') }}
                    </div>
                </div>
                <div v-if="groupBy && (!swimlaneMatrix || !swimlaneMatrix.columns.length)" class="mt-3">
                    <div class="text-center text-danger">
                        {{ $t('NoRecordfound') }}
                    </div>
                </div>
            </div>
        </div>
        <AddStatus v-if="IsAddStatus" :projectId="projectId" :projectdata="EditDetail"></AddStatus>
        <EditTask v-if="IsEditTask" :projectId="ProjectId" :projectdata="projectData" @callbackfunction="UpdateTask"
            :isHideConstruction="false" :isHideSprint="true" :TabsArray="TabsArray" :NewTabName="NewTabName" :modeType="modeType" :ProjectOwner="ProjectOwner" :checkPmUser="checkPmUser"></EditTask>
    </div>
</template>

<script>
import DataService from '../../../../services/DataService';
import AddStatus from '../../../../components/Modal/AddStatus.vue'
import EditTask from '../../../../components/Modal/EditTask.vue';
import draggable from 'vuedraggable';
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
export default {
    components: {
        AddStatus, draggable, EditTask, Treeselect
    },
    props: {
        projectId: {
            type: Number,
            require: true
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        ProjectOwner: {
            type: String
        }
    },
    data() {
        return {
            modeType: '',
            activeTaskIndex: null,
            IsEditTask: false,
            isLoading: false,
            userId: null,
            TaskMode: false,
            companyId: null,
            UserType: null,
            ProjectId: 0,
            IsAddStatus: false,
            ShowMoreFalse: false,
            ListingData: [],
            StatusList: [],
            statusmodel: false,
            EditDetail: [],
            TaskFieldValue: '',
            projectData: [],
            taskData: [],
            isDragging: false,
            draggedTask: null,
            sourceBoardIndex: null,
            sourceBoardId: null,
            isBoardDragging: false,
            isUpdatingTask: false,
            groupBy: '',
            _boardSource: [],
            boardOrderBeforeDrag: [],
            PriorityData: [],
            swimlaneMatrix: null,
            ProjectUsers: [],
            IsTaskName: '',
            TypeFilter: null,
            QuickFilter: null,
            PriorityFilter: null,
            StatusFilter: null,
            SprintFilter: null,
            ProjectBacklogType: [],
            FilterPriorityData: [],
            StatusData: [],
            SprintData: []
        }
    },
    computed: {
        draggableGroupOptions() {
            if (this.groupBy) {
                return { name: 'taskList', pull: false, put: false };
            }
            return { name: 'taskList', pull: true, put: true };
        }
    },
    watch: {
        PriorityData: {
            handler() {
                if (this.groupBy === 'priority') {
                    this.rebuildDisplayBoards();
                }
            },
            deep: true
        }
    },
    mounted() {
        var vm = this;
        vm.TaskData();
    },
    created: async function () {
        var vm = this;
        vm.TaskData();
        vm.userId = vm.GetUserInfo.ID;
        vm.ProjectId = vm.projectId;
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.CheckDisabled();
        vm.GetProjectPriority();
        vm.GetProjectUsers();
        vm.GetProjectBacklogType();
        vm.GetProjectSprint();
        vm.StatusDropdown();
    },
    methods: {
        getFilterLimitText(count) {
            return `+${count}`;
        },
        normalizeSelectIds(value) {
            if (value == null) return [];
            var arr = Array.isArray(value) ? value : [value];
            return arr
                .map(function (v) {
                    if (v == null) return null;
                    if (typeof v === 'object') return v.value != null ? v.value : (v.id != null ? v.id : null);
                    return v;
                })
                .filter(function (v) { return v !== null && v !== ''; });
        },
        csv(val) {
            return this.normalizeSelectIds(val).join(',');
        },
        Clearsearch() {
            this.IsTaskName = '';
            this.TypeFilter = null;
            this.QuickFilter = null;
            this.PriorityFilter = null;
            this.StatusFilter = null;
            this.SprintFilter = null;
            this.TaskData();
        },
        onGroupByChange() {
            this.TaskMode = false;
            this.activeTaskIndex = null;
            this.rebuildDisplayBoards();
        },
        matrixRowDraggableGroup() {
            // Keep all swimlane cells in one group so tasks can move across rows.
            return { name: 'swimlane-matrix', pull: true, put: true };
        },
        getBoardTaskCount(boardId) {
            var board = (this._boardSource || []).find(function (b) { return b.board_id == boardId; });
            if (!board || !Array.isArray(board.tasks)) return 0;
            return board.tasks.length;
        },
        normalizePriorityKey(t) {
            var raw = t.priority_name != null ? String(t.priority_name).trim() : '';
            return raw || '__none__';
        },
        getPriorityColorFromMaster(label) {
            if (!label || label === '__none__') return '';
            var normalized = String(label).trim().toLowerCase();
            var match = (this.PriorityData || []).find(function (p) {
                return String((p && p.name) || '').trim().toLowerCase() === normalized;
            });
            if (!match) return '';
            // API shape varies by module; support common color fields.
            var color = match.color_code || match.COLOR_CODE || match.colorCode || match.color || '';
            color = String(color || '').trim();
            return color;
        },
        priorityDotColor(label) {
            var fromMaster = this.getPriorityColorFromMaster(label);
            if (fromMaster) return fromMaster;
            var l = String(label).toLowerCase();
            if (l.indexOf('critical') !== -1) return '#dc3545';
            if (l.indexOf('high') !== -1) return '#fd7e14';
            if (l.indexOf('medium') !== -1) return '#ffc107';
            if (l.indexOf('low') !== -1) return '#28a745';
            return '#6c757d';
        },
        getOrderedPriorityRowKeys() {
            var vm = this;
            var fromTasks = {};
            var ordered = [];
            var added = {};

            (this._boardSource || []).forEach(function (b) {
