            if (this.PriorityData && this.PriorityData.length) {
                this.PriorityData.forEach(function (p) {
                    var key = String((p && p.name) || '').trim() || '__none__';
                    if (fromTasks[key] && !added[key]) {
                        added[key] = true;
                        ordered.push({
                            key: key,
