                            dotColor: (p && (p.second_value || p.color_code)) || vm.priorityDotColor(key)
                        });
                    }
                });
            }

            // Add any task priorities not present in master.
            Object.keys(fromTasks).forEach(function (key) {
                if (!added[key]) {
                    added[key] = true;
                    ordered.push({
                        key: key,
                        label: key === '__none__' ? 'N/A' : key,
                        dotColor: vm.priorityDotColor(key)
                    });
                }
            });

            return ordered;
        },
        getAssigneeRowKeys() {
            var names = [];
            var seen = {};
