            var vm = this;
            (this._boardSource || []).forEach(function (b) {
                (b.tasks || []).forEach(function (t) {
                    var assigns = Array.isArray(t.Assign) ? t.Assign : (t.Assign != null && t.Assign !== '' ? String(t.Assign).split(',').map(s => s.trim()) : []);
                    if (assigns.length === 0) {
                        hasUnassigned = true;
                    } else {
                        assigns.forEach(function (name) {
                            var key = name.trim();
                            if (key && !seen[key]) {
                                seen[key] = true;
                                names.push(key);
                            }
                        });
                    }
                });
            });
            if (hasUnassigned || names.length === 0) {
                names.push('__unassigned__');
            }
            names.sort(function (a, b) {
                if (a === '__unassigned__') return 1;
