                });
                return { axisLabel: vm.$t('Priority'), columns: columns, rows: rows };
            }
            if (this.groupBy === 'assignee') {
                var aKeys = this.getAssigneeRowKeys();
                var rows = aKeys.map(function (key, rowIndex) {
                    var label = key === '__unassigned__' ? vm.$t('Unassigned') || 'Unassigned' : key;
                    var initials = key === '__unassigned__' ? '—' : vm.initialsFromDisplayName(label);
                    var avatarBg = vm.assigneeAvatarColor(rowIndex);
                    var userId = null;
                    if (key !== '__unassigned__') {
                        var match = (vm.ProjectUsers || []).find(function (u) {
                            return String((u && u.name) || '').trim().toLowerCase() === String(key).trim().toLowerCase();
                        });
                        userId = match && match.value ? match.value : null;
