                        var tasks = (board && board.tasks ? board.tasks : []).filter(function (t) {
                            var assigns = Array.isArray(t.Assign) ? t.Assign : (t.Assign != null && t.Assign !== '' ? String(t.Assign).split(',').map(s => s.trim()) : []);
                            if (key === '__unassigned__') {
                                return assigns.length === 0;
                            } else {
                                return assigns.some(function (name) { return name.trim() === key; });
                            }
                        });
                        return {
                            board_id: col.board_id,
                            board_name: col.board_name,
                            board_color: col.board_color,
                            wip_limit: col.wip_limit,
                            board_status: col.board_status,
                            tasks: tasks
                        };
                    });
                    var totalCount = cells.reduce(function (s, c) { return s + c.tasks.length; }, 0);
                    return {
                        rowKey: key,
