        onDragStart(evt) {
            
            var vm = this;
            if (vm.isBoardDragging) return;
            vm.isDragging = true;
            // Get source board index
            var sourceElement = evt.from;
            var sourceBoardName = sourceElement.getAttribute('data-board-name');
            var sourceBoardId = sourceElement.getAttribute('data-board-id');
            vm.sourceBoardId = sourceBoardId;
            if (sourceBoardName) {
                var bl = vm.getBoardListForMove();
                vm.sourceBoardIndex = bl.findIndex(board => board.board_name === sourceBoardName);
            }
            // Get dragged task data
            var taskElement = evt.item;
            vm.draggedTask = this.getTaskDataFromElement(taskElement);
            // Add visual feedback
            document.body.classList.add('dragging');
        },
        onDragAdd(evt) {
            // Task was added to a new board, handle the move
            var vm = this;
            if (vm.isBoardDragging) return;

            // Prevent duplicate calls
            if (vm.isUpdatingTask) {
                return;
            }

            var targetBoardName = evt.to.getAttribute('data-board-name');
            var targetBoardId = evt.to.getAttribute('data-board-id');

            // Get task data from the element if draggedTask is not available
            var taskData = vm.draggedTask;
            if (!taskData && evt.item) {
                taskData = vm.getTaskDataFromElement(evt.item);
            }

            if (targetBoardName && taskData && taskData.task_id) {
                vm.isUpdatingTask = true;
                var rowKey = evt.to.getAttribute('data-row-key');
                var rowUserId = evt.to.getAttribute('data-row-user-id');
                var sourceBoardId = evt.from.getAttribute('data-board-id') || vm.sourceBoardId;
                vm.handleTaskMove(taskData, targetBoardName, targetBoardId, { key: rowKey, userId: rowUserId }, sourceBoardId);
            }
        },
        onDragEnd(evt) {
            var vm = this;
            if (vm.isBoardDragging) return;
            // Remove visual feedback
            document.body.classList.remove('dragging');
            // If task was moved within the same board, no status update needed
            var sourceBoardName = evt.from.getAttribute('data-board-name');
            var targetBoardName = evt.to.getAttribute('data-board-name');
            var sourceRowKey = evt.from.getAttribute('data-row-key');
            var targetRowKey = evt.to.getAttribute('data-row-key');
            var sameBoard = sourceBoardName === targetBoardName;
            var sameRow = sourceRowKey === targetRowKey;

            if (sameBoard && (!this.groupBy || sameRow)) {
                // Task moved within same board, just refresh
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
                vm.isUpdatingTask = false;
                vm.TaskData();
                return;
            }

            // Task moved to different board - this should be handled by onDragAdd
            // But we'll also handle it here as a fallback if onDragAdd didn't fire
            if (!vm.isUpdatingTask && targetBoardName && evt.item) {
                var taskData = vm.getTaskDataFromElement(evt.item);
                if (taskData && taskData.task_id) {
                    var targetBoardId = evt.to.getAttribute('data-board-id');
                    vm.isUpdatingTask = true;
                    var rowKey = evt.to.getAttribute('data-row-key');
                    var rowUserId = evt.to.getAttribute('data-row-user-id');
                    var sourceBoardId = evt.from.getAttribute('data-board-id') || vm.sourceBoardId;
                    vm.handleTaskMove(taskData, targetBoardName, targetBoardId, { key: rowKey, userId: rowUserId }, sourceBoardId);
                } else {
                    // Clean up if no valid task data
                    vm.isDragging = false;
                    vm.draggedTask = null;
                    vm.sourceBoardIndex = null;
                    vm.sourceBoardId = null;
                    vm.isUpdatingTask = false;
                    vm.TaskData(); // Refresh to restore state
                }
            } else {
                // Clean up drag state (onDragAdd is handling the update)
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
                vm.sourceBoardId = null;
            }
        },
        getTaskDataFromElement(element) {
            
            var vm = this;
            // Try multiple ways to get task data from the dragged element
            var taskData = null;

            // Method 1: From Vue component instance (_underlying_vm_)
            if (element._underlying_vm_ && element._underlying_vm_.task_id) {
                taskData = element._underlying_vm_;
            }
            // Method 2: From Vue __vue__ property
            else if (element.__vue__) {
                // Try $attrs first
                if (element.__vue__.$attrs && element.__vue__.$attrs.task_id) {
                    taskData = element.__vue__.$attrs;
                }
                // Try component data
                else if (element.__vue__.$data && element.__vue__.$data.task_id) {
                    taskData = element.__vue__.$data;
                }
            }
            // Method 3: From data attribute (dataset)
            else if (element.dataset && element.dataset.taskId) {
                var taskId = String(element.dataset.taskId);
                taskData = vm.findTaskById(taskId);
            }
            // Method 4: From the actual element's data-task-id attribute
            else {
                var taskIdAttr = element.getAttribute ? element.getAttribute('data-task-id') : null;
                if (taskIdAttr) {
                    var taskId = String(taskIdAttr);
                    taskData = vm.findTaskById(taskId);
                }
            }

            // If still no task data, try to find by searching all boards
            if (!taskData && element) {
                // Try to get task_id from any nested element
                var taskIdElement = element.querySelector ? element.querySelector('[data-task-id]') : null;
                if (taskIdElement) {
                    var taskId = String(taskIdElement.getAttribute('data-task-id'));
                    taskData = vm.findTaskById(taskId);
                }
            }

            return taskData;
        },
        findTaskById(taskId) {
            var normalizedTaskId = String(taskId);
            if (this.groupBy && this.swimlaneMatrix && this.swimlaneMatrix.rows) {
                for (var r = 0; r < this.swimlaneMatrix.rows.length; r++) {
                    var row = this.swimlaneMatrix.rows[r];
                    for (var c = 0; c < row.cells.length; c++) {
                        var cell = row.cells[c];
                        if (cell.tasks && cell.tasks.length) {
                            var t = cell.tasks.find(function (x) { return String(x.task_id) === normalizedTaskId; });
                            if (t) return t;
                        }
                    }
                }
                return null;
            }
            for (var i = 0; i < this.StatusList.length; i++) {
                var board = this.StatusList[i];
                if (board.tasks && board.tasks.length > 0) {
                    var task = board.tasks.find(function (t) { return String(t.task_id) === normalizedTaskId; });
                    if (task) {
                        return task;
                    }
                }
            }
            return null;
        },
        getBoardListForMove() {
            if (this.groupBy && this._boardSource && this._boardSource.length) {
                return this._boardSource;
            }
            return this.StatusList;
        },
        handleTaskMove(taskData, targetBoardName, targetBoardId, targetRow, sourceBoardId) {
            var vm = this;
            if (!taskData || !taskData.task_id) {
                console.error('Invalid task data for move operation');
                vm.TaskData();
                return;
            }
            var boardList = vm.getBoardListForMove();
            var targetBoard = null;
            if (targetBoardId) {
                targetBoard = boardList.find(board => board.board_id == targetBoardId);
            }
            if (!targetBoard) {
                targetBoard = boardList.find(board => board.board_name === targetBoardName);
            }

            if (!targetBoard || !targetBoard.board_status || targetBoard.board_status.length === 0) {
                console.error('Target board not found or has no statuses');
                vm.TaskData();
                return;
            }

            var normalizedSourceBoardId = sourceBoardId != null && sourceBoardId !== '' ? parseInt(sourceBoardId, 10) : null;
            var normalizedTargetBoardId = targetBoard.board_id != null ? parseInt(targetBoard.board_id, 10) : null;
            var isCrossBoardMove = normalizedSourceBoardId !== null && normalizedTargetBoardId !== null
                ? normalizedSourceBoardId !== normalizedTargetBoardId
                : true;
            var wipLimit = parseInt(targetBoard.wip_limit, 10);
            if (isCrossBoardMove && !isNaN(wipLimit) && wipLimit > 0) {
                var targetTaskCount = Array.isArray(targetBoard.tasks) ? targetBoard.tasks.length : 0;
                if (targetTaskCount >= wipLimit) {
                    vm.isUpdatingTask = false;
                    vm.isDragging = false;
                    vm.draggedTask = null;
                    vm.sourceBoardIndex = null;
                    vm.sourceBoardId = null;
                    vm.ShowAlert(vm.$t("Board Limit Exceed"), "failure", true, vm.$t("Alert"));
                    vm.TaskData();
                    return;
                }
            }
            var firstStatus = targetBoard.board_status[0];

            if (!firstStatus || !firstStatus.status_id) {
                console.error('Target board has no valid first status');
                vm.TaskData();
                return;
            }
            var updateData = {
                task_id: taskData.task_id,
                StatusId: firstStatus.status_id,
                status_name: firstStatus.status_name || targetBoardName,
                status_bg_color: firstStatus.status_bg_color || firstStatus.STATUS_BG_COLOR || '#24a5ff',
                IsFor: 'TASKLISTING'
            };
            vm.updateTaskStatus(updateData, function () {
                vm.applyGroupedFieldMove(taskData, targetRow);
            });
        },
        applyGroupedFieldMove(taskData, targetRow) {
            var vm = this;
            var targetRowKey = targetRow && targetRow.key ? targetRow.key : '';
            var targetRowUserId = targetRow && targetRow.userId ? targetRow.userId : '';
            if (!vm.groupBy || !targetRowKey || !taskData) {
                vm.TaskData();
                return;
            }
            if (vm.groupBy === 'priority') {
                if (targetRowKey === '__none__') {
                    vm.TaskData();
                    return;
                }
                var targetPriority = (vm.PriorityData || []).find(function (p) {
                    return String(p.name) === String(targetRowKey);
                });
                if (!targetPriority) {
                    vm.TaskData();
                    return;
                }
                var payload = {
                    ID: taskData.task_id,
                    StatusId: targetPriority.value,
                    IsFor: 'UPDATE_PROJECT_PRIORTY'
                };
                DataService.CommonUpdateStatus(JSON.stringify(payload)).then(function () {
                    vm.TaskData();
                }).catch(function () {
                    vm.TaskData();
                });
                return;
            }
            if (vm.groupBy === 'assignee') {
                if (targetRowKey === '__unassigned__') {
                    vm.TaskData();
                    return;
                }
                var userId = targetRowUserId;
                if (!userId) {
                    var matchedUser = (vm.ProjectUsers || []).find(function (u) {
                        return String((u && u.name) || '').trim().toLowerCase() === String(targetRowKey).trim().toLowerCase();
                    });
                    userId = matchedUser && matchedUser.value ? matchedUser.value : '';
                }
                if (!userId) {
                    vm.TaskData();
                    return;
                }
                var userPayload = {
                    BacklogId: taskData.task_id,
                    ProjectId: vm.ProjectId,
                    UserId: userId
                };
                DataService.UpdateAssignUser(JSON.stringify(userPayload)).then(function () {
                    vm.TaskData();
                }).catch(function () {
                    vm.TaskData();
                });
                return;
            }
            vm.TaskData();
        },
        updateTaskStatus(itm, onDone) {
            var vm = this;
            var obj = {
                ID: itm.task_id,
                StatusId: itm.StatusId,
                IsFor: itm.IsFor
            };
            var objectPostString = JSON.stringify(obj);

            DataService.CommonUpdateStatus(objectPostString).then(function (response) {
                // Reset update flag
                vm.isUpdatingTask = false;
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
                vm.sourceBoardId = null;

                if (response.data.result == '0') {
                    // Success - update grouped field first (if any), then refresh.
                    if (typeof onDone === 'function') {
                        onDone();
                    } else {
                        vm.TaskData();
                    }
                    vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t('Task')]), "success", true, vm.$t("Alert"));
                } else {
                    // Error - refresh to restore state
                    vm.TaskData();
                    vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t("Alert"));
                }
            }).catch(function (error) {
                // Error - refresh to restore state
                vm.isUpdatingTask = false;
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
                vm.sourceBoardId = null;
                vm.TaskData();
                vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t("Alert"));
                console.error('Error updating task status:', error);
            });
        },
        stripHtmlTags(str) {
            if (!str) return '';
            return String(str).replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
        },
        getTaskDesc(task) {
            var raw = task.task_description;
            if (!raw || raw === '') return '';
            var plain = this.stripHtmlTags(raw);
            return plain || '';
        },
        getTaskProgress(task) {
            var total = parseInt(task.TotalTask, 10);
            var done = parseInt(task.CompleteTask, 10);
            if (!total || isNaN(total) || total <= 0) return 0;
            if (isNaN(done) || done < 0) done = 0;
            return Math.min(100, Math.round((done / total) * 100));
        },
        getTaskAge(task) {
            var startDate = task.planned_start_date;
            if (!startDate || startDate === '') return null;
            var start = new Date(startDate);
            if (isNaN(start.getTime())) return null;
            var diffDays = Math.floor((new Date() - start) / (1000 * 60 * 60 * 24));
            if (diffDays < 0) return null;
            if (diffDays === 0) return 'Today';
            return diffDays + 'd';
        },
        getTaskAgeClass(task) {
            var startDate = task.planned_start_date;
            if (!startDate || startDate === '') return '';
            var start = new Date(startDate);
            if (isNaN(start.getTime())) return '';
            var diffDays = Math.floor((new Date() - start) / (1000 * 60 * 60 * 24));
            if (diffDays > 14) return 'age-danger';
            if (diffDays > 7) return 'age-warning';
            return 'age-normal';
        },
        DeleteStatus: async function (data) {
            var id = data.board_id;
            var vm = this;
            var url = 'controller=Project&action=DeleteBoard'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    var val = "";
                    vm.isLoading = true;
                    if (id == null) {
                        $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                            if (val.length > 0)
                                val += ',';
                            val += $(this).val();
                        });
                    }
                    else {
                        val = id;
                    }
                    if (val != null) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                            var postJSON = {
                                ids: val,
                                moduleName: "PROJECT",
                                refCode: "TALYGEN_GLOBAL_BOARD"
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                vm.isLoading = false;
                                if (response.data[0].Status == "Success") {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Board')]), "success", true, vm.$t("Alert"));
                                    vm.TaskData();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Board')]), "warning", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                    }
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
            vm.isLoading = false;
        },
    }

}
</script>

