<template>
    <section>
        <div class="my-popups">
            <loader :is-visible="isLoading"></loader>
            <div class="modal d-block">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header theme-primary partition-full d-flex">
                            <h4 class="modal-title">{{ $t('AddTeam') }}</h4>
                            <button type="button" class="close" v-on:click="Cancel">
                                <em class="fa fa-times" aria-hidden="true"></em>
                            </button>
                        </div>                    
                        <div class="col-md-12 p-3" v-if="!IsShowUser">
                            <div class="heading-border">
                                <h5 class="h5">
                                    <span>Add </span>
                                </h5>
                            </div>
                        </div> 
                       
                            <div class="col-md-12 pt-2" v-if="!IsShowUser">
                            <div class="listing">
                                <div class="table-responsive table-fix-header float-left" style="max-height:530px;">
                                    <table id="mainTable" class="table table-bordered dt-responsive nowrap mt-0">
                                        <thead class="thead-bg">
                                            <tr>
                                                <th style="min-width:150px;"><span>{{ $t('User') }}</span></th>
                                                <th><span>{{ $t('Virtual User') }}</span><span class="float-left text-danger"></span></th>
                                                <th><span>{{ $t('Virtual User Track Only') }}</span></th> 
                                            </tr>                                               
                                        </thead>
                                        <tbody>
                                       <tr  v-for="(item,index) in GetTeamMemberData"  v-bind:data-id="item.value" v-bind:data-index="index">
                                  
                                       <td class="sorting_1">{{item.UserName}}</td>
                                       <td style="position:relative; overflow: visible !important;" class="sorting_1"> 
                                            <multiselect 
                                                placeholder="SelectUser" 
                                                :max-height="150"
                                                v-model="item.VirtualUserMultiple"  
                                                label="name" 
                                                track-by="value" 
                                                :limit="2"
                                                :options="item.VirtualUsers"
                                                :multiple="true" 
                                                :taggable="true">
                                            </multiselect>
                                        </td>
                                       <td class="sorting_1">
                                        <div>
                                        <label class="switch w70">
                                              <input v-bind:disabled="item.TEAM_PROJECT_USER_TYPE_ID !=3" class="form-check-input custom-control-input dynamic" type="checkbox"
                                               v-model="item.VirtualUserTrackOnly" v-bind:name="'IsLogin'"
                                               v-on:change="checkForAutoCreateEnable(item.VirtualUserTrackOnly)"
                                               v-disabled="disabled" />
                                            <span class="slider round" style="cursor:default;">
                                              <span class="slider-yes">{{ $t('Yes') }}</span>
                                              <span class="slider-no">{{ $t('No') }}</span>
                                           </span>
                                         </label>
                                        </div>
                                        </td>
                                       </tr>
                                       <tr style="cursor:initial;" v-if="GetTeamMemberData.length ==0">
                                        <td class="text-center text-danger" colspan="2">{{$t("No Record Found")}}</td>
                                      </tr>
                                     </tbody>
                                    </table>
                                    
                                </div>
                            </div>
                        </div>
                       

                        <div class="row flex-row-reverse mt-3 mb-3">
                            <div class="col-lg-6 text-right">
                                <a href="javascript:;" class="btn btn-success save-btn mr-2" v-on:click="SaveVirtualUSer()" title="Save">
                                    <i class="fa fa-save pr-2"></i>{{ $t('Save') }}
                                </a>
                                <a href="javascript:;" class="btn btn-danger mr-2" v-on:click="Cancel()" title="Cancel">
                                    <i class="fa fa-close pr-2"></i>{{ $t('Cancel') }}
                                </a>
                            </div>
                        </div>                 
                    </div>
                </div>
            </div>
        </div>
        <AddVirtual :ProjectName="ProjectName" />
    </section>
</template>
<script>
import DataService from '../../services/DataService';

export default {
    props: {
        ProjectName: {
            type: String,
            required: true 
        }
    },
    data() {
        return {
            isLoading: false,
            GetTeamMemberData: [],
            projectId:0,
            projectTeams: [],
            GetVirtualUserList:[],
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [
                {
                    layoutType: "triple",
                    Data: [
                        {
                            astype: "TextField",
                            label: "",
                            name: "FirstName",
                            value: "",
                            validationRules: { "required": true, max: 4000 },
                        },
                         {
                        astype: "MultiSelectField",
                            label:"",
                            name: "SelectUser",
                            value: "",
                            mode: "tag",
                            placeholder: "",
                            config: {
                                options: []
                            },
                            validationRules: {
                                "required": true,
                                "regex": /^[a-zA-Z0-9\s]*$/
                            },
                            disabled: false,
                            
                        },
                        {
                            astype: "toggleField",
                            label: this.$t(),
                            name: "CheckBoxField",
                            value: "",
                            placeholder: "",
                            config: {
                                options: [{ name: "", value: "true" }],
                                showAddIcon: false,
                                onChange: this.GetCheckBoxValue
                            },
                            validationRules: "",
                        }
                    ]
                }
            ],
            userId: null,
            companyId: null,
            UserType: null,
            IsShowUser: false,
            updatecomponent: 0
        }
    },
    created: async function () {
        var ths = this;
        ths.projectId = ths.$route.params.projectId;
        ths.GetProjectVirtualUserbyId();
    },
    methods: {
        GetProjectVirtualUserbyId: async function () {
            var ths = this;
            var url = `projectId=${ths.projectId}`;
            await DataService.GetProjectVirtualUserbyId(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.length > 0) {                      
                        ths.GetTeamMemberData=response.data;
                        ths.GetTeamMemberData.forEach(function (element) {
                            const newVirtualUsers = [];
                            if(element.VirtualUserMultiple.length>0){
                                element.VirtualUserMultiple.forEach(item => {
                                    item.name = item.Name;   // new key
                                    item.value = item.UserId; // new key
                                    delete item.Name;         // remove old key
                                    delete item.UserId;       // remove old key
                                });
                            }
                           if(element.VirtualUsers.length>0){
                                element.VirtualUsers.forEach(function (itm) {
                                    var obj = {
                                        value: itm.UserId,
                                        name: itm.Name
                                    };
                                    newVirtualUsers.push(obj);
                                });
                                element.VirtualUsers = newVirtualUsers;
                           }                            
                        });
                    }
                }
            })
        },
        SaveVirtualUSer() {
            var vm = this;  
            const filtered = vm.GetTeamMemberData.filter(item => item.VirtualUserMultiple && item.VirtualUserMultiple.length > 0);
            filtered.forEach(item => {
                if (item.VirtualUserMultiple && item.VirtualUserMultiple.length > 0) {
                    item.VirtualUser = item.VirtualUserMultiple.map(v => v.value).join(",");
                } else {
                    item.VirtualUser = "";
                }
            });
            DataService.ProjectVirtualUser(filtered).then(function (response) {
                if (response.data.status== "Success") {                   
                    vm.ShowAlert(vm.$t('AddedSuccess',[vm.$t('VirtualUSer')]), "success", true,  vm.$t("Alert"));
                    vm.$parent.GetVirtualUserConfiguration();
                    vm.Cancel();                    
                }
                else {
                    vm.ShowAlert(vm.$t('UnknownErrorOccur'), "failure", true, vm.$t("Alert"));
                }
            }); 
        },         
        Cancel() {
            this.$parent.VirtualListingSachema = false;
        },
        checkForAutoCreateEnable(){

        }      
    }
}
</script>
