<template lang="en">
<section>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full d-flex">
                        <h4 v-if="expenseLimitId == 0" class="modal-title">{{ $t('Add an Expense Limit') }}</h4>
                        <h4 v-else-if="expenseLimitId > 0" class="modal-title">{{ $t('Edit an Expense Limit') }}</h4>
                        <button type="button" class="close" @click="Cancel">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <dynamic-form ref="dynamicform" lang="en" :mandatorytext="$t('MandatoryString')" :buttons="commentButtons" v-on:OnSubmit="onSubmit" :schema="FormSchema"></dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
    <AddExpenseLimit  />
    <AddExpense v-if="AddExpense" ></AddExpense>
</section>
</template>

<script>
import DataService from '../../services/DataService';
import AddExpense from './AddExpense.vue';
export default {
    components: {
        AddExpense
    },
    props: {
        
        expenseLimitId: {
            type: Number,
            required: true
        },
          ProjectBudget: {
            type: Number,
            required: true
        }
    },
    data() {
        return {
            noRecord: false,
            TotalRecords: 0,
            isLoading: false,
            taskOptions: [],
            arrUserList: [],
            ccOption: [],
            progress: 0,
            projectId: 0,
            userId: '',
            companyId: '',
            startDate: '',
            dueDate: '',
            AddExpense: false,
            StatusId:1001,
            FormSchema: [{
                    layoutType: "triple",
                    Data: [{
                            astype: "SelectField",
                            label: this.$t('Expense Category'),
                            name: "ExpenseCategory",
                            value: "",
                            placeholder: "",
                            config: {
                                showAddIcon: true,
                                onAddButtonClick: this.openaddtagpopup,
                                options: []
                            },
                            placeholder: "",
                            validationRules: {
                                "required": true
                            },
                            disabled: false,
                        },
                        {

                            astype: "DateField",
                            label: this.$t("Start Date"),
                            name: "StartDate",
                            value: new Date(),
                            placeholder: this.$t("StartDate"),
                            validationRules: {
                                required: true,
                            },
                            config: {
                                mode: "date",
                                format: "M/D/YYYY"
                            }
                        },
                        {
                            astype: "DateField",
                            label: this.$t("End Date"),
                            name: "EndDate",
                            value: new Date(),
                            placeholder: this.$t("EndDate"),
                            validationRules: {
                                required: true,
                            },
                            config: {
                                mode: "date",
                                format: "M/D/YYYY"
                            },

                        },

                        {
                            astype: "MultiSelectField",
                            label: this.$t('Select User(s)'),
                            name: "SelectUser",
                            value: "",
                            mode: "tag",
                            placeholder: "",
                            config: {
                                options: []
                            },
                            validationRules: {
                                "required": true
                            },
                            disabled: false,

                        },
                        {
                            astype: "NumericField",
                            label: this.$t('Max. Expense Allowed'),
                            name: "MaxExpenseAllowed",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true,
                                max: 20
                            },
                            disabled: false,
                        },
                        {
                            astype: "NumericField",
                            label: this.$t('Expense Allowed Per Day'),
                            name: "ExpenseAllowedPerDay",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true,
                                max: 20
                            },
                            disabled: false,
                        },
                        {
                            astype: "CheckBoxField",
                            label: this.$t('Max. Expense Allowed'),
                            name: "ExpenseAllowed",
                            value: "",
                            placeholder: "",
                            config: {
                                options: [{
                                    name: "",
                                    value: "true"
                                }],
                                showAddIcon: false,
                                onChange: this.GetCheckBoxValue
                            },
                        },
                        {
                            astype: "CheckBoxField",
                            label: this.$t('Approval required per transaction:'),
                            name: "Approvalrequiredpertransaction",
                            value: "",
                            placeholder: "",
                            
                            config: {
                                options: [{
                                    name: "",
                                    value: "true"
                                }],
                                showAddIcon: false,
                                onChange: this.GetCheckBoxValue
                            },
                        },
                    ]
                },

            ],
            commentButtons: [{
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Cancel,
                },
            ],
            ProjectBudgets:0,
        }
    },
    async created() {
        
        var vm = this;
        vm.projectId = vm.$route.params.projectId;
        vm.ProjectBudgets = vm.ProjectBudget;
        // vm.FormSchema[0].Data[4].validationRules.max = vm.ProjectBudgets.toString().length +1;
        // vm.FormSchema[0].Data[5].validationRules.max = vm.ProjectBudgets.toString().length +1;
        vm.GetAllCategoriesByCompanyId();
        await vm.GetUserList();
        setTimeout(function () {
            if (vm.expenseLimitId > 0) {
                vm.GetExpenseLimit();
            }
        }, 500);

    },
    methods: {
      
        GetAllCategoriesByCompanyId: function () {
            var ths = this;
            var url = `CompanyId=${ths.companyId}`;
            DataService.GetAllCategoriesByCompanyId(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.length > 0) {
                        response.data.forEach((element) => {
                            var obj = {
                                value: element.EXPENSE_CATEGORY_ID,
                                name: element.CATEGORY_NAME
                            }
                            ths.FormSchema[0].Data[0].config.options.push(obj)
                            ths.$refs.dynamicform.UpdateKeyValue();

                        })
                    }
                }
            })
        },
        onSubmit(formfields, val) {
            var vm = this;
            var val = "";
            vm.FormSchema[0].Data[3].value.forEach((itm) => {
                val += itm.value;
                val += ',';
            });
            var objData = {
                ExpenseLimitId: vm.expenseLimitId == null ? 0 : vm.expenseLimitId,
                ProjectId: vm.projectId == null ? 0 : vm.projectId,
                ExpenseCategoryId: formfields.ExpenseCategory,   
                EXPENSE_LIMIT_FROM: vm.$options.filters.formatDateYMD(formfields.StartDate),         
                EXPENSE_LIMIT_TO: vm.$options.filters.formatDateYMD(formfields.EndDate),             
                Users: val,
                ExpenseMax: formfields.MaxExpenseAllowed,                                               
                ExpensePerDay: formfields.ExpenseAllowedPerDay,  
                ExpenseOverLimit: formfields.ExpenseAllowed == 'true' ? true : false,  
                ExpenseTransactionApproval: formfields.Approvalrequiredpertransaction == 'true' ? true : false, 
                StatusId:vm.StatusId
            };

            
            if (Number(objData.ExpenseMax) < Number(objData.ExpensePerDay)) {
                vm.ShowAlert(vm.$t('Themaximumallowedexpense', [vm.$t('Expense')]), "warning", true, vm.$t("Alert"));
                return;
            }
             vm.isLoading=true;
            var objectPostString = JSON.stringify(objData);
            DataService.SaveExpenseLimit(objectPostString).then(function (response) {
                
                if(response.data.statusMessage == 'ExpenseLimitGraterThenProjectBudget')
                    {
                        vm.ShowAlert(vm.$t('ExpenseLimitGraterThenProjectBudget', [vm.$t('Expense')]), "failure", true, vm.$t("Alert"));
                    }
               else  if (response.data.msg == "Save") {
                    vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t('Expense')]), "success", true, vm.$t("Alert"));
                    vm.$parent.ExpenseListing();
                    vm.Cancel();
                } else {
                    if (response.data.msg === '0') {
                        vm.ShowAlert(vm.$t('AddedError', [vm.$t('Expense')]), "failure", true, vm.$t("Alert"));
                    } else {
                        if (vm.expenseLimitId == 0) {
                            vm.ShowAlert(vm.$t('ExpenseSaveSucessfully', [vm.$t('Expense')]), "success", true, vm.$t("Alert"));
                        } else if (vm.expenseLimitId > 0) {
                            vm.ShowAlert(vm.$t('ExpenseUpdatedSucessfully', [vm.$t('Expense')]), "success", true, vm.$t("Alert"));
                        }
                        vm.Cancel();
                    }
                }
                  vm.isLoading=false;
            });
          
        },
  
        GetExpenseLimit: async function () {
            
            var vm = this;
            var url = `expenseLimitId=${vm.expenseLimitId}`;
                 vm.isLoading=true;
            await DataService.GetExpenseLimit(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.length > 0) {
                        const Expense = response.data[0];
                        vm.$refs.dynamicform.updateProperty("ExpenseCategory", "value", Expense.EXPENSE_CATEGORY_ID);
                        vm.$refs.dynamicform.updateProperty("StartDate", "value", Expense.EXPENSE_LIMIT_FROM);
                        vm.$refs.dynamicform.updateProperty("EndDate", "value", Expense.EXPENSE_LIMIT_TO);
                        var userData = Expense.USER_ID;
                        userData = userData.replace(/,$/, ''); 
                        var userDataArray = userData.split(',');
                        var bindArrUser = []; 

                        for (var i = 0; i < userDataArray.length; i++) {
                            var userList = vm.arrUserList.filter(x => x.UserId == userDataArray[i]); // Fixed: use userDataArray[i] instead of ccuserArray[i]
                            userList.forEach((element) => {
                                var obj = {
                                    value: element.UserId,
                                    label: element.UserName
                                };
                                bindArrUser.push(obj);
                            });
                        }
                        vm.ProjectBudget=Expense.PROECT_BUDGET;
                        vm.$refs.dynamicform.updateProperty("SelectUser", "value", bindArrUser);
                        vm.$refs.dynamicform.updateProperty("MaxExpenseAllowed", "value", Expense.EXPENSE_MAX);
                        vm.$refs.dynamicform.updateProperty("ExpenseAllowedPerDay", "value", Expense.EXPENSE_PER_DAY);
                        vm.$refs.dynamicform.updateProperty("ExpenseAllowed", "value", Expense.EXPENSE_OVER_LIMIT == 1 ? "true" : false);
                        vm.$refs.dynamicform.updateProperty("Approvalrequiredpertransaction", "value", Expense.EXPENSE_TRANS_APPROVAL == 1 ? "true" : false);
                        vm.StatusId=Expense.STATUS_ID;
                        vm.$refs.dynamicform.UpdateKeyValue();
                    }
                }
                vm.isLoading=false;
            });
        },
        GetUserList: async function () {
            var ths = this;
            var url = `CompanyId=${ths.companyId}&UserId=${ths.userId}&isActive=1&isIncludedLoginUserId=true&moduleName=&projectIds=${String(ths.projectId == null ? 0 : ths.projectId)}`;
            await DataService.GetUserList(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.length > 0) {
                        ths.arrUserList = response.data;
                        response.data.forEach((element) => {
                            var obj = {
                                value: element.UserId,
                                name: element.UserName
                            }
                            ths.FormSchema[0].Data[3].config.options.push(obj)
                            ths.$refs.dynamicform.UpdateKeyValue();

                        })
                    }
                }
            })
        },
        openaddtagpopup() {
            var vm = this;
            vm.AddExpense = true;
        },
        Cancel() {
            this.$parent.ExpenseLimitSchema = false;
        },
        CloseAssociate() {
            var vm = this;
            vm.$parent.IsAssociateShow = false;
        },
    }
}
</script>
