<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('Move') }} {{ $t(NewTabName) }} </h4>
                        <button type="button" class="close" v-on:click="CloseManageTasks">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>   
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default{
    props:{
        BackLogData:{
            type:Object,
            required:true
        },
        NewTabName:{
            type:String,
            require: true
        },
        AssignTabTabName:{
            type:String,
            require: true
        },
        AssignSprintTab:{
            type:String,
            require: true
        } 
    },
    data(){
        return{
            isLoading:false,
            ProjectBackLogId:0,
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [               
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Move To'),
                            name: "MoveTo",
                            value: "", 
                            config: {
                                onChange: this.ChangeMoveType,
                                options: []
                            },                           
                            placeholder: this.$t('Move To'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Choose Epic'),
                            name: "ChooseEpic",
                            visibility: false,
                            value: "", 
                            config: {                                
                                options: []
                            },                           
                            placeholder: this.$t('Epic'),
                            validationRules: { "required": false, max: 100 },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Sprint'),
                            name: "ChooseSprint",
                            visibility: false,
                            value: "", 
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Sprint'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "MultiSelectField",                                                
                            label: this.$t('Assignee'),
                            name: "Assignee",
                            mode:"tag",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select'),
                            validationRules: { "required": false, max: 100 },
                        },
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Priority'),
                            name: "Priority",
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Priority'),
                            validationRules: { "required": true, max: 100 },
                        },
                       
                        {
                            astype: "SelectField",                                                
                            label: this.$t('Parent'),
                            name: "Parent",
                            visibility: false,
                            value: "",  
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Parent'),
                            validationRules: { "required": false, max: 100 },
                        }                                            
                    ]
                }                
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseManageTasks,
                },
            ],
            ProjectId:null,
            TeamMemberData:[]
        }
    },
    created:async function(){        
        var ths =this;
        ths.ProjectId=parseInt(ths.$route.params.projectId);
        if(ths.BackLogData.parent_task_id != null){
            ths.FormSchema[0].Data[5].visibility=true;
            await ths.GetParentTask();       
        } 
        ths.FormSchema[0].Data[2].label=`${ths.$t(ths.AssignSprintTab)}`;
        ths.FormSchema[0].Data[3].label=`${ths.$t('Select')} ${ths.$t(ths.AssignTabTabName)}`;       
        await ths.GetAssignee();
        await ths.GetProjectPriority();
        await ths.GetProjectBacklogMoveType(); 
        if(ths.BackLogData.User_id != null){
            setTimeout(function () {
                    ths.BindAssigenedUsers();
            }, 2000);
        }
        ths.BindBackLogDetail(ths.BackLogData);

       
    },  
    methods:{
        BindBackLogDetail(data){
            var vm=this;
            vm.FormSchema[0].Data[5].value =data.parent_task_id;
            vm.FormSchema[0].Data[4].value =data.Priority_id;
            vm.FormSchema[0].Data[2].value =data.sprint_id==null?"":data.sprint_id;
            vm.FormSchema[0].Data[3].value =data.Assign;
        },
        async BindAssigenedUsers(){            
            var vm =this;
            const userIdArray = vm.BackLogData.User_id.split(',').map(id => parseInt(id, 10));
            const filteredData= vm.TeamMemberData.filter(member => userIdArray.includes(parseInt(member.value, 10)));
            var UserData=[];
            filteredData.forEach((element)=>{
                let obj={
                    value:element.value,
                    label:element.name
                }
                UserData.push(obj);                        
            })
            vm.FormSchema[0].Data[3].value=UserData; 
        }, 
        async GetParentTask() {
            var vm = this;
            var url = `id=&moduleName=PROJECT&type=GET_PROJECT_PARENT_TASK&search=&refId=${vm.BackLogData.parent_task_id}`;             
            await DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(element => {
                                let obj = {
                                    name: element.name,
                                    value: element.value=='Sprint'?'':element.value
                                }
                                vm.FormSchema[0].Data[5].config.options.push(obj);
                            });  
                            vm.$refs.AssignTagForm.UpdateKeyValue();                          
                        }             
                    }
                }
            })
        },
        async GetProjectBacklogMoveType(){
            var vm=this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_BACKLOG_MOVE_TYPE&search=&refId=`;
            await DataService.GetDDLData(url).then((response)=>{                 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            response.data.DATA.forEach(item=>{                                
                                let obj={
                                    value:item.value,
                                    name:item.name
                                };
                                vm.FormSchema[0].Data[0].config.options.push(obj);
                            })  
                            vm.$refs.AssignTagForm.UpdateKeyValue();                           
                        }
                    }
                }
            })
        },
        async GetEpic(){
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=PROJECT&type=PROJECT_Epic&search=&refId=`;
            await DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            var SprintData=response.data.DATA;
                            SprintData.forEach(element => {
                                let obj={
                                    name:element.name,
                                    value:element.value
                                }
                                this.FormSchema[0].Data[1].config.options.push(obj);
                            });
                            this.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
            })
        },
        async GetProjectSprint(){            
            var url = `id=&moduleName=PROJECT&type=PROJECT_SPRINT&search=&refId=${this.ProjectId}`;
            await DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            var SprintData=response.data.DATA;
                            this.FormSchema[0].Data[2].config.options=[];
                            SprintData.forEach(element => {
                                let obj={
                                    name:element.name,
                                    value:element.value
                                }
                                this.FormSchema[0].Data[2].config.options.push(obj);
                            });                            
                        }
                        this.$refs.AssignTagForm.UpdateKeyValue();
                    }
                }
            })
        },
        ChangeMoveType:function(){
            var ths=this;
            var chktype=ths.FormSchema[0].Data[0].value;
            if(chktype=='E'){
                ths.FormSchema[0].Data[1].visibility=true;
                ths.FormSchema[0].Data[2].visibility=false;                
                ths.GetEpic();
            }
            else if(chktype=='S'){
                ths.FormSchema[0].Data[1].visibility=false;
                ths.FormSchema[0].Data[2].visibility=true;
                ths.GetProjectSprint();
            }
            else{
                ths.FormSchema[0].Data[1].visibility=false;
                ths.FormSchema[0].Data[2].visibility=false;
            }
        },  
        CloseManageTasks(){
            this.$parent.IsManageTasks=false;
        },
        async GetAssignee(){
            var vm=this;       
            var url = `id=${this.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            vm.TeamMemberData=response.data.DATA;
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    value: element.value,
                                    name: element.name
                                }
                                vm.FormSchema[0].Data[3].config.options.push(obj);
                            })
                        }
                        else {
                            vm.$refs.AssignTagForm.UpdateKeyValue();  
                        }
                    }
                }
            });
        },
        async GetProjectPriority(){
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            await DataService.GetDDLData(url).then((response)=>{ 
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) { 
                            var PriorityData=response.data.DATA;
                            PriorityData.forEach(element => {
                                let obj={
                                    name:element.name,
                                    value:element.value
                                }
                                this.FormSchema[0].Data[4].config.options.push(obj);
                            });
                            this.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
            })
        },
        OnSubmit(){            
            var ths = this;
            ths.isLoading=true;
            var val = "";      
            if(ths.FormSchema[0].Data[3].value !=null){
                    ths.FormSchema[0].Data[3].value.forEach((itm)=>{                               
                    val += itm.value;
                    val += ',';
                });
            }
            var obj = {
                BackLogId: ths.BackLogData.task_id,
                Project_id:ths.ProjectId,
                Subject:ths.BackLogData.task_name,
                IssueTypeId:ths.BackLogData.task_type,
                SprintId:ths.FormSchema[0].Data[2].value,
                EpicId:ths.FormSchema[0].Data[1].value,
                PriorityId:ths.FormSchema[0].Data[4].value,
                ParentId:ths.FormSchema[0].Data[5].value,
                StatusId:ths.BackLogData.Status_id,
                UserId:val,
                BackLogDescription:ths.BackLogData.task_description,
                IsBacklog:false
            }
            DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {                
                ths.isLoading=false;
                if(response.data.result.DATA.length>0){ 
                    if(response.data.result.DATA[0].VALUE=='UPDATE') {
                        ths.ShowAlert(ths.$t('UpdatedSuccess',[ths.$t(ths.NewTabName)]),"success", true, ths.$t("Alert"));
                    }else{
                        ths.ShowAlert(ths.$t('AddedSuccess',[ths.$t(ths.NewTabName)]), "success", true,  ths.$t("Alert"));
                    } 
                    ths.CloseManageTasks();
                    ths.$parent.FetchBacklogListing();
                }else{
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            })        
        }
    }
}
</script>