<template>
  <section class="project-sales-pipeline-overview">
    <div class="projectoverviewbase">
    <CommonDashboard
      ref="commonDashboard"
      :project-id="projectId"
      :check-pm-user="checkPmUser"
      :new-tab-name="NewTabName"
      :ProjectOwner="ProjectOwner"
      :tabs-array="TabsArray"
      :Template_Name="Template_Name"
      @AddView="$emit('AddView', $event)"
    />
    <div class="card col-md-12 p-0 mb-3 spl-top-card">
      <div class="card-body col-12 pt-3 pb-4 px-3 common-dashboard-shell">
        <!-- <div class="spl-intel-head d-flex flex-wrap align-items-center justify-content-between gap-3 mb-4">
          <div class="spl-intel-brand d-flex flex-wrap align-items-center">
            <em class="fa fa-star spl-intel-star" aria-hidden="true"></em>
            <span class="spl-intel-title">Template Intelligence</span>
            <span class="spl-template-badge">{{ templateTag }}</span>
          </div>
          
        </div> -->

        <!-- <div class="spl-kpi-row">
          <div v-for="(k, idx) in kpiCards" :key="'kpi-' + idx" class="spl-kpi-col">
            <div class="spl-kpi-card" :class="'spl-kpi-card--' + k.tint">
              <div class="spl-kpi-value">{{ k.value }}</div>
              <div class="spl-kpi-label">{{ k.label }}</div>
            </div>
          </div>
        </div> -->

        <div class="row mx-0 mcc-chart-row align-items-stretch">
          <div class="col-lg-8 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Sales Pipeline Funnel</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasFunnelChart"
                  type="bar"
                  height="340"
                  :options="funnelChartOptions"
                  :series="funnelChartSeries"
                  :key="'spl-fn-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Revenue by Expense Categories ($k)</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasRevenueChart"
                  type="bar"
                  height="340"
                  :options="revenueChartOptions"
                  :series="revenueChartSeries"
                  :key="'spl-rv-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
        </div>

        <div class="row mx-0">
          <div class="col-12 px-2 section_pp">
            <div class="section mcc-overdue-section">
              <div class="section-header reddy cd-panel-head mcc-od-head">
                <span class="cd-panel-title mcc-od-title-wrap">
                  <em class="fa fa-clock-o mcc-od-icon" aria-hidden="true"></em>
                  <span>
                    <span class="mcc-od-title-main">Stale deals</span>
                    <span class="mcc-od-title-sub"> — No activity &gt;14 days</span>
                  </span>
                </span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="mcc-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
              </div>
              <div class="section-body border p-0">
                <div class="table-responsive mcc-od-wrap">
                  <table class="table mb-0 mcc-od-table">
                    <thead>
                      <tr>
                        <th>Deal name</th>
                        <th>Task_name</th>
                        <th>Planned Start Date</th>
                        <th>Planned End Date</th>
                        <th>Owner</th>
                        <th>Status</th>
                        <th>Priority</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="(row, idx) in staleDealRows" v-if="staleDealRows.length > 0"
                        :key="'st-' + idx"
                        :class="idx % 2 === 0 ? 'spl-stale-row--alt' : ''"
                      >
                        <td class="mcc-od-title" :title="row.dealName">{{ truncate(row.dealName, 40) }}</td>
                        <td :title="row.company">{{ truncate(row.company) || '—' }}</td>
                        <td :title="formatCellDate(row.start_date)" class="spl-deal-value">{{formatCellDate(row.start_date) }}</td>
                        <td :title=" formatCellDate(row.end_date)" class="spl-deal-value">{{ formatCellDate(row.end_date) }}</td>
                        <td :title="row.owner">{{ row.owner || '—' }}</td>
                        <td :title="row.status_name" class="text-white">
                        <span
                          class="mcc-stage-pill text-white"
                          :style="{ backgroundColor: row.status_bg_color || '#6c757d' }"
                        >
                          {{ row.status_name || '—' }}
                        </span>
                      </td>

                      <td :title="row.priority_name" class="text-white">
                        <span
                          class="mcc-stage-pill text-white"
                          :style="{ backgroundColor: row.color_code || '#f4511e' }"
                        >
                          {{ row.priority_name || '—' }}
                        </span>
                      </td>
                      </tr>
                      <tr v-if="!staleDealRows.length">
                        <td colspan="7" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <CriticalandBlockerDetail v-if="isCriticalandBlockerDetail" :Type="Template_Name"  :HeaderText="'Stale deals  — No activity &gt;14 days'"/>
    </div>
  </section>
</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';
function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}

/** Optional API: SALES_PIPELINE_DASHBOARD = { kpis, funnel[], revenue_by_stage[], stale_deals[] } */

// const FUNNEL_DEFAULT = [
//   { label: 'Prospecting', count: 42 },
//   { label: 'Qualified', count: 32 },
//   { label: 'Proposal', count: 18 },
//   { label: 'Negotiation', count: 9 },
//   { label: 'Closed-Won', count: 6, revenueNote: '$340k' },
// ];

const FUNNEL_COLORS = ['#9333ea', '#1a73e8', '#5c6bc0', '#f9ab00', '#34a853'];

// const REVENUE_DEFAULT = {
//   categories: ['Prospect', 'Qualified', 'Proposal', 'Negot.', 'Won'],
//   values: [180, 320, 410, 260, 720],
// };

const REVENUE_COLORS = ['#aecbfa', '#8ab4f8', '#669df6', '#4285f4', '#34a853'];

const DEFAULT_STALE_DEALS = [];

export default {
  name: 'SalesPipeline',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail},
  props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
    
  },
  data() {
    return {
      isCriticalandBlockerDetail:false,
      chartKey: 0,
      kpiCards: [],
      funnelWonNote: '',
      funnelStageCount: 0,
      hasFunnelChart: false,
      funnelChartSeries: [],
      funnelChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: {
          bar: {
            horizontal: true,
            barHeight: '70%',
            borderRadius: 4,
            distributed: true,
            dataLabels: { position: 'center' },
          },
        },
        dataLabels: {
          enabled: true,
          style: { fontSize: '11px', fontWeight: 700, colors: ['#fff', '#fff', '#fff', '#202124', '#fff'] },
          dropShadow: { enabled: false },
        },
        colors: [...FUNNEL_COLORS],
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
        xaxis: { labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
      },
      hasRevenueChart: false,
      revenueChartSeries: [],
      revenueChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: { bar: { borderRadius: 6, columnWidth: '58%', distributed: true } },
        colors: [...REVENUE_COLORS],
        dataLabels: { enabled: false },
        xaxis: { categories: [], labels: { style: { fontSize: '11px' } } },
        yaxis: {
          max: 800,
          tickAmount: 4,
          labels: {
            style: { fontSize: '11px' },
            formatter: (v) => (Number.isFinite(Number(v)) ? `$${Math.round(Number(v))}k` : ''),
          },
        },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
      },
      staleDealRows: [],
      BacklogId: null,
      AssigenedUser: null,
      IsAssignedUser: false,
    };
  },
  computed: {
    templateTag() {
      return (this.Template_Name || 'SALES PIPELINE').toString().replace(/_/g, ' ').toUpperCase();
    },
  },
  watch: {
    projectId() {
      this.loadChartData();
    },
  },
  mounted() {
    this.loadChartData();
  },
  methods: {
    openDashboardAddView() {
      
     this.isCriticalandBlockerDetail=true;
    },
    onFollowUp(row) {
      if (row && row.taskId != null) {
        this.AssignedUser(row.taskId, row.userIds);
      }
    },
    truncate(str, len) {
      if (str == null || str === '') return '—';
      const s = String(str);
      return s.length > len ? `${s.slice(0, len - 1)}…` : s;
    },
    loadChartData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          this.applySalesPayload(res || {});
          this.$nextTick(() => {
            this.chartKey += 1;
          });
        })
        .catch((e) => {
          console.error('Sales pipeline overview load:', e);
          this.applySalesPayload({});
        });
    },
    formatCellDate(val) {
      if (!val) return '—';
      const f = this.$options.filters && this.$options.filters.formatDate;
      if (typeof f === 'function') return f(val);
      try {
        const d = val instanceof Date ? val : new Date(val);
        if (Number.isNaN(d.getTime())) return '—';
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const yy = d.getFullYear();
        return `${mm}/${dd}/${yy}`;
      } catch (e) {
        return '—';
      }
    },
    applySalesPayload(res) {
      const sd = res.SALES_PIPELINE_DASHBOARD || res.sales_pipeline_dashboard || {};
      this.bindKpis(sd, res);
      this.bindRevenueChart(sd, res);
      this.bindStaleDeals(sd, res);
      this.bindFunnelChart(sd, res);

    },
    bindKpis(sd, res) {
      const k = sd.kpis || sd.kpi || {};
      let pipelineValue = k.pipeline_value != null ? String(k.pipeline_value) : sd.pipeline_value;
      if (pipelineValue == null && Array.isArray(res.EXPENSEDATA) && res.EXPENSEDATA.length) {
        const t = res.EXPENSEDATA.reduce((a, x) => a + n(x.CATEGORY_TOTAL_AMOUNT, 0), 0);
        if (t >= 1e6) pipelineValue = `$${(t / 1e6).toFixed(1)}M`;
        else if (t >= 1000) pipelineValue = `$${Math.round(t / 1000)}k`;
      }
      if (pipelineValue == null) pipelineValue = '$2.4M';

      let winRate = k.win_rate_mtd_pct != null ? `${n(k.win_rate_mtd_pct, 38)}%` : sd.win_rate_mtd;
      if (winRate == null) winRate = '38%';

      let avgCycle = k.avg_sales_cycle_days != null ? `${n(k.avg_sales_cycle_days, 24)}d` : sd.avg_sales_cycle;
      if (avgCycle == null) avgCycle = '24d';

      let stale = k.stale_deals_count ?? sd.stale_deals_count;
      if (stale == null) {
        const bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
        stale = bugs.length || 7;
      } else {
        stale = n(stale, 7);
      }

      this.kpiCards = [
        { label: 'Pipeline value', value: pipelineValue, tint: 'green' },
        { label: 'Win rate (MTD)', value: winRate, tint: 'blue' },
        { label: 'Avg sales cycle', value: avgCycle, tint: 'orange' },
        { label: 'Stale deals', value: stale, tint: 'rose' },
      ];
    },
    bindFunnelChart(sd, res) {        
      let rows = sd.funnel || sd.pipeline_funnel;
      if (!Array.isArray(rows) || !rows.length) {
        const st = Array.isArray(res.STAGEDATA) ? res.STAGEDATA : [];
        if (st.length) {
          rows = st.map((x) => ({
            label: x.stage_name || 'Stage',
            count: n(x.total_count ?? x.stage_progress, 0),
            revenueNote: x.revenue_note,
          }));
        }
      }
      if (!Array.isArray(rows) || !rows.length) {
        const status = Array.isArray(res.STAGEDATA) ? res.STAGEDATA : [];
        if (status.length) {
          rows = status.slice(0, 6).map((x) => ({
            label: x.status_name || x.component_name || 'Stage',
            count: n(x.total_count, 0),
          }));
        }
      }
      if (!Array.isArray(rows) || !rows.length) {
        rows=[];
      }

      const categories = rows.map((r) => r.label || r.name || r.stage || 'Stage');
      const data = rows.map((r) => n(r.count ?? r.deals ?? r.value, 0));
      const last = rows[rows.length - 1] || {};
      this.funnelWonNote = last.revenueNote || last.revenue_label || '';
      if (!this.funnelWonNote && /won|closed/i.test(String(last.label || ''))) {
        this.funnelWonNote = '$340k';
      }
      this.funnelStageCount = categories.length;

      const maxVal = Math.max(10, ...data, 1) * 1.12;
      const colors = rows.map((_, i) => FUNNEL_COLORS[i % FUNNEL_COLORS.length]);
      const labelColors = data.map((count, i) => {
        if (count <= 0) return '#5f6368';
        if (colors[i] === '#f9ab00' && count < 15) return '#202124';
        return '#fff';
      });

      const vm = this;
      this.hasFunnelChart = categories.length > 0 && data.some((v) => v > 0);
      this.funnelChartSeries = [{ name: 'Deals', data }];
      this.funnelChartOptions = {
        ...this.funnelChartOptions,
        colors,
        dataLabels: {
          ...this.funnelChartOptions.dataLabels,
          style: { ...this.funnelChartOptions.dataLabels.style, colors: labelColors },
          formatter(val, opts) {
            const i = opts.dataPointIndex;
            const c = n(val, 0);
            const lastIdx = vm.funnelStageCount - 1;
            if (i === lastIdx && vm.funnelWonNote) {
              return `${c} deals • ${vm.funnelWonNote}`;
            }
            return String(c);
          },
        },
        xaxis: { ...this.funnelChartOptions.xaxis, max: maxVal, categories },
      }
    },
    bindRevenueChart(sd, res) {
      
      let cats = [];
      let vals = [];
      const rev = res.EXPENSEDATA;
      if (rev && Array.isArray(rev) && rev.length) {
        cats = rev.map((x) => x.CATEGORY_NAME || 'Category');
        vals = rev.map((x) => n(x.USED_AMOUNT, 0) / 1000); 
      }
      const maxVal = Math.max(100, ...vals, 1) * 1.12;
      const colors = vals.map((_, i) => (i === vals.length - 1 ? '#34a853' : REVENUE_COLORS[i % (REVENUE_COLORS.length - 1)]));
      this.hasRevenueChart = cats.length > 0;
      this.revenueChartSeries = [{ name: 'Revenue ($k)', data: vals  }];
      this.revenueChartOptions = {
        ...this.revenueChartOptions,
        colors,
        xaxis: { ...this.revenueChartOptions.xaxis, categories: cats },
        yaxis: { ...this.revenueChartOptions.yaxis, max: maxVal },
      };
    },
    bindStaleDeals(sd, res) {
      let rows = sd.stale_deals || sd.stale_deal_rows;
      if (Array.isArray(rows) && rows.length) {
        this.staleDealRows = [];
        return;
      }
      const bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
      if (bugs.length) {
        this.staleDealRows = bugs.slice(0, 20).map((b) => ({
          dealName: b.stage_name || '—',
          company: b.task_number + ' ' + b.task_name  || '—',
          start_date: b.planned_start_date != null ? b.planned_start_date : '—',
          end_date:b.planned_end_date ?  b.planned_end_date : '--',
          status_name: b.status_name || '—',
          status_bg_color:b.status_bg_color || '--',
          owner: b.Created_by || '—',
          priority_name: b.priority_name != null ? b.priority_name : '—',
          color_code: b.color_code,
        }));
        return;
      }
      this.staleDealRows = DEFAULT_STALE_DEALS.map((r) => ({
        ...r,
        lastActivityLabel: `${r.lastActivityDays} days ago`,
      }));
    },
    normalizeStaleRow(r) {
      const days = r.last_activity_days != null ? n(r.last_activity_days, 0) : n(r.days_idle, 0);
      return {
        dealName: r.deal_name || r.name || r.title || '—',
        company: r.company || r.account || '—',
        valueLabel: r.value_label || r.value || (r.amount_k != null ? `$${n(r.amount_k, 0)}k` : '—'),
        stage: r.stage || r.stage_name || '—',
        owner: r.owner || r.owner_name || '—',
        lastActivityLabel: days > 0 ? `${days} days ago` : r.last_activity_label || '—',
        taskId: r.task_id,
        userIds: r.user_ids ?? r.UserIds,
      };
    },
    stagePillClass(stage) {
      const s = String(stage || '').toLowerCase();
      if (s.includes('qualif')) return 'spl-stage-pill--green';
      if (s.includes('prospect')) return 'spl-stage-pill--blue';
      if (s.includes('proposal') || s.includes('negot')) return 'spl-stage-pill--amber';
      if (s.includes('won') || s.includes('closed')) return 'spl-stage-pill--green';
      return 'spl-stage-pill--muted';
    },
    AssignedUser(val, users) {
      this.BacklogId = val;
      this.AssigenedUser = users;
      this.IsAssignedUser = true;
    },
  },
};
</script>

