<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered mw-800">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full d-flex">
                        <h4 class="modal-title">{{ MessegeId > 0 ? 'Edit' : 'Create' }} Project Message</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="DiscussionForm"
                            :mandatorytext='MandatoryString' v-on:OnSubmit="onSubmit">
                        </dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import DataService from '../../services/DataService';
export default {
    props: {
        message: {
            type: Object,
            required: true,
        },
        projectId: {
            type: Number,
            required: true,
        },
        MessegeId: {
            type: Number,
            required: true,
            default: 0
        },
        discussionType: {
            type: String,
            required: true,
            default: 0
        },
        discussionId: {
            type: Number,
            required: true,
            default: 0
        },
        Userid: {
            type: Number,
            required: false,
            default: 0
        }
    },
    data() {
        return {
            isLoading: false,
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [
                {
                    layoutType: "single",
                    Data: [{
                            astype: "TextAreaField",
                            label: this.$t('Message'),
                            name: "Message",
                            value: "",
                            placeholder: this.$t('Enter Message'),
                            validationRules: { "required": true, max: 4000 },  //required": false
                            config: {
                                rows: 7
                            }
                        }                     
                    ]
                }
            ],
            PageSize: 100,
            PageNumber: 1,
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Post Message",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-times pr-2'></i>Close",
                    onClick: this.Close,
                },
            ],
        }
    },
    async created() {
        
        if(this.MessegeId > 0){
            this.GetMessages();
        }
        if (this.discussionType.toLowerCase() == 'private') {
            this.FormSchema[0].Data[2].visibility = true;   // FIXED visibility
            this.FetchTeam();
        }
    },
    methods: {
        GetMessages: function () {
            
            var vm = this;
            var url = `messageId=${vm.MessegeId}&Type=M`;
            DataService.GetMessageDetails(url).then((response) => {
                if (response.status === 200) {
                    const data = response.data.result.DATA;
                    if (data.length > 0) {
                        const item = data[0];
                         this.FormSchema[0].Data[0].value = item.MESSAGE_BOARD_TITLE || "";
                    }
                }
            });
        },
        onSubmit: async function () {
        
        var vm = this;            
        vm.isLoading = true;        
        // Check if we're editing a main message (MessegeId > 0)
        const isEditing = vm.MessegeId > 0;        
        var jsonobj = {
            Id: isEditing ? -1 : 0, // -1 for edit, 0 for new (though this component only handles edits)
            MessageBoardId: vm.MessegeId > 0 ? vm.MessegeId : 0,
            DiscussionId: vm.discussionId || '',
            Title: this.FormSchema[0].Data[0].value,
            Description: null,
            Status_id: 1001,
            IsPushNotification: 0,
            IsClear: 0,
            Attachment: ''                
        };        
        var params = JSON.stringify(jsonobj);        
        try {
            const response = await DataService.SaveDisscussMessage(params);

            if(response.data.result.status == 'INSERT' || response.data.result.status == 'UPDATE'){
            vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t('Message')]), "success", true, vm.$t("Alert"));            
          
            vm.$emit('message-saved', {
                messageId: vm.MessegeId,
                isMainMessage: true, // This component only handles main message edits
                action: 'edit',
                data: jsonobj
            });
            
            vm.Close();
            }
        } catch (error) {
            console.error('Error saving message:', error);
            vm.ShowAlert(vm.$t('UnknownErrorOccur'), "failure", true, vm.$t('Alert'));
        } finally {
            vm.isLoading = false;
        }
        },
        Close() {
            this.$emit('close');
        }
    }
}
</script>