
<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('ShareFile') }}</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">

                        <div id="divsharefile" class="modal-body" style="height: auto; min-height: 0px; max-height: none;">
                            <div id="divshareuserlist" class="w-100 float-left">
                                <section id="divMainContent" class="main-content">
                                    <div class="container-fluid p-0">
                                        <div class="px-3 d-flex flex-wrap">
                                            <div class="mover-panel-box">
                                                <div class="row">
                                                    <div class="heading-border">
                                                        <h5 class="h5"><span>{{$t("Available_Users")  }}</span></h5>
                                                    </div>

                                                    <div class="listing mt-2">
                                                        <div class="table-responsive border-bottom-0">
                                                            <table id="example" class="table table-bordered">
                                                                <thead class="thead-bg">
                                                                    <tr>
                                                                        <th scope="col">{{ $t("UserName") }}</th>
                                                                    </tr>
                                                                </thead>
                                                            </table>
                                                        </div>
                                                        <div class="table-responsive border-top-0 mCustomScrollbar _mCS_7 mCS_no_scrollbar"
                                                            style="max-height:250px;min-height:250px;" id="divAvailUser">
                                                            <div id="mCSB_7"
                                                                class="mCustomScrollBox mCS-dark-thick mCSB_vertical mCSB_inside"
                                                                style="max-height: 249px;" tabindex="0">
                                                                <div id="mCSB_7_container"
                                                                    class="mCSB_container mCS_y_hidden mCS_no_scrollbar_y"
                                                                    style="position:relative; top:0; left:0;" dir="ltr">
                                                                    <table id="tblAvailUser" class="table table-bordered">

                                                                        <tbody>
                                                                            <tr userid="obj.UserId"
                                                                                v-for="obj in AvailableUsers"
                                                                                :key="obj.UserId">
                                                                              <td>
                                                                            <div class="custom-control custom-checkbox">
                                                                                <input 
                                                                                    type="checkbox" 
                                                                                    class="chkItems custom-control-input"
                                                                                    :userid="obj.UserId"
                                                                                    :username="obj.Name"
                                                                                    :value="obj.UserId" 
                                                                                    :id="'chk_avail_' + obj.UserId"
                                                                                    style="display: none;"
                                                                                >
                                                                                <label 
                                                                                    class="custom-control-label universal-custom-control-label pt-1"
                                                                                    :for="'chk_avail_' + obj.UserId"
                                                                                ></label>
                                                                            </div>
                                                                            <label class="form-check-label" for="Designation">
                                                                                {{ obj.Name }}
                                                                            </label>
                                                                        </td>
                                                                            </tr>
                                                                        </tbody>
                                                                    </table>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                            <div class="mover-controls ancArrowdata">
                                                <button id="AddAll" data-toggle-tooltip="tooltip" title=""
                                                    data-original-title="Move Right" @click="RightMove()"><i
                                                        aria-hidden="true" class="fa fa-angle-down fa-2x d-md-none"></i><i
                                                        aria-hidden="true"
                                                        class="fa fa-angle-right fa-2x d-none d-md-block"></i></button>
                                                <button id="RemoveAll" data-toggle-tooltip="tooltip" title=""
                                                    data-original-title="Move Left" @click="LeftMove()"><i
                                                        aria-hidden="true" class="fa fa-angle-up fa-2x d-md-none"></i><i
                                                        aria-hidden="true"
                                                        class="fa fa-angle-left fa-2x d-none d-md-block"></i></button>
                                            </div>
                                            <div class="mover-panel-box">
                                                <div class="row" id="divSelectedColumnsData">
                                                    <div class="heading-border">
                                                        <h5 class="h5"><span>{{ $t("AssignedUser") }}</span></h5>
                                                    </div>

                                                    <div class="listing mt-2">
                                                        <div class="table-responsive border-bottom-0">
                                                            <table id="example" class="table table-bordered">
                                                                <thead class="thead-bg">
                                                                    <tr>
                                                                        <th scope="col" style="width:85%;">{{ $t("UserName") }}
                                                                        </th>

                                                                        <th scope="col" style="width:15%;"
                                                                            class="thchangeheader">{{ $t("Actions") }}</th>
                                                                    </tr>
                                                                </thead>
                                                            </table>
                                                        </div>
                                                        <div class="table-responsive border-top-0 mCustomScrollbar _mCS_8 mCS_no_scrollbar"
                                                            id="divAssignedUser" style="max-height:250px;min-height:250px;">
                                                            <div id="mCSB_8"
                                                                class="mCustomScrollBox mCS-dark-thick mCSB_vertical mCSB_inside"
                                                                style="max-height: 249px;" tabindex="0">
                                                                <div id="mCSB_8_container"
                                                                    class="mCSB_container mCS_y_hidden mCS_no_scrollbar_y"
                                                                    style="position:relative; top:0; left:0;" dir="ltr">
                                                                    <table id="tblAssignedUser"
                                                                        class="table table-bordered">
                                                                        <tbody>
                                                                            <tr v-for="item in AssignedUser"
                                                                                :key="item.UserId">
                                                                                <td style="width: 85%;">
                                                                            <div class="custom-control custom-checkbox">
                                                                                <input 
                                                                                    type="checkbox" 
                                                                                    @change="ToggleNewColumn(item)"
                                                                                    class="chkItems custom-control-input"
                                                                                    :userid="item.UserId"
                                                                                    :username="item.Name"
                                                                                    :value="item.UserId"
                                                                                    :id="'chk_assigned_' + item.UserId"
                                                                                    style="display: none;"
                                                                                >
                                                                                <label 
                                                                                    class="custom-control-label universal-custom-control-label pt-1"
                                                                                    :for="'chk_assigned_' + item.UserId"
                                                                                ></label>
                                                                            </div>
                                                                            <label class="form-check-label">
                                                                                {{ item.Name }}
                                                                            </label>
                                                                        </td>
                                                                                <td style="width: 15%;"
                                                                                    class="text-center single-action">
                                                                                    <a href="javascript:;"
                                                                                        @click="DeleteItem(item)"
                                                                                        class="removeUser"
                                                                                        userid="item.UserId"
                                                                                        username="item.Name"><em
                                                                                            class="fa fa-trash action-icon text-danger actionicon_20"></em></a>
                                                                                </td>
                                                                            </tr>
                                                                        </tbody>
                                                                    </table>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <div class="col-lg-12 px-0 mt-2 text-right">
                                            <a href="javascript:;" class="btn btn-success mr-2" id="btnShare" title=""
                                                @click="SaveShareFile()" data-toggle-tooltip="tooltip"
                                                data-original-title="Save"><em class="fa fa-save pr-2 "></em>{{$t("Save")}}</a>

                                            <a href="javascript:;" class="btn btn-danger" id="ancCancelShare" title=""
                                                v-on:click="Close" data-toggle-tooltip="tooltip"
                                                data-original-title="Cancel"><em class="fa fa-close pr-2"></em>{{$t("Cancel")}}</a>
                                        </div>

                                    </div>

                                </section>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>

import DataService from '../../services/DataService';

export default
    {
        props: {
            ProjectId: {
                type: Number,
                required: true,
            },
            FileId: {
                type: Number,
                required: true,
            }
        },
        data() {
            return {

                userId: null,
                companyId: null,
                UserType: null,
                AvailableUsers: [],
                AssignedUser: [],
                SelectedUsersArray: [],

            }
        },
        created: function () {

            var ths = this;
            ths.userId = ths.GetUserInfo.ID;
            ths.companyId = ths.GetUserInfo.CompanyId;
            ths.UserType = ths.GetUserInfo.UserType;
            ths.GetAvailableAndAssignedListing();


        },
        methods: {

            GetAvailableAndAssignedListing: function () {
                
                var vm = this;

                var url = `ProjectId=${vm.ProjectId}&FileId=${vm.FileId}`;
                DataService.GetAvailableAndAssignedListing(url).then((response) => {
                    if (response.data.AvailableUsers.length > 0) {

                        vm.AvailableUsers = response.data.AvailableUsers;
                    }

                    if (response.data.AssignedUsers.length > 0) {

                        vm.AssignedUser = response.data.AssignedUsers.map(user => {

                            user.NewColumn = false;
                            return user;
                        });
                    }
                });
            },

            Close: function () {

                var vm = this;
                vm.$parent.IsShareFileShow = false;
            },

            DeleteItem: function (th) {

                var vm = this;
                vm.AvailableUsers.push({
                    UserId: th.UserId,
                    Name: th.Name
                });

                vm.AssignedUser = vm.AssignedUser.filter(function (user) {
                    return user.UserId !== th.UserId || user.Name !== th.Name;
                });
            },

            RightMove: function () {
                
                var vm = this;

                $("#tblAvailUser .chkItems:checked")
                    .not("[id^='chkAll']")
                    .each(function () {

                        var userId = $(this).attr("userid");
                        var userName = $(this).attr("username");

                        if (userId) {

                            vm.AssignedUser.push({

                                UserId: userId,
                                Name: userName,

                            });

                            var index = vm.AvailableUsers.findIndex(function (user) {
                                return user.UserId == userId;
                            });


                            if (index !== -1) {
                                vm.AvailableUsers.splice(index, 1);
                            }

                        }
                    });
            },

            LeftMove: function () {
                
                var vm = this;

                $("#tblAssignedUser .chkItems:checked")
                    .not("[id^='chkAll']")
                    .each(function () {

                        var userId = $(this).attr("userid");
                        var userName = $(this).attr("username");

                        if (userId) {

                            vm.AvailableUsers.push({

                                UserId: userId,
                                Name: userName,


                            });

                            var index = vm.AssignedUser.findIndex(function (user) {
                                return user.UserId == userId;
                            });


                            if (index !== -1) {
                                vm.AssignedUser.splice(index, 1);
                            }

                        }


                    });

            },

            ToggleNewColumn: function (user) {
                
                user.NewColumn = !user.NewColumn;
            },

            SaveShareFile: function () {
                
                var vm = this;
                // let SelectedUsers = vm.AssignedUser.filter(user => user.NewColumn === true);

                // SelectedUsers.forEach(user => {
                //     vm.SelectedUsersArray.push(user.USER_ID);  // or use any field as needed
                // });

                // var CommaSeparatedIds = vm.SelectedUsersArray.join(',');

                vm.AssignedUser.forEach(user => {
                    vm.SelectedUsersArray.push(user.UserId);  
                });
                var CommaSeparatedIds = vm.SelectedUsersArray.join(',');
                if(CommaSeparatedIds ==='' || CommaSeparatedIds =="")
                {
                    vm.ShowAlert(vm.$t("UserSelect"),'warning',true,vm.$t('Alert'));
                    return;
                }
                var url = `ProjectId=${vm.ProjectId}&FileId=${vm.FileId}&CommaSeparatedIds=${CommaSeparatedIds}`;
                DataService.SaveShareData(url).then((response) => {
                    if (response.data[0].Status == 'Success') {

                        vm.$parent.IsShareFileShow = false;
                        vm.ShowAlert(vm.$t("File_Shared_Successfully"),'success',true,vm.$t('Alert'));
                    }
                    else{
                        
                        vm.ShowAlert(vm.$t("Error"),'failure',true,vm.$t('Alert'));
                    }

                    
                });
            },
        },


    }

</script>

