<template>
    <section>
        <div>

            <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="true" ModuleName="PROJECT"
                SubModuleCode="PHASE" IdentityColumn="PHASE_ID" :HeaderText="$t(NewTabName)" :SearchFields="false"
                :ListData="ListingData" :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons"
                :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions" :LegendArray="[]"
                :ListDataCallBackFunction="FetchProjectPhaseList" :SortExp="SortExp" :SortBy="SortBy"
                :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod"
                v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata" :Key="Key">
                <template v-slot:slotdata="{ data }">
                    <template v-if="data.column.COLUMN_NAME == 'START_DATE'">
                        <span :title="data.row.START_DATE">
                            {{ data.row.START_DATE }}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'END_DATE'">
                        <span :title="data.row.END_DATE">
                            {{ data.row.END_DATE }}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'PHASE_NAME'">
                        <a :title="data.row.PHASE_NAME" @click="clickEventOfColumn(data.row)" href="javascript:;"
                            style="color: dodgerblue;cursor: pointer; white-space: nowrap;  word-wrap: break-word;  overflow: hidden; display: block;  text-overflow: ellipsis;">
                            {{ data.row.PHASE_NAME }}
                        </a>
                    </template>
                </template>
            </tg-list>

        </div>
        <AddProjectPhaseAssociate v-if="PhaseAssociate" :phase-list="ListingData" :NewTabName="NewTabName"
            :EditPhaseId="EditPhaseId" :TabsArray="TabsArray">
        </AddProjectPhaseAssociate>
        <!-- <AddPhase v-if="isAddPhase" :PhaseItem="PhaseItem" :phase-list="ListingData" :NewTabName="NewTabName"
            :TabsArray="TabsArray">
        </AddPhase> -->
    </section>

</template>
<script>
import DataService from '../../../../services/DataService.js';
import AddProjectPhaseAssociate from '../../../../components/Modal/AddProjectPhaseAssociate.vue';
// import AddPhase from '../../../../components/Modal/AddPhase.vue'
import schema from '../../../Project/Project/ProjectDetailLeftAllTabs/projectphaseSchema'
export default {
    components: { AddProjectPhaseAssociate },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        ProjectOwner: {
            type: String
        }
    },
    data() {
        return {
            Key: 0,
            leftSearchFields: [],
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            taskId: '',
            Headers: [],
            ListingData: [],
            searchCondition: '',
            Buttons: [],
            ProjectTaskListingpopup: false,
            PhaseAssociate: false,
            //isAddPhase: false,
            ProjectEndDate: '',
            UserType: null,
            ProjectStartDate: '',
            PhaseItem: '',
            EditPhaseId: null

        }
    },
    watch: {
        NewTabName: {
            handler(newTabName) {
                if (newTabName) {
                    this.updateButtons(newTabName);
                    this.updateHeaders(newTabName);
                }
            },
            immediate: true
        }
    },
    created: async function () {
        var ths = this;
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.userId = ths.GetUserInfo.ID;
        ths.UserType = ths.GetUserInfo.UserType;
        if (!this.Buttons || this.Buttons.length === 0) {
            this.Buttons = JSON.parse(JSON.stringify(schema.buttons));
        }
        if (!this.Headers || this.Headers.length === 0) {
            this.Headers = JSON.parse(JSON.stringify(schema.TableHeader));
        }
        if (this.NewTabName) {
            this.updateButtons(this.NewTabName);
            this.updateHeaders(this.NewTabName);
        }
        await ths.FetchProjectPhaseList();
        await ths.ProjectOverview();
        ths.CheckDisabled();
    },
    updated() {
        const divElement = document.getElementsByClassName('theme-primary partition p-actions-expand')
        if (divElement[0] && divElement[0].lastChild.className != 'p-name text-white') {
            const spanElement = document.createElement('span')
            spanElement.className = "p-name text-white"
            spanElement.textContent = this.$t(this.NewTabName);
            divElement[0].appendChild(spanElement);
        }
    },
    methods: {
        updateButtons(newTabName) {
            var vm = this;
            const buttonsCopy = JSON.parse(JSON.stringify(schema.buttons));
            if (newTabName && buttonsCopy && buttonsCopy.length > 0) {
                buttonsCopy.forEach((button, index) => {
                    if (button.callbackfunction === 'AddAssociate') {
                        buttonsCopy[index].title = `${vm.$t('Add')} ${vm.$t(this.NewTabName)}` + ' ' + this.$t('Associate');
                    }
                });
            }
            this.Buttons = buttonsCopy;
        },
        updateHeaders(newTabName) {
            this.Headers = JSON.parse(JSON.stringify(schema.TableHeader));
            var vm = this;
            if (newTabName && this.Headers && this.Headers.length > 0) {
                this.Headers.forEach(header => {
                    if (newTabName) {
                        if (header.COLUMN_NAME === 'PHASE_NAME') {
                            header.DISPLAY_NAME = vm.$t(this.NewTabName);
                        }

                    }
                });
            }
        },
        CheckDisabled() {
            const type = this.UserType;
            const hasAccess = this.checkPmUser || this.ProjectOwner;
            const isClient = type === 'CL' || type === 'NU';
            const isAdmin = type === 'CA' || type === 'PM';
            const buttons =
                isAdmin ? [true, true, true] :
                (isClient && hasAccess) ? [false, false, true] :
                [true, false, false];
            const result = isAdmin || (isClient && hasAccess);
            this.Buttons.forEach((b, i) => b.isvisible = buttons[i]);
            return result;
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${this.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {
                if (response.data != null > 0) {
                    vm.ProjectStartDate = response.data.planneD_START_DATE;
                    vm.ProjectEndDate = response.data.planneD_END_DATE;
                    vm.ProjectName = response.data.projecT_NAME;
                }
            });
        },
        BackToList: function () {
            var ths = this;
            ths.$router.push({ name: 'ProjectList' });
        },
        SetDateFormat: function (value) {
            var NDATE = value;
            var date = new Date(NDATE);
            var day = String(date.getDate()).padStart(2, '0');
            var month = String(date.getMonth() + 1).padStart(2, '0');
            var year = date.getFullYear();
            return `${day}/${month}/${year}`;
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchProjectPhaseList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        renderActions() { },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchProjectPhaseList();
        },
        commonHeaderButtonClick: function (event) {
            switch (event.callbackfunction) {
                case "Deletedata":
                    this.DeletedPhase();
                    break;
                case "AddAssociate":
                    this.AddAssociate();
                    break;               
                case "EditPhase":
                    this.EditPhase();
                    break;              
                case "BackToList":
                    this.BackToList();
                    break;
            }
        },
        AddAssociate: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddUpdatePhase'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.EditPhaseId = null;
                    vm.PhaseAssociate = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        DeletedPhase: function (event) {
            var vm = this;
            var val = "";
            vm.isLoading = true;
            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                if (val.length > 0)
                    val += ',';
                val += $(this).val();
            });
            if (val != null) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Phase")), function () {
                    var obj = {
                        ProjectId: vm.projectId,
                        PhaseIds: val
                    };
                    var objectPostString = JSON.stringify(obj)
                    DataService.DeletePhase(objectPostString).then(function (response) {
                        if (response.data.result.DATA[0].VALUE == 'SUCCESS') {
                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Phase')]), "success", true, vm.$t("Alert"));
                            vm.Buttons[2].isdisabled = true;
                            vm.isLoading = false;
                            vm.FetchProjectPhaseList();
                            vm.Key++;
                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Phase')]), "failure", true, vm.$t("Alert"));
                        }
                    });
                });
            }
            else {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
            }
            vm.isLoading = false;
        },
        EditPhase:async function () {
            var vm = this;
            var val = "";
            vm.isLoading = true;
            var url = 'controller=Project&action=AddUpdatePhase'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    var selectedIds = [];
                    $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                        if (val.length > 0)
                            val += ',';
                        val += $(this).val();
                        selectedIds.push($(this).val());
                    });
                    if (val != '' && selectedIds.length < 2) {
                        var id = Number(selectedIds[0]);
                        const item = vm.ListingData.find(x => x.PHASE_ID == id);
                        vm.PhaseItem = item;
                        this.isAddPhase = true;

                    }
                    else {
                        vm.ShowAlert(vm.$t("Pleaseselectatleastonerecord"), 'failure', true, vm.$t('Alert'));
                    }
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });

        },
        FetchProjectPhaseList: async function () {
            var vueObj = this;
            vueObj.isLoading = true;
            var params = `projectId=${vueObj.projectId}&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNum=${vueObj.PageNumber}`;
            await DataService.GetProjectPhaseList(params).then(function (response) {
                if (response.data.result.data.length > 0) {
                    vueObj.ListingData = response.data.result.data;
                    vueObj.ListingData.forEach((item) => {
                        item.isCheckBoxDisabled = false;
                        if (item.company_id == 0) {
                            item.isCheckBoxDisabled = true;
                        }
                        item.START_DATE = vueObj.$d(new Date(item.START_DATE));
                        item.END_DATE = vueObj.$d(new Date(item.END_DATE));
                    });
                    vueObj.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
                    vueObj.TotalPages = Math.ceil(vueObj.TotalRecords / vueObj.PageSize);
                } else {
                    vueObj.TotalRecords = 0;
                    vueObj.TotalPages = 1;
                    vueObj.ListingData = [];
                }
            });
        },
        async clickEventOfColumn(row) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdatePhase'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data || vm.checkPmUser || vm.ProjectOwner) {
                    vm.EditPhaseId = row.PHASE_ID;
                    vm.PhaseAssociate = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        }
    }
}
</script>