<template>
  <section>
    <loader :is-visible="isLoading"></loader>
    <div class="ticketsmallfix theme-primary partition p-actions-expand mt-2" style="overflow: visible;">
      <span class="p-name text-white">{{ $t('Component') }}</span>
      <span class="p-actions float-right">
        <a title="Add" href="javascript:;" class="p-action-btn text-white" @click="openAddModal">
          <em class="fa fa-plus"></em> <br>
          <span>{{ $t('Add') }}</span>
        </a>
        <a title="Delete" href="javascript:;" class="p-action-btn text-white" @click="deleteSelected(null)">
          <em class="fa fa-trash-o pr-2"></em> <br>
          <span>{{ $t('Delete') }}</span>
        </a>
        <a title="Back to list" href="javascript:;" class="p-action-btn text-white" @click="goBackToList">
          <em class="fa fa-angle-double-left pr-2"></em> <br>
          <span>{{ $t('BacktoList') }}</span>
        </a>
      </span>
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0 top-menu-tab border p-3">
      <div class="row p-0 pt-2 colcontrol">
        <div class="col float-left">
          <div class="form-group mb-2">
            <input class="form-control" :placeholder="dynamicPlaceholder" v-model="componentNameFilter"
              @keyup.enter="SearchByComponentName">
          </div>
        </div>
        <div class="col float-left">
          <div class="form-group mb-2">
            <Treeselect v-model="selectedStatus" :options="statusOptions" :placeholder="$t('Status')" :multiple="true"
              :limit="1" :limitText="getFilterLimitText" v-on:input="FetchData(selectedStatus, 'COMPONENT_BY_STATUS')">
            </Treeselect>
          </div>
        </div>
        <div class="col float-left">
          <div class="background-0 text-left form-check-inline">
            <a href="javascript:void(0);" class="btn btn-danger clearsearchtext px-4" @click="clearFilters">
              <em class="fa fa-refresh"></em>{{ $t('Clear') }}
            </a>
          </div>
        </div>
      </div>
    </div>

    <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="true" ModuleName="PROJECT"
      SubModuleCode="ProjectComponent" IdentityColumn="component_id" :HeaderText="$t('Component')" :ListData="fullList"
      :HeaderData="Headers" :widgets="widgets" :TotalRecords="TotalRecords" :SearchFields="false"
      :LegendArray="legendArray" :PageSize="pageSize" :CurrentPageNumber="pageNum" :SortExp="SortExp" :SortBy="SortBy"
      :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod"
      :ListDataCallBackFunction="listDataCallback" :RenderRowActionMethod="renderActions"
      v-on:ActionButtonClick="actionButtonClick" v-on:SortdataButtonClick="sortdata">
      <template v-slot:slotdata="{ data }">
        <template v-if="data.column.COLUMN_NAME == 'component_name'">
          <a @click="Edit(data.row)" class="text-primary" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.component_name }}
          </a>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'component_desc'">
          <span :title="data.row.component_desc" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.component_desc }}
          </span>
        </template>
          <template v-if="data.column.COLUMN_NAME == 'modified_at'">
          <span
            :title="data.row.modified_at == '' ? '--' : $options.filters.formatDate(data.row.modified_at)">
            {{ data.row.modified_at == '' ? '--' : $options.filters.formatDate(data.row.modified_at) }}
          </span>
        </template>
          <template v-if="data.column.COLUMN_NAME == 'created_at'">
          <span
            :title="data.row.created_at == null ? 'N/A' : $options.filters.formatDate(data.row.created_at)">
            {{ data.row.created_at == null ? 'N/A' : $options.filters.formatDate(data.row.created_at) }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'status_name'">
          <listing-status :isfor="'PROJECTCOMPONENT'" ref="updatestatus" v-bind:dataid="rowIdentity(data.row)"
            data-controller="Task" v-bind:statuslist="StatusList" v-bind:item="data"
            v-bind:parentid="rowIdentity(data.row)" dataController="Project" dataAction="BacklogStatusUpdate"
            v-bind:dataselected="data.row.status_name" v-bind:callbackfunction="listDataCallback"
            v-bind:isselectedvaluestring="true">
          </listing-status>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'TaskCount'">
          <div class="user-count-wrapper">
            <span>
              <a @click="OpenTaskModel(data.row.component_id)" class="text-dark single-action" href="javascript:;">
                <em class="fa fa-tasks"></em>
                <span class="noti-circle noti-green">{{ data.row.TaskCount }}</span>
              </a>
            </span>
          </div>
        </template>
      </template>
    </tg-list>
    <AddComponentModal v-if="isAddComponentModal" :componentData="ComponentData" @close="onCloseAddModal" />
    <TaskDetailModel v-if="isTaskModal" :Id="componentId" :Type="type" @close="onCloseAddModal" />
  </section>
</template>

<script>
import DataService from '../../../../services/DataService'
import AddComponentModal from '../../../../components/Modal/AddComponentModal.vue'
import TaskDetailModel from '../../../../components/Modal/TaskDetailModel.vue'
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'

export default {
  components: { Treeselect, AddComponentModal, TaskDetailModel },
  props: {
    checkPmUser: {
      type: Boolean,
      required: true
    },
    ProjectOwner: {
      type: Boolean,
      required: true
    },
    NewTabName: {
      type: String,
      require: true
    },
    TabsArray: {
      type: Array
    }
  },
  computed: {
    dynamicPlaceholder() {
      return `${this.$t('Component')} ${this.$t('Name')}...`
    }
  },
  data() {
    return {
      componentId: 0,
      isTaskModal: false,
      type: 'Component',
      legendArray: [],
      searchFieldsEmpty: [],
      isLoading: false,
      widgets: [],
      componentNameFilter: '',
      selectedStatus: null,
      StatusList: [],
      isAddComponentModal: false,
      ComponentData: null,
      statusOptions: [],
      fullList: [],
      ProjectId: 0,
      Headers: [
        {
          COLUMN_NAME: 'component_name',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Component Name',
          DISPLAY_ORDER: 1,
          settings: {
            isInSlot: true,
            isValueTruncate: false
          }
        },
        {
          COLUMN_NAME: 'component_desc',
          DATA_TYPE: 'string',
          SORTABLE: false,
          VISIBLE: true,
          DISPLAY_NAME: 'Component Description',
          DISPLAY_ORDER: 2,
          settings: {
            isInSlot: true,
            isValueTruncate: false
          }
        },
        {
          COLUMN_NAME: 'status_name',
          DATA_TYPE: 'string',
          SORTABLE: true,
          VISIBLE: true,
          DISPLAY_NAME: 'Status',
          DISPLAY_ORDER: 3,
          settings: {
            isInSlot: true
          }
        },
        {
            COLUMN_NAME: "created_at",
            DATA_TYPE: "string",
            SORTABLE: false,
            VISIBLE: true,
            DISPLAY_NAME: "Created At",
            DISPLAY_ORDER: 10,
            settings : {
                isInSlot: true
            }
        },        
        {
            COLUMN_NAME: "CreatedName",
            DATA_TYPE: "string",
            SORTABLE: false,
            VISIBLE: true,
            DISPLAY_NAME: "Created By",
            DISPLAY_ORDER: 10,
        },
        {
            COLUMN_NAME: "modified_at",
            DATA_TYPE: "string",
            SORTABLE: false,
            VISIBLE: true,
            DISPLAY_NAME: "Modified At",
            DISPLAY_ORDER: 10,
            settings : {
                isInSlot: true
            }
        },
        {
            COLUMN_NAME: "ModifiedName",
            DATA_TYPE: "string",
            SORTABLE: false,
            VISIBLE: true,
            DISPLAY_NAME: "Modified By",
            DISPLAY_ORDER: 10,
        },
        
        {
          COLUMN_NAME: 'TaskCount',
          DATA_TYPE: 'string',
          SORTABLE: false,
          VISIBLE: true,
          DISPLAY_NAME: 'Total Count',
          DISPLAY_ORDER: 4,
          settings: {
            isInSlot: true
          }
        }
        
      ],
      headerButtons: [],
      pageSize: 10,
      pageNum: 1,
      SortBy: '',
      SortExp: '',
      TotalRecords: 0,
      CompanyId: null,
      _fetchInProgress: false,
      _pendingFetch: false,
      listActions: [
        {
          title: 'Edit',
          href: 'javascript:void(0)',
          icon: 'fa fa-pencil action-icon',
          additionalSpan: '',
          callbackfunction: 'Edit'
        },
        {
          title: 'Delete',
          href: 'javascript:void(0)',
          callbackfunction: 'Delete',
          icon: 'fa fa-trash-o action-icon text-danger',
          additionalSpan: ''
        }
      ]
    }
  },
  created() {
    var ths = this;
    ths.ProjectId = ths.$route.params.projectId;
    if (ths.GetUserInfo && ths.GetUserInfo.CompanyId != null) {
      ths.CompanyId = ths.GetUserInfo.CompanyId;
    }
    ths.FetchData()
    ths.bindStatusOptions();

  },
  methods: {
    OpenTaskModel(id) {

      this.componentId = id;
      this.isTaskModal = true;
    },
    rowIdentity(row) {
      if (!row) return 0
      var id = row.component_id != null ? row.component_id : row.COMPONENT_ID != null ? row.COMPONENT_ID : row.ID != null ? row.ID : row.id
      var n = Number(id)
      return isNaN(n) ? 0 : n
    },
    listDataCallback() {
      this.FetchData()
    },
    normalizeSelectIds(value) {
      if (value == null) return []
      var arr = Array.isArray(value) ? value : [value]
      return arr
        .map(function (v) {
          if (v == null) return null
          if (typeof v === 'object') return v.value != null ? v.value : (v.id != null ? v.id : null)
          return v
        })
        .filter(function (v) { return v !== null && v !== '' })
    },
    statusIdsCsv(val) {
      var ids = this.normalizeSelectIds(val)
      return ids.length ? ids.join(',') : ''
    },

    renderActions: function () {
      var self = this;
      let rtnActionArray = [];
      self.listActions.forEach(actionItem => {
        let action = { ...actionItem };
        switch (action.title) {
          case 'Delete':
            action.isVisible = true;
            break;
          case 'Edit':
            action.isVisible = true;
            break;
          default: {
            action.isVisible = true;
          }
        }
        rtnActionArray.push(action);
      });
      return rtnActionArray;
    },
    pagerMethod(value) {
      if (!value) return
      this.pageSize = value.PageSize != null ? value.PageSize : this.pageSize
      this.pageNum = value.PageNumber != null ? value.PageNumber : this.pageNum
      this.FetchData();
    },
    sortdata: function (s) {
      var SortDir = "sort tb_headerSortDown";
      this.pageNum = 1
      this.SortBy = s;
      if (s === this.SortBy) {
        if (this.SortExp == "") {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
        else if (this.SortExp == "ASC") {
          this.SortExp = "DESC";
          SortDir = "sort tb_headerSortUp";
        }
        else {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
      }
      this.FetchData();
      $("#" + s + '  span:first-child').attr("class", SortDir);
    },

    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {
        case 'Edit':
          this.Edit(item)
          break
        case 'Delete':
          this.deleteSelected(this.rowIdentity(item))
          break
      }
    },
    async Edit(item) {
      var vm = this;
      vm.isLoading = true;
      var url = 'controller=Project&action=AddUpdateComponent';
      await DataService.CheckPrivilege(url).then(async function (response) {
        vm.isLoading = false;
        if (response.data || vm.checkPmUser || vm.ProjectOwner) {
          vm.ComponentData = item;
          vm.isAddComponentModal = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
        }
      })

    },
    getFilterLimitText(count) {
      return `+${count}`
    },
    SearchByComponentName() {
      this.pageNum = 1
      this.FetchData()
    },
    FetchData(searchValue = null, searchType = null) {
      var ths = this;
      if (searchType === 'COMPONENT_BY_STATUS') {
        ths.selectedStatus = searchValue
        ths.pageNum = 1
      }
      if (ths._fetchInProgress) {
        ths._pendingFetch = true
        return
      }
      ths._fetchInProgress = true
      ths.isLoading = true
      const taskName = (ths.componentNameFilter || '').trim()
      const statusParam = ths.statusIdsCsv(ths.selectedStatus)
      const params =
        `projectId=${ths.ProjectId}&taskName=${encodeURIComponent(taskName)}&status=${statusParam}` +
        `&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.pageSize}&pageNum=${ths.pageNum}&type=Component`
      DataService.GetComponetAndEnvirementListing(params).then((response) => {
        var rows = response && response.data && response.data.result && response.data.result.DATA
        if (rows && rows.length > 0) {
          ths.fullList = rows
          ths.TotalRecords = rows[0].TotalRecords != null ? rows[0].TotalRecords : rows.length
        } else {
          ths.fullList = []
          ths.TotalRecords = 0
        }
      }).catch(() => {
        ths.fullList = []
        ths.TotalRecords = 0
      }).finally(() => {
        ths.isLoading = false
        ths._fetchInProgress = false
        if (ths._pendingFetch) {
          ths._pendingFetch = false
          ths.FetchData()
        }
      })
    },
    bindStatusOptions: function () {
      var vm = this;
      if (vm.CompanyId == null && vm.GetUserInfo && vm.GetUserInfo.CompanyId != null) {
        vm.CompanyId = vm.GetUserInfo.CompanyId
      }
      var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
      DataService.StatusListing(url).then((response) => {
        if (response.data != null && response.data != "") {
          vm.StatusList = response.data.result.data;
          vm.statusOptions = []
          vm.StatusList.forEach(function (item) {
            var obj = {
              id: item.STATUS_ID,
              label: item.STATUS
            }
            vm.statusOptions.push(obj);
          });
        }
      });
    },
    clearFilters() {
      this.componentNameFilter = ''
      this.selectedStatus = null
      this.pageNum = 1
      this.FetchData()
    },
    async openAddModal() {
      var vm = this;
      vm.isLoading = true;
      var url = 'controller=Project&action=AddUpdateComponent';
      await DataService.CheckPrivilege(url).then(async function (response) {
        vm.isLoading = false;
        if (response.data || vm.checkPmUser || vm.ProjectOwner) {
          vm.ComponentData = null;
          vm.isAddComponentModal = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
        }
      })

    },
    onCloseAddModal() {
      this.isAddComponentModal = false
      this.ComponentData = null;
      this.Id = null;
      this.isTaskModal = false;
    },
    goBackToList() {
      this.$router.push({ name: 'ProjectList' })
    },
    deleteSelected: async function (id) {
      var val = ''
      var vm = this
      var url = 'controller=Project&action=DeleteComponent';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data || vm.checkPmUser || vm.ProjectOwner) {
          if (id == null || id === '') {
            $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
              if (val.length > 0) {
                val += ','
              }
              val += $(this).val()
            })
          } else {
            val = String(id)
          }
          if (val != null && val !== '') {
            vm.confirmR(vm.$t('ConfirmDelete'), true, (vm.$t('Delete') + '  ' + vm.$t('Group')), function () {
              vm.isLoading = true
              var postJSON = {
                ids: val,
                moduleName: 'PROJECT',
                refCode: 'TALYGEN_COMPONENT'
              }
              var objectPostString = JSON.stringify(postJSON)
              DataService.CommonCommonDelete(objectPostString).then(function (response) {
                vm.isLoading = false
                if (response.data.length > 0) {
                  if (response.data[0].Status === 'Success') {
                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Component')]), 'success', true, vm.$t('Alert'))
                    vm.FetchData()
                  } else {
                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Component')]), 'failure', true, vm.$t('Alert'))
                  }
                } else {
                  vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Component')]), 'failure', true, vm.$t('Alert'))
                }
              }).catch(function () {
                vm.isLoading = false
                vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Component')]), 'failure', true, vm.$t('Alert'))
              })
            })
          } else {
            vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), 'failure', true, vm.$t('Alert'))
          }
        } else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, vm.$t("Alert"));
        }
      })
    }
  }
}
</script>