<template>
    <div class="my-popups">
        {{ projectBudget }}
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">

                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('Manage') }} {{ $t('Budget') }} </h4>
                        <button type="button" class="close" v-on:click="CloseAddBudget">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm"
                            :mandatorytext='MandatoryString' v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default {
    props: {
        BacklogId: {
            type: Number,
            Required: true
        },
        projectBudget: {
            type: Number,
            Required: true
        },
        pandingBudget:{
            type:Number || String
        },
        projectCurrency:{
            type:String
        }
    },
    data() {
        return {
            isLoading: false,
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('Category'),
                            name: "Category",
                            value: "",
                            placeholder: this.$t('Enter Category'),
                            visibility: true,
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Categories'),
                            name: "Categories",
                            value: "",
                            config: {
                                options: [],
                                showAddIcon: true,
                                onAddButtonClick: this.openaddCategories
                            },
                            placeholder: this.$t('Select Categories'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "TextField",
                            label: this.$t('Amount'),
                            name: "categoryAmount",
                            value: "",
                            config: {
                                options: []
                            },
                            placeholder: this.$t('Enter Amount'),
                            validationRules: { "required": true, "regex": /^[a-zA-Z0-9\s]*$/ },
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: false,
                    onClick: this.SaveCategorybutton,
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseAddBudget,
                },
            ],
            projectId: null,
            CompanyId: null,
            UserId: null,
            Currency: '',
            isSaving: false,
        }
    },
    created: function () {
        var vm = this;
        vm.projectId = parseInt(vm.$route.params.projectId);
        vm.CompanyId = vm.GetUserInfo.CompanyId;
        vm.Currency = vm.GetUserInfo.Currency.replace(/[()]/g, '');
        vm.FormSchema[0].Data[2].label = vm.$t('Amount(' + vm.projectCurrency + ')');
        vm.UserId = vm.GetUserInfo.ID;
        vm.FormSchema[0].Data[0].visibility = false;
        vm.GetExpenseCategory();
    },
    watch: {
        '$parent.showCategoryModal'(newVal) {
            if (newVal === true) {
                this.resetForm();
            }
        }
    },
    methods: {
        resetForm() {            
            this.FormSchema[0].Data[0].value = "";
            this.FormSchema[0].Data[1].value = "";
            this.FormSchema[0].Data[2].value = "";
            this.ShowAddCategoryDiv();
            this.isCategorySave = false;
            if (this.$refs.AssignTagForm) {
                this.$refs.AssignTagForm.UpdateKeyValue();
            }
        },

        SaveCategorybutton() {            
            if (this.isSaving) return;
            this.isCategorySave = true;
            this.OnSubmit();
        },
        openaddCategories() {
            
            var vm = this;
            vm.FormSchema[0].Data[0].visibility = true;
            vm.FormSchema[0].Data[0].validationRules.required = true;
            vm.FormSchema[0].Data[1].visibility = false;
            vm.FormSchema[0].Data[2].visibility = false;
            vm.buttons[0].isVisible = false;
            vm.buttons[1].isVisible = true;
        },
        ShowAddCategoryDiv() {
            
            var vm = this;
            vm.FormSchema[0].Data[0].visibility = false;
            vm.FormSchema[0].Data[1].visibility = true;
            vm.FormSchema[0].Data[2].visibility = true;
            vm.FormSchema[0].Data[0].validationRules.required = false;
            vm.buttons[1].isVisible = false;
            vm.buttons[0].isVisible = true;
        },
        GetExpenseCategory() {
            var ths = this;
            var url = `id=&companyId=${ths.CompanyId}&userId=${ths.UserId}&moduleName=Expenses&type=EXPENSE_CATEGORY&refId=${ths.projectId}`;
            DataService.GetExpenseCategory(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            ths.FormSchema[0].Data[1].config.options=[];
                            response.data.DATA.forEach(element => {
                                let Obj = {
                                    name: element.name,
                                    value: element.value
                                }
                                ths.FormSchema[0].Data[1].config.options.push(Obj);
                            });
                            ths.$refs.AssignTagForm.UpdateKeyValue();
                        }
                    }
                }
            })
        },
        CloseAddBudget() {            
            this.resetForm();
            this.$parent.showCategoryModal = false;
        },
        SaveCategory() {
            var ths = this;
            var data = {
                userId: ths.UserId,
                companyId: ths.CompanyId,
                categoryName: ths.FormSchema[0].Data[0].value,
                categoryDesc: ths.FormSchema[0].Data[0].value
            };
            var objectPostString = JSON.stringify(data)
            if (ths.FormSchema[0].Data[0].value != "") {
                DataService.AddCategory(objectPostString).then(function (response) {
                    ths.isSaving = false;
                    ths.isLoading = false;
                    if (response.data.status == 'Success') {
                        if (response.data.result === 0) {
                            ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Category')]), "success", true, ths.$t("Alert"));

                        } else {
                            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Category')]), "success", true, ths.$t("Alert"));
                            ths.GetExpenseCategory();
                            ths.$emit('callBackFunction');
                            ths.ShowAddCategoryDiv();
                        }
                    }

                })
            }
        },
        OnSubmit() {            
            if (this.isSaving) return;
            if (this.isCategorySave) {
                this.isCategorySave = false;
                this.SaveCategory();
            } else {
                this.savebudge();
            }
        },
        savebudge: async function () {
            var ths = this;
            ths.isLoading = true;
            var paidAmount=0;    
            ths.projectBudget !=null ? ths.projectBudget : 0;        
            if (parseFloat(ths.projectBudget) < parseFloat(ths.FormSchema[0].Data[2].value)) {
                ths.ShowAlert(ths.$t('Amountcannotexceedthetotalbudget', [ths.$t('Budget')]), "failure", true, ths.$t("Alert"));
                ths.isLoading = false;
                return;
            }
            paidAmount=parseFloat(ths.projectBudget)-parseFloat(ths.pandingBudget);
            if(paidAmount <  parseFloat(ths.FormSchema[0].Data[2].value)) 
            {
                ths.ShowAlert(ths.$t('Amountcannotexceedthetotalbudget', [ths.$t('Budget')]), "failure", true, ths.$t("Alert"));
                ths.isLoading=false;
                return;
            }
            var data = [{
                USER_ID: ths.UserId,
                COMPANY_ID: ths.CompanyId,
                CATEGORY_ID: ths.FormSchema[0].Data[1].value,
                ESTIMATED_AMOUNT: ths.FormSchema[0].Data[2].value,
                STATUS: 1001,
                EVENT_ID: ths.projectId,
                TYPE_VAL: 'INSERT'
            }];
            var objectPostString = JSON.stringify(data)
            await DataService.ManageBudget(objectPostString).then(function (response) {
                ths.isLoading = false;
                if (response.data.result.DATA.Value > 0) {
                    ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Budget')]), "success", true, ths.$t("Alert"));
                    ths.$emit('GetExpenseCategory');
                    ths.$emit('callBackFunction');
                    ths.CloseAddBudget();
                } else {
                    ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Category')]), "warning", true, ths.$t("Alert"));
                }

            })
        }
    }
}
</script>