<template>
    <section>
        <div>
            <!-- <tg-list :IsShowAction="false"  :ModuleName="moduleCode" :SubModuleCode="subModuleCode"
                    :IdentityColumn="primaryKeyforModule" :ListData="ListingData" :HeaderData="Headers"
                    :HeaderButtons="Buttons" :TotalRecords="TotalRecords" :IsSearchFieldsOnTop="false" :RenderRowActionMethod="renderActions"
                    SearchPosition="top" :SearchFields="topsearchField" 
                    :ListDataCallBackFunction="FetchTaskList" 
                     sourcetype=""
                    v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick" 
                    v-on:SortdataButtonClick="sortdata" :NorecordfoundText="$t('NoRecordfound')">
                </tg-list> -->
    
            <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="true" ModuleName="PROJECT"
                SubModuleCode="Task" IdentityColumn="project_id" :HeaderText="$t('Manage Tasks')" :ListData="ListingData"
                :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
                :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchTaskList" :SortExp="SortExp"
                :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod"
                v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata"></tg-list>
    
        </div>
    
    </section>
</template>
<script>
import DataService from '../../../../services/DataService.js';
import schema from '../../Project/ProjectDetailLeftAllTabs/CallDetailListingSchema.js';
export default {
  props: {
    ProjectName: {
      type: Object,
      require: true
    },
    projectId: {
      type: Number,
      require: true
    }
  },

   data() {
    return {
      TotalRecords: null,
      noRecord: false,
      projectId: '',
      isLoading: false,
      CompanyId: null,
      PageSize: 10,
      PageNumber: 1,
      isPaged: 1,
      TotalPages: 0,
      SortBy: '',
      SortExp: '',
      taskId: '',
      Headers: schema.TableHeader,
      ListingData: [],
      searchCondition: '',
      Buttons: schema.buttons,
      widgets: [],
      // ProjectTaskListingpopup:false
    }
  },
  created: async function () {
    var ths = this;
    
    ths.projectId = ths.$route.params.projectId;
    ths.CompanyId = ths.GetUserInfo.CompanyId;
    ths.userId = ths.GetUserInfo.ID;
    await ths.FetchTaskList();
  },
  methods: {
    sortdata() { },
    closepopup() {
      
      //this.ProjectTaskListingpopup=false;
    },
    renderActions() { },
    pagerMethod() { },
    commonHeaderButtonClick: function (event) {
      switch (event.callbackfunction) {
        case "EditTask":
          this.EditTask();
          break;
        case "BackToList":
          this.BackToList();
          break;
      }
    },
    EditTask() {
      this.$emit('EditProject');
    },
    BackToList: function () {
      var ths = this;
      ths.$router.push({ name: 'ProjectList' });
    },
    FetchTaskList: async function (x, item, refform) {
      
      var vueObj = this;
      vueObj.isLoading = true;
      var params = `projectId=${vueObj.projectId}&subModuleCode=${vueObj.subModuleCode}&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNum=${vueObj.PageNumber}`;
      await DataService.CallDetailListing(params).then(function (response) {
        if (response.data.result.data.length > 0) {
          vueObj.ListingData = response.data.result.data;
          vueObj.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
          vueObj.TotalPages = Math.ceil(vueObj.TotalRecords / vueObj.PageSize);
        }
        else {
          
          vueObj.TotalRecords = 0;
          vueObj.TotalPages = 1;
          vueObj.ListingData = [];

        }

      });
    },
  }
}
</script>