<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered mw-800">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('Edit') }} {{ $t('Budget') }}</h4>
                        <button type="button" class="close" v-on:click="cancelEditBudget">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>                        
                    </div>
                    <div class="modal-body">
                        <div class="col-md-12">
                            <div class="row">
                                <div class="listing mt-2">
                                    <div class="table-responsive  table-fix-header" style="max-height: 320px;">
                                        <table class="table table-bordered dt-responsive nowrap mt-0">
                                            <thead class="thead-bg">
                                                <tr>
                                                    <th style="width:33%">
                                                        <span>{{$t('Category')}}</span>
                                                    </th>
                                                    <th style="width:33%">
                                                        <span>{{$t('Amount')}}({{ projectCurrency }})</span>
                                                    </th>
                                                    <th class="text-center">
                                                        <span>{{$t('Action')}}</span>
                                                    </th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr v-for="(item,index) in BudgetListingData" :key="index">
                                                    <td class="form-group">
                                                        <span>{{item.category_name}}</span>
                                                    </td>
                                                    <td class="text-left">
                                                        <input v-bind:class="{'form-control':true}" v-bind:id="'CategoryAmount'+item.budget_id" name="CategoryAmount" data-vv-as="@Resources.Category @Resources.Amount" v-model="item.estimated_amount" type="number">
                                                        
                                                    </td>
                                                    <td class="text-center single-action">
                                                        <a href="javascript:;" v-on:click="deleteCategoryBudget(item.budget_id)">
                                                            <em class="fa fa-trash-o text-danger action-icon"></em>
                                                        </a>
                                                    </td>
                                                </tr>
                                                <tr v-if="BudgetListingData == null || BudgetListingData.length == 0">
                                                    <td colspan="10" class="text-center text-danger no-record">{{$t('NoRecordfound')}}</td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            </div>
                            <div class="row flex-row-reverse mt-2">
                                <div class="col-lg-12 text-right p-0">
                                    <a href="javascript:;" class="btn btn-success formbtn widthhalf mr-2" title="" id="anctransferloaddata" v-on:click="UpdateBudget"><i class="fa fa-save pr-2"></i>{{$t('Save')}}</a>
                                    <a href="javascript:;" v-on:click="cancelEditBudget" class="btn btn-danger formbtn widthhalf"><i class="fa fa-times"></i> {{$t('Cancel')}}</a>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService'
export default {
    props:{
        projectBudget:{
            type:Number,
            Required:true
        },
        pandingBudget:{
            type:Number | String
        },
         projectCurrency:{
            type:String
        }
    },
    data(){
        return {
            BudgetListingData: [],
            isLoading:false,
            projectId:0,
            CompanyId:null,
            UserId:null,
            Currency:''
        }
    },
    created:function(){
        var vm =this;
        vm.projectId = parseInt(vm.$route.params.projectId); 
        vm.CompanyId = vm.GetUserInfo.CompanyId;
        vm.Currency = vm.GetUserInfo.Currency.replace(/[()]/g, '');
        vm.UserId = vm.GetUserInfo.ID;
        vm.getBudgetListing();
    },
    methods:{
        UpdateBudget(){
            var ths = this;
            ths.isLoading=true;  
            var budgetList = [];
            var totalofcategorys=0; 
            $.each(ths.BudgetListingData, function (key, value) {
                
                totalofcategorys +=parseFloat(value.estimated_amount);
                var obj = {
                    BUDGET_ID: value.budget_id,
                    USER_ID: ths.UserId,
                    COMPANY_ID: ths.CompanyId,
                    CATEGORY_ID: value.category_id,
                    ESTIMATED_AMOUNT: value.estimated_amount,
                    STATUS: 1001,
                    EVENT_ID: ths.projectId,
                    TYPE_VAL: 'UPDATE'
                };
                budgetList.push(obj);
            }); 
                
            if(totalofcategorys > this.projectBudget) 
            {
                ths.ShowAlert(ths.$t('Amountcannotexceedthetotalbudget', [ths.$t('Budget')]), "failure", true, ths.$t("Alert"));
                ths.isLoading=false;
                return;
            }
            var objectPostString = JSON.stringify(budgetList);
            DataService.ManageBudget(objectPostString).then((response)=>{
                
                ths.isLoading=false;
                if(response.data.result.DATA.Value == -1){                     
                    ths.ShowAlert(ths.$t('EstimatedBudgetsuccessfullyupdated'), "success", true,  ths.$t("Alert"));                                 
                    ths.$emit('callBackFunction');
                    ths.cancelEditBudget();    
                }else{
                    ths.ShowAlert(ths.$t('AlreadyExists',[ths.$t('Category')]),"success", true, ths.$t("Alert"));
                }
            })
        },
        deleteCategoryBudget: function (val) {
        var ths = this;
        var url = 'controller=Project&action=DeleteBudget';
        DataService.CheckPrivilege(url).then(async function (response) {
            if (response.data) {
                
                var obj = {
                    BUDGET_ID: val,
                    TYPE_VAL: 'DELETE',
                    PROJECT_ID:ths.projectId
                };
                var objectPostString = JSON.stringify(obj);
                ths.confirmR(ths.$t("ConfirmDelete"), true, (ths.$t("Delete") + "  " + ths.$t("Budget")), function () {
                    DataService.ManageBudget(objectPostString).then((response) => {
                        ths.isLoading = false;
                        if (response.data.result.DATA.Value == -2) {
                            ths.ShowAlert(ths.$t('DeletedSuccess', [ths.$t('Budget')]), "success", true, ths.$t("Alert"));
                            ths.getBudgetListing();
                            ths.$emit('callBackFunction');
                            ths.cancelEditBudget();
                        } else if(response.data.result.DATA.Value == 0){
                            ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('You can'+'delete this category because it already has expenses. Please remove those expenses first')]), "failure", true, ths.$t("Alert"));
                        }
                    });
                });
            } else {
                ths.ShowAlert(ths.$t('NotAuthorizedSection'), "failure", true, "Alert");
            }
        });
    },
        getBudgetListing(){              
            var vm = this;              
            var url = `eventId=${vm.projectId}`;
            vm.isLoading=true;
            DataService.getBudgetListing(url).then((response)=>{
                var arrAU = [];
                
                vm.isLoading=false;    
                if (response.data != null) {
                    if (typeof(response.data.data) != "undefined" &&  response.data.data.length > 0) {
                        vm.BudgetListingData = response.data.data
                        var sum = 0;
                        $.each(vm.BudgetListingData, function (index, element) {
                            arrAU.push([element.category_name, element.estimated_amount,element.CATEGORY_TOTAL_AMOUNT]);
                            sum = sum + element.estimated_amount;
                        });
                        vm.totalbudget = sum;
                        vm.paidexpenses = vm.totalbudget - vm.totalexpenses;
                    } else {
                        vm.totalbudget = 0;
                        vm.BudgetListingData = [];
                    }
                } else {
                    vm.totalbudget = 0;
                    vm.BudgetListingData = [];
                }      
            })
        },
        FetchData(){
            this.getBudgetListing();
        },
        cancelEditBudget:function(){
            this.$parent.showEditBudgetModal=false;
        }
    }
}
</script>