<template>
  <section>
    <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="false" ModuleName="Event"
      SubModuleCode="Client" IdentityColumn="MEETING_ID" :HeaderText="$t('Meetings')" :ListData="list"
      :HeaderData="Headers" :HeaderButtons="Buttons" :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions"
      :ListDataCallBackFunction="FetchMettingList" :SortExp="SortExp" :SortBy="SortBy"
      v-on:ActionButtonClick="actionButtonClick" :NorecordfoundText="$t('NoRecordfound')"
      v-on:PagerButtonClick="pagerMethod" :widgets="widgets" :LegendArray="LegendArray"
      v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata">
      <template v-slot:slotdata="{ data }">
        <template v-if="data.column.COLUMN_NAME == 'EVENT_SUBJECT'">
          <a @click="AddWishList(data.row)" class="task-dec" :title="data.row.EVENT_SUBJECT"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.EVENT_SUBJECT ?? 'N/A' }}
          </a>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'AGENDA'">
          <span :title="data.row.AGENDA"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.AGENDA ?? 'N/A' }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'SPEAKER'">
          <span :title="data.row.SPEAKER"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.SPEAKER ?? 'N/A' }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'EVENT_START_TIME'">
          <span :title="data.row.EVENT_START_TIME"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ $d(new Date(data.row.EVENT_START_TIME)) ?? 'N/A' }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'EVENT_END_TIME'">
          <span :title="data.row.EVENT_END_TIME"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ $d(new Date(data.row.EVENT_END_TIME)) ?? 'N/A' }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'EVENT_LOCATION_NAME'">
          <span :title="data.row.EVENT_LOCATION_NAME"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.EVENT_LOCATION_NAME ?? 'N/A' }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'STATUS_NAME'">
          <span :title="data.row.STATUS_NAME"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
            {{ data.row.STATUS_NAME ?? 'N/A' }}
          </span>
        </template>
      </template>
    </tg-list>
    <ModalAddMeeting v-if="showModal" :meetingId="selectedMeetingId" @close="showModal = false"
      @saved="FetchMettingList" />
  </section>
</template>

<script>
import DataService from '@/services/DataService';
import ModalAddMeeting from '../Modals/ModalAddMeeting.vue';
export default {
  name: 'MeetingPortion',
  components: { ModalAddMeeting },
  props: { eventId: { type: [Number, String], required: true } },
  data() {
    return {
      isLoading: false,
      widgets: [],
      LegendArray: [],
      list: [],
      SortBy: '',
      SortExp: '',
      TotalRecords: 0,
      PageSize: 10,
      PageNumber: 1,
      showModal: false,
      selectedMeetingId: 0,
      listActions: [{
        title: 'Edit',
        href: 'javascript:void(0)',
        callbackfunction: 'EditMetting',
        icon: 'fa fa-pencil action-icon',
        additionalSpan: ''
      },
      {
        title: 'Delete',
        href: 'javascript:void(0)',
        callbackfunction: 'DeleteMetting',
        icon: 'fa fa-trash-o text-danger',
        additionalSpan: ''
      },],
      Headers: [{
        "COLUMN_NAME": "METTING_ID",
        "DATA_TYPE": "string",
        "SORTABLE": false,
        "VISIBLE": false,
        "DISPLAY_NAME": "Subject",
        "DISPLAY_ORDER": 1,
      }, {
        "COLUMN_NAME": "EVENT_SUBJECT",
        "DATA_TYPE": "string",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "Subject",
        "DISPLAY_ORDER": 1,
        settings: {
          isInSlot: true
        }
      },
      {
        "COLUMN_NAME": "AGENDA",
        "DATA_TYPE": "string",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "Agenda",
        "DISPLAY_ORDER": 2,
        settings: {
          isInSlot: true
        }
      },
      {
        "COLUMN_NAME": "SPEAKER",
        "DATA_TYPE": "string",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "Speaker",
        "DISPLAY_ORDER": 3,
        settings: {
          isInSlot: true
        }
      },
      {
        "COLUMN_NAME": "EVENT_START_TIME",
        "DATA_TYPE": "date",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "Start Date",
        "DISPLAY_ORDER": 4,
        settings: {
          isInSlot: true
        }

      },
      {
        "COLUMN_NAME": "EVENT_END_TIME",
        "DATA_TYPE": "date",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "End Date",
        "DISPLAY_ORDER": 5,
        settings: {
          isInSlot: true
        }

      },
      {
        "COLUMN_NAME": "EVENT_LOCATION_NAME",
        "DATA_TYPE": "date",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "Location Name",
        "DISPLAY_ORDER": 6,
        settings: {
          isInSlot: true
        }

      },
      {
        "COLUMN_NAME": "STATUS_NAME",
        "DATA_TYPE": "date",
        "SORTABLE": true,
        "VISIBLE": true,
        "DISPLAY_NAME": "Status Name",
        "DISPLAY_ORDER": 6,
        settings: {
          isInSlot: true
        }

      },
      ],
      Buttons: [{
        title: 'Add',
        iconClass: 'fa fa-plus pr-2',
        callbackfunction: 'openAdd',
        additionalClass: '',
        isdisabled: false,
        isvisible: true,

      },
      {
        title: 'Back to list',
        iconClass: 'fa fa-angle-double-left pr-2',
        callbackfunction: 'BackToList',
        additionalClass: '',
        isdisabled: false,
        isvisible: true,

      }],

    };
  },
  created() { this.FetchMettingList(); },
  methods: {
    renderActions: function () {
      var self = this;
      let rtnActionArray = [];
      self.listActions.forEach(actionItem => {
        let action = { ...actionItem };
        switch (action.title) {
          case 'Add':
            action.isVisible = true;
            break;
          default: {
            action.isVisible = true;
          }
        }
        rtnActionArray.push(action);
      });
      return rtnActionArray;
    },
    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {
        case 'EditMetting':
          this.openEdit(item.METTING_ID);
          break;
        case 'DeleteMetting':
          this.commonDeleteData(item.METTING_ID);
          break;

      }
    },
    async commonDeleteData(id) {
      var vm = this;
      var url = 'controller=Project&action=DeleteEventDonation';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.isLoading = true;
          if (id != null) {
            vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
              var postJSON = {
                ID: id
              };
              var objectPostString = JSON.stringify(postJSON);
              DataService.DeleteMeetingDataById(objectPostString).then(function (response) {
                vm.isLoading = false;
                if (response.status == 200) {
                  vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Meeting')]), "success", true, vm.$t("Alert"));
                  vm.FetchMettingList();
                }
                else {
                  vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Meeting')]), "warning", true, vm.$t("Alert"));
                }
              });
            });
          }
          else {
            vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), "warning", true, vm.$t("Alert"));
          }
          vm.isLoading = false;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    commonHeaderButtonClick: async function (event) {
      var vm = this;
      switch (event.callbackfunction) {
        case "openAdd":
          vm.openAdd();
          break;
        case "BackToList":
          vm.BackToList();
          break;
      }
    },
    BackToList: function () {
      this.$router.push({ name: 'ProjectList' });
    },
    pagerMethod: function (value) {
      this.PageSize = value.PageSize;
      this.PageNumber = value.PageNumber;
      this.FetchMettingList();
    },
    sortdata: function (s) {
      var SortDir = "sort tb_headerSortDown";
      this.SortBy = s;
      if (s === this.SortBy) {
        if (this.SortExp == "") {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
        else if (this.SortExp == "ASC") {
          this.SortExp = "DESC";
          SortDir = "sort tb_headerSortUp";
        }
        else {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
      }
      this.FetchMettingList();
      $("#" + s + '  span:first-child').attr("class", SortDir);
    },
    async FetchMettingList() {
      try {

        const res = await DataService.GetMeetingListing(`eventId=${this.eventId}&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pagesize=${this.PageSize}&pagenumber=${this.PageNumber}`);
        this.list = (res.data && res.data.result && res.data.result.DATA) ? res.data.result.DATA : [];
        this.TotalRecords = (res.data && res.data.result) ? (res.data.result.DATA[0].TOTALRECORDS || 0) : 0;
      } catch (_) { this.list = []; this.TotalRecords = 0; }
    },

    openAdd() {
      this.selectedMeetingId = 0;
      this.showModal = true;
    },
    async openEdit(item) {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateEventMeetings'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          this.selectedMeetingId = item || item; this.showModal = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
          vm.showSocialMediaAdd = false;
        }
      });

    }
  }
};
</script>
