<template>
    <section>
        <div>
            <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="true" ModuleName="PROJECT"
                SubModuleCode="Client" IdentityColumn="MILESTONE_ID" :HeaderText="$t(NewTabName)" :ListData="ListingData"
                :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
                :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchTaskList"
                :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')"  
                v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
                v-on:SortdataButtonClick="sortdata" :Key="Key">
                <template v-slot:slotdata="{ data }">
                    <template v-if="data.column.COLUMN_NAME == 'STATUS_NAME'">
                        <span v-bind:style="{backgroundColor:data.row.STATUS_BG_COLOR}" class="px-2 text-center text-white d-block">
                            {{ capitalizeFirst(data.row.STATUS_NAME) }}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'MILESTONE_DESC'">
                        <span :title="data.row.MILESTONE_DESC" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                            {{ data.row.MILESTONE_DESC}}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'PROJECT_NAME'">
                        <span :title="data.row.PROJECT_NAME" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                            {{ data.row.PROJECT_NAME}}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'MILESTONE_NAME'">
                        <span :title="data.row.MILESTONE_NAME" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                            {{ data.row.MILESTONE_NAME}}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'TASK_NAMES'">
                        <span v-if="data.row.MILESTONE_CRITERIA=='Task'" :title="data.row.TASK_NAMES" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                            {{ data.row.TASK_NAMES}}
                        </span>
                        <span v-else>N/A</span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'MILESTONE_PROGRESS'">
                        <div class="time" v-if="data.row.MILESTONE_PROGRESS != null">
                            <div :class="'c100 small green p' + data.row.MILESTONE_PROGRESS">
                                <span>{{ data.row.MILESTONE_PROGRESS }}%</span>
                                <div class="slice">
                                    <div class="bar"></div>
                                    <div class="fill"></div>
                                </div>
                            </div>
                        </div>
                    </template>
                    <template v-if="data.column.COLUMN_NAME === 'DUE_DATE'">
                        <span :title="data.row.DUE_DATE ? $options.filters.formatDate(data.row.DUE_DATE) : 'N/A'">
                            {{ data.row.DUE_DATE ? $options.filters.formatDate(data.row.DUE_DATE) : 'N/A' }}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME === 'DATE_RECEIVED'">
                        <span :title="data.row.DATE_RECEIVED ? $options.filters.formatDate(data.row.DATE_RECEIVED) : 'N/A'">
                            {{ data.row.DATE_RECEIVED ? $options.filters.formatDate(data.row.DATE_RECEIVED) : 'N/A' }}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'ROWNUMBER'">
                        {{ data.row.ROWNUMBER }}
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'AMOUNT_DUE'">                        
                        <span :title="$n(data.row.AMOUNT_DUE, 'currency', $getLocaleByCurrency(Currency))">
                            {{ $n(data.row.AMOUNT_DUE, 'currency', $getLocaleByCurrency(Currency)) }}
                        </span>

                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'key'">
                        <span>TG-{{ data.row.MILESTONE_ID }}</span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'Edit' && CheckDisabled()">
                        <a title="" href="javascript:;" class="table-head-btn single-action"
                            data-toggle-tooltip="tooltip" data-original-title="Edit Member"><em
                                @click="EditMilestone(data.row)"
                                class="fa fa-pencil text-success action-icon edit-action"></em></a>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'INVOICE_NO'">
                        <!-- <a v-if="data.row.INVOICE_NO==null" title="" href="javascript:;" class="table-head-btn single-action" @click="GenerateInvoice(data.row)">{{ $t('GenerateInvoice') }}</a> -->
                    </template>
                </template>
            </tg-list>
        </div>
        <AddMilestone v-if="MilestoneListingSchema" :ProjectName="ProjectName" :MilestoneID="MilestoneID" :NewTabName="NewTabName" :TabsArray="TabsArray" :projectCurrency="projectCurrency">
        </AddMilestone>
    </section>
</template>
<script>
import Schema from './MilestoneListingSchema';
import DataService from '../../../../services/DataService';
import AddMilestone from '../../../../components/Modal/AddMilestone.vue';
export default {
    components: { AddMilestone },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray:{
            type:Array
        },
        projectCurrency:{
            type:String
        },
        ProjectOwner: {
            type: String
        },
        checkPmUser: {
            type: Boolean,
            required: true
        }
    },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            MilestoneID: null,
            milestoneName: '',
            milestoneDesc: '',
            statusId: '',
            PageNumber: 1,
            StatusList: [],
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            ProjectName: '',
            taskId: '',
            listActions: Schema.listActions,
            Headers: [],
            ListingData: [],
            searchCondition: '',
            Buttons: [],
            IsEditTeamShow: false,
            MilestoneListingSchema: false,
            Currency: '',
            Key:0
        };
    },
    watch: {       
        NewTabName: {
            handler(newTabName) {                
                if (newTabName) {
                    this.updateButtons(newTabName);
                    this.updateHeaders(newTabName);
                }
            },
            immediate: true
        }
    },
    created: async function () {        
        this.NewTabName;
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.userId = this.GetUserInfo.ID;
        this.Currency = this.projectCurrency;
        if (!this.Buttons || this.Buttons.length === 0) {
            this.Buttons = JSON.parse(JSON.stringify(Schema.buttons));
        }
        if (!this.Headers || this.Headers.length === 0) {
            this.Headers = JSON.parse(JSON.stringify(Schema.TableHeader));
        }
        if (this.NewTabName) {
            this.updateButtons(this.NewTabName);
            this.updateHeaders(this.NewTabName);
        }
        this.CheckDisabled();
        this.GetStatus();
        this.ProjectOverview();
        await this.FetchTaskList();
    },
    methods: {
        CheckDisabled() {
            const type = this.GetUserInfo.UserType;
            const hasAccess = this.checkPmUser || this.ProjectOwner;
            const isClient = type === 'CL' || type === 'NU';
            const isAdmin = type === 'CA' || type === 'PM';
            const isAllowed = isAdmin || (isClient && hasAccess);
            const buttons =
                isAdmin ? [true, true,true] :
                    (isClient && hasAccess) ? [true, true,true] :
                        [false,false,true];
            this.Buttons.forEach((b, i) => b.isvisible = buttons[i]);
            if (!isAllowed) {
                this.Headers.forEach(h => {
                    if (h.COLUMN_NAME === 'Edit') {
                        h.VISIBLE = false;
                    }
                });
            }
            return isAllowed;
        },
        capitalizeFirst(value) {
            if (!value) return '';
            return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
        },
        updateButtons(newTabName) { 
            const buttonsCopy = JSON.parse(JSON.stringify(Schema.buttons));
            if (newTabName && buttonsCopy && buttonsCopy.length > 0) {
                buttonsCopy.forEach((button, index) => {
                    if (button.callbackfunction === 'MilestoneListingSchema') {
                        buttonsCopy[index].title = `${this.$t('Add')} ${this.$t(this.NewTabName)}`;
                    }
                });
            }
            this.Buttons = buttonsCopy;
        },

        updateHeaders(newTabName) {
            this.Headers = JSON.parse(JSON.stringify(Schema.TableHeader));
            if (newTabName && this.Headers && this.Headers.length > 0) {
                this.Headers.forEach(header => {
                    if (newTabName) {
                        if (header.COLUMN_NAME === 'MILESTONE_NAME' && header.DISPLAY_NAME === 'Milestone Name') {
                            header.DISPLAY_NAME = this.$t(newTabName) + ' ' + this.$t('Name');
                        }
                        else if (header.COLUMN_NAME === 'MILESTONE_CRITERIA' && header.DISPLAY_NAME === 'Milestone Criteria') {
                            header.DISPLAY_NAME = this.$t(newTabName) + ' ' + 'Criteria';
                        }
                        else if (header.COLUMN_NAME === 'AMOUNT_DUE' ) {
                            header.DISPLAY_NAME = header.DISPLAY_NAME + '(' +  this.Currency + ')';
                        }

                    }
                });
            }
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${this.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {
                if (response.data != null > 0) {
                    vm.ProjectName = response.data.projecT_NAME;
                }
            });
        },
        getStatusClass(status) {
            let returnClass = '';
            switch (status) {
                case 'Active':
                    returnClass = 'px-2 text-center text-white d-block';
                    break;
                case 'Inactive':
                    returnClass = 'px-2 text-center bg-danger text-white d-block';
                    break;
                default:
                    returnClass = '';
            }
            return returnClass;
        },
        renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Edit':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchTaskList();
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {
                case 'DeleteClientData':
                    this.commonDeleteData(item.MILESTONE_ID);
                    break;

            }
        },
        commonHeaderButtonClick: async function (event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "MilestoneListingSchema":
                    vm.AddMilestone();
                    break;
                case "EditProject":
                    vm.EditProject();
                    break;
                case "BackToList":
                    this.BackToList();
                    break;
                case "DeleteClientData":
                    vm.commonDeleteData();
                    break;
            }
        },
        AddMilestone: async function () {
            var vm = this;
            var url = 'controller=Milestone&action=AddMilestone'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data  || vm.checkPmUser || vm.ProjectOwner) {
                    vm.MilestoneID = 0,
                        vm.MilestoneListingSchema = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchTaskList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },         
        commonDeleteData: async function (id) {
            var vm = this;
            var url = 'controller=Milestone&action=DeleteMilestone'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data  || vm.checkPmUser || vm.ProjectOwner) {
                    var val = "";
                    vm.isLoading = true;
                    if (id == null) {
                        $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                            if (val.length > 0)
                                val += ',';
                            val += $(this).val();
                        });
                    }
                    else {
                        val = id;
                    }
                    if (val != null) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                            var postJSON = {
                                ids: val,
                                moduleName: "PROJECT",
                                refCode: "TALYGEN_milestone"


                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {

                                vm.isLoading = false;
                                if (response.status == 200) {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Milestone')]), "success", true, vm.$t("Alert"));
                                    vm.FetchTaskList();
                                    vm.Key++;
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Milestone')]), "Success", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                    }
                    vm.isLoading = false;
                } else {
                    vm.isLoading = false;
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });


        },
        BackToList: function () {
            this.$router.push({ name: 'ProjectList' });
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        },
        EditMilestone: async function (val) {
            var vm = this;
            var url = 'controller=Milestone&action=UpdateMilestone'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data  || vm.checkPmUser || vm.ProjectOwner) {
                    vm.MilestoneID = val.MILESTONE_ID,
                        vm.ProjectName = val.PROJECT_NAME,
                        vm.MilestoneListingSchema = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        GetStatus: function () {
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`;
            DataService.StatusListing(url).then(response => {
                if (response.data.result.data != null && response.data.result.data != "") {
                    vm.StatusList = response.data.result.data;
                }
            });
        },
        ReloadTimeline(){this.FetchTaskList();},
        FetchTaskList: async function () {
            this.isLoading = true;
            const params = `projectId=${this.projectId}&milestoneName=${this.milestoneName}&milestoneDesc=${this.milestoneDesc}&statusId=${this.statusId}&projectName=${this.ProjectName}&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&totalRecords=0`;
            await DataService.MilestoneListing(params).then(response => {
                const data = response.data.result.data;
                if (data.length > 0) {
                    this.ListingData = response.data.result.data;
                    this.ListingData.forEach((item) => {
                        item.isCheckBoxDisabled = false;
                        if (item.COMPANY_ID == 0) {
                            item.isCheckBoxDisabled = true;
                        }
                    })
                    this.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                    this.$emit('callbackWidgets');
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
            });
        },
        GenerateInvoice(data) {
            this.$router.push({
                name: 'CreateInvoice', params: {
                    milestoneId: data.MILESTONE_ID || 0,
                    projectId: data.PROJECT_ID || 0,
                    currency: this.CurrencyCode || '',
                    reqFrom: 'Project_OverView'
                }
            });
        }
    }
};
</script>
