
<template>
  <section>
    <!-- <loader :is-visible="isLoading"></loader> -->

    <div class="ticketsmallfix theme-primary partition p-actions-expand mb-2 mt-2">
      <span class="p-name text-white">{{ $t('ProjectMessages') }}</span>
      <span class="p-actions float-right">

        <a title="" @click="BackToList" class="p-action-btn text-white float-right" data-toggle-tooltip="tooltip"
          data-original-title="Back to list"><i aria-hidden="true" class="fa fa-angle-double-left"></i><br>{{
            $t('BacktoList') }}</a>
      </span>
      <a href="javascript:;" class="custbx-btn p-action-btn text-white float-right"
        @click="exportToChat(currentMessages)" title="Export to Excel" data-bs-toggle="tooltip" data-bs-placement="top">
        Export Chat as PDF<em class="fa fa-file-export "></em>
      </a>
    </div>
    <div class="mess_newdes d-flex vh-90 border" id="chat-export-wrapper">
      <!-- Sidebar -->

      <div class="chat-sidebar bg-white d-flex flex-column mess_newdes_left">
        <!-- Scrollable list -->
        <div class="flex-grow-1 overflow-auto p-3">
          <div class="mb-2 panesdivider">



            <div class="col-lg-12 mb-2 p-0">
              <div class="heading-border mt-0">
                <h6 class="h5">
                  <span>{{ $t('DiscussionTopics') }}</span>
                  <small class="float-right">
                    <button v-if="CheckDisabled()" class="btn btn-sm font-14  mr-1" title="Create new topic"
                      @click="ShowMessagePopup" style="position: inherit;">
                      <em class="fa fa-plus text-secondary"></em>
                    </button>

                    <button class="btn btn-sm font-14" title="Refresh Discussion Topics" @click="refreshDiscussions"
                      style="position: inherit;">
                      <em class="fa fa-refresh text-primary"></em>
                    </button>

                  </small>
                </h6>
              </div>
            </div>

            <!-- Filter Section -->
            <div class="mb-2">
              <!-- Search Filter -->
              <div class="input-group input-group-sm mb-2">

                <div class="input-group customsearchbox">
                  <input type="text" class="form-control border-start-0" placeholder="Search By Discussion Topic..."
                    v-model="searchFilter">
                  <div class="input-group-append">
                    <span class="input-group-text bg-light border-end-0">
                      <em class="fa fa-search text-muted"></em>
                    </span>
                    <button v-if="searchFilter" class="btn btn-outline-danger border-start-0 ml-1" type="button"
                      @click="clearSearchFilter" title="Clear search">
                      <em class="fa fa-times"></em>
                    </button>
                  </div>
                </div>
              </div>

              <!-- Discussion Type Filter -->
              <div class="d-flex mt-3">
                <button v-for="type in discussionTypes" :key="type.value"
                  class="btn btn-sm flex-grow-1 onlychild2 mr-1 py-1"
                  :class="typeFilter === type.value ? 'btn-primary text-white' : 'btn-light lighten'"
                  @click="toggleTypeFilter(type.value)">
                  {{ type.label }}
                </button>
              </div>
            </div>

            <!-- Filtered Discussion List -->

            <div style="max-height: 270px; overflow-y: auto;">
              <button v-for="discussion in filteredDiscussions" :key="discussion.discussion_id"
                class="btn w-100 text-start d-flex justify-content-between align-items-center mb-1 listhovereffect"
                :class="{ 'border-primary': activeDiscussionId === discussion.discussion_id }"
                @click="selectDiscussion(discussion.discussion_id)">

                   <div class="d-flex">
                     <div class="hashtag"><em class="fa fa-hashtag"></em></div>
                     <div class="text-left">
                       <div class="fw-semibold" :title="discussion.discussion_title">{{ discussion.discussion_title }}</div>
                    <div class="d-flex align-items-center mt-1">
                      <span class="text-muted font-11" :title="discussion.created_by_name">{{ discussion.created_by_name }}</span>
                      <span class="badge bg-secondary-new ms-2 font-10 ml-1">
                        {{ formattedDiscussionType(discussion.discussion_type) }}
                      </span>
                    </div>
                  </div>
                </div>
                <span class="roundbadge">
                  {{ discussion.total_message_count }}
                </span>
              </button>
            </div>

            <!-- No Results Message -->
            <div v-if="filteredDiscussions.length === 0 && discussions.length > 0" class="text-center p-0">
              <div class="text-muted bg-light py-2">
                <em class="fa fa-comments-o fa-2x mb-1"></em>
                <p class="mb-1 font-14">No Private Messages Yet!</p>
                <div class="mt-2">
                  <button class="btn btn-sm btn-primary font-12 p-1" @click="clearFilters">
                    Clear Filters
                  </button>
                </div>
              </div>
            </div>


            <!-- v-if="discussions.length === 0"  -->

            <div v-if="discussions.length === 0" class="text-center p-0">
              <button
                class="btn w-100 text-start d-flex justify-content-between align-items-center mb-2 border bg-light darkbuttonbase">
                <div class="text-left">
                  <div class="fw-semibold">{{ $t('NoDiscussionsYet') }}</div>
                  <span class="text-muted font-12">{{ $t('CreateYourFirstDiscussion') }}</span>
                </div>
              </button>
            </div>

          </div>
          <div>


            <div class="col-lg-12 mb-2 p-0">
              <div class="heading-border mt-0">
                <h6 class="h5">
                  <span>{{ $t('DirectMessages') }}</span>
                  <small class="float-right">
                    <button class="btn btn-sm font-14" title="Refresh Direct Messages" @click="refreshDirectUserList">
                      <em class="fa fa-refresh text-primary"></em>
                    </button>
                  </small>
                </h6>
              </div>
            </div>

            <div class="input-group input-group-sm mb-2">

              <div class="input-group customsearchbox">
                <input type="text" class="form-control border-start-0" :placeholder="$t('searchbyteam')"
                  v-model="searchteamFilter">
                <div class="input-group-append">
                  <span class="input-group-text bg-light border-end-0">
                    <em class="fa fa-search text-muted"></em>
                  </span>
                  <button v-if="searchteamFilter" class="btn btn-outline-danger border-start-0 ml-1" type="button"
                    @click="clearteamSearchFilter" title="Clear search">
                    <em class="fa fa-times"></em>
                  </button>
                </div>
              </div>
            </div>

            <div style="max-height: 270px; overflow-y: auto;">
              <button v-for="(user, index) in filteredDirectUsers" :key="user.UserId" @click="selectUser(index, user)"
                class="btn w-100 text-start d-flex justify-content-between align-items-center mb-1 listhovereffect direct"
                :class="{ 'border-primary': selectedUserId === user.UserId }">

                <div class="d-flex">
                  <div class="statuss">{{ getInitials(user.UserName) }}</div>
                   <div class="text-left">
                      <div class="fw-semibold" :title="user.UserName">{{ user.UserName }}</div>
                      <span class="text-muted font-11">{{ user.UserType }}</span>
                    </div>
                </div>

                <span class="roundbadge">
                  {{ user.UserMessageCount }}
                </span>

              </button>
            </div>

            <div class="col-12 mb-3 font-14 text-center text-danger border p-2 "
              v-if="filteredDirectUsers.length === 0">
              {{ $t('NoRecordfound') }}
            </div>


          </div>
        </div>
      </div>
      <div class="flex-grow-1 d-flex flex-column bg-white w-100 mess_newdes_right">
        <div class="p-3 border-bottom 121212" v-if="activeDiscussion">
          <div class="col-lg-12 mb-0 p-0 float-left">
            <div class="heading-border mt-2">
              <h6 class="h5">
                <span>
                  {{ activeDiscussion.discussion_title }}
                  ({{ formattedDiscussionType(activeDiscussion.discussion_type) }})
                  <a href="javascript:;" class="text-muted mx-2  mr-5"
                    @click="ShowMessagePopup(activeDiscussion.discussion_id)" title="Edit Discussion Topic"
                    data-bs-toggle="tooltip" data-bs-placement="top">
                    <em v-if="CheckDisabled()" class="fa fa-edit text-success font-20"></em>
                  </a>
                 
                </span>
                <small class="float-right position-relative" >
                  <a href="javascript:;" class="font-14 text-primary"  v-if="activeDiscussion.discussion_type === 'private'"
                     @mouseenter="showDiscussionUsers" 
                     @mouseleave="hideDiscussionUsers">
                    <em class="fa fa-eye mr-1"></em>View Users
                  </a>
                  <a v-if="CheckDisabled()" title="Clear Chat" href="javascript:;" class="font-14 text-info ml-3" @click="claerChat(activeDiscussion.discussion_id)" ><em class="fa fa-refresh mr-1"></em>Clear Chat</a>
                  <a v-if="CheckDisabled()" title="Delete Chat" href="javascript:;" class="font-14 text-danger ml-3" @click="DeleteBoard(activeDiscussion.discussion_id)"><em class="fa fa-trash-o mr-1"></em>Delete Group</a>
                 
                  <div class="viewmoretagsbase_ptl showTags pmlists" v-if="isShowDiscussionUsersPopover">
                  <div class="popover-arrowss_ptl"></div>
                  <div class="viewmoretags_ptl">
                    <span class="head">{{ $t('Users') }}</span>
                    <div class="outerbase">
                      <span v-for="(item, index) in getDiscussionUsersList" :key="index" :title="item">
                        {{ index + 1 }}. {{ TruncateStr(item, 20) }}
                      </span>
                    </div>
                  </div>
                </div>
                </small>
              </h6>
            </div>
            <small class="text-muted">
              {{ getMessageCountForDiscussion(activeDiscussionId) }} {{ $t('Messages') }} •
              {{ $t('created_by_name') }} {{ activeDiscussion.created_by_name }} •
              {{ formatDate(activeDiscussion.created_at) }}
            </small>
          </div>
          <div v-if="activeDiscussion && activeDiscussion.discussion_description && !isUserData"
            class="p-0 mb-0 uniquepanes col-lg-12 float-left">
            <div class="d-flex align-items-baseline">
              <span class="text-muted flex-grow-1 font-13">{{ activeDiscussion.discussion_description }}</span>
            </div>
          </div>
        </div>
        <div class="p-3 border-bottom d-flex align-items-center gap-2 justify-content-between hshshs" v-if="isUserData">
          <div class="col-lg-12 mb-2 p-0">
            <div class="heading-border mt-2">
              <h6 class="h5">
                <span :title="UserData.UserName">{{ UserData.UserName }} ({{ formattedDiscussionType(UserData.UserType) }})</span>
                <small class="float-right">
                </small>
              </h6>
            </div>
            <small class="text-muted">
              {{ getMessageCountForUser(selectedUserId) }} {{ $t('Messages') }} •
              Direct message conversation
            </small>
          </div>
        </div>
        <div class="flex-grow-1 overflow-auto p-3">
          <div v-for="(message, index) in currentMessages" :key="message.messageId"
            class="px-3 py-2 mb-1 rounded bg-light chatpanes" v-if="(message.user_id !== LoginUserId && !message.is_deleted_for_me) 
   || (message.user_id === LoginUserId && !message.is_deleted_for_me)">
          
            <div class="d-flex gap-2" >
              <div class="chat-avatar bg-primary">
                {{ getInitials(message.user_name) }}
              </div>
           
              <div class="flex-grow-1" >
                <div class="fw-semibold">
                  <span class="font-weight-medium mr-2" :title="message.user_name">{{ message.user_name }}</span>
                  <small class="text-muted">• {{ formatDateTime(message.created_at) }}</small>
                  <span v-if="message.is_admin" class="badge bg-warning text-dark ml-2">
                    <em class="fa fa-shield-alt"></em> Admin
                  </span>
                </div>
                <p class="mb-2 font-14" v-html="renderMessageContent(message.content)" @click="handleMentionClick($event, message.content)"></p>
                <div class="mt-2 roundpills">
                  <div class="float-left position-relative d-inline-block"
                    @mouseenter="showLikedByPopover(message.messageId)"
                    @mouseleave="hideLikedByPopover()">
                    <button class="btn btn-sm rounded-pill mr-2"
                      :class="message.is_liked_by_current_user ? 'btn-primary' : 'btn-outline-primary'"
                      @click="toggleLike(message)" :disabled="isLoading">
                      <em class="fa fa-thumbs-up mr-1"></em>
                      {{ message.likes || 0 }}
                      <!-- {{LoginUserId +'/'+ message.user_id}} -->
                    </button>
                    <div v-if="hoveredLikeMessageId === message.messageId && message.likes > 0 && message.liked_name && message.liked_name.trim()"
                      class="viewmoretagsbase_ptl showTags msgs_likedby"
                      @mouseenter="showLikedByPopover(message.messageId)"
                      @mouseleave="hideLikedByPopover()">
                      <div class="popover-arrowss_ptl"></div>
                      <div class="viewmoretags_ptl">
                        <span class="head">{{ $t('Liked  by') }}</span>
                        <div class="outerbase">
                          <span v-for="(item, index) in (message.liked_name || '').split(',').filter(name => name.trim())" 
                            :key="index" 
                            :title="item.trim()">
                            {{ index + 1 }}. {{ TruncateStr(item.trim(), 20) }}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <button class="btn btn-sm rounded-pill mr-2 btn-outline-info" title="Attachments"
                    :disabled="isLoading || !message.file_attachments || !message.file_attachments.length"
                    @click="DownloadAttachment(message, message.file_attachments)">
                    <em class="fa fa-paperclip mr-1"></em>
                    {{ message.total_file_count || 0 }}
                  </button>
                </div>
                <div class="replythreadbase mt-3" v-if="message.Reply.length > 0">
                  <div class="d-flex gap-2 mb-2" v-for="ritem in message.Reply" :key="ritem.message_board_comment_id">
                    <div class="chat-avatar"> {{ getInitials(ritem.comment_posted_by) }} </div>
                    <div class="flex-grow-1">
                      <div class="fw-semibold">
                        <span class="font-weight-medium mr-2" :title="ritem.comment_posted_by">{{ ritem.comment_posted_by }}</span>
                        <small class="text-muted">{{ formatDateTime(ritem.created_at) }}</small>
                        <span>
                          <a v-if="ritem.created_by === LoginUserId"><em class="fa fa-pencil font-14 text-success ml-3"
                              @click="openReplyMessagePopup(ritem, message)"></em></a>
                          <a
                            v-if="!(activeDiscussion && activeDiscussion.discussion_type === 'private' && !isUserInDiscussion(LoginUserId) && ritem.created_by !== LoginUserId)">
                            <em class="fa fa-trash-o font-14 text-danger ml-3"
                              @click="DeleteMessageComment(ritem.created_by, ritem.message_board_comment_id, 'MessageBoardReply')">
                            </em>
                          </a>
                        </span>
                      </div>
                      <!-- Reply message text with @mention highlighting and click navigation -->
                      <p class="mb-2 font-13"
                         v-html="renderMessageContent(ritem.message_board_comment_title)"
                         @click="handleMentionClick($event, ritem.message_board_comment_title)">
                      </p>
                      <div class="mt-2 roundpills">
                        <!--Reply Attachment Count Badge -->
                        <button class="btn btn-sm rounded-pill mr-2 btn-outline-info" title="Attachments"
                          :disabled="isLoading || !ritem.file_attachments || !ritem.file_attachments.length"
                          @click="DownloadAttachment(ritem, ritem.file_attachments)">
                          <em class="fa fa-paperclip mr-1"></em>
                          {{ ritem.total_file_count || 0 }}
                        </button>

                      </div>
                    </div>
                  </div>
                </div>

                <div class="replybase" v-if="activeReplyIndex === index">
                  <div class="mt-2 position-relative">
                    <form class="d-flex gap-2 textareamsg" @submit.prevent="sendMessage(message, 'Replay')">
                      <button type="button" class="emojibx pt-" @click="toggleEmojiPickerForReply(index)">
                        <i class="fa fa-smile text-warning"></i>
                      </button>

                      <div class="flex-grow-1 position-relative border-left">
                        <input class="form-control w-75 bg-light mt-1" :class="['form-control chat-input', { 'edit-highlight':  editingIndex === index || replyingIndex === index}]"
                          :placeholder="editingReplyId && editingReplyParentId === message.messageId ? 'Editing reply...' : (isUserData ? 'Type your direct message...' : 'Type your message...')"
                          v-model="newMessageContent" @keydown.enter.exact.prevent="sendMessage(message, 'Replay')"
                          @keydown.enter.shift.exact="onNewLine" @input="handleMentionInput($event, 'reply', index)"
                          @keydown="handleMentionKeydown($event, 'reply', index)"
                          @keydown.esc="cancelEditReply"
                          :ref="'replyInput_' + index" />


                        <div v-if="attachments.length > 0 && isFiletype == 'Replay'"
                          class="attachment-preview mt-2 p-2 border rounded bg-light">
                          <div v-for="(attachment, index) in attachments" :key="index"
                            class="d-flex align-items-center mb-1">
                            <span class="text-truncate flex-grow-1">
                              <em class="fa fa-paperclip mr-1"></em>
                              {{ attachment.name }}
                              <small class="text-muted">({{ formatFileSize(attachment.size) }})</small>
                            </span>

                            <!-- Attachment or screenshot download karne ka button -->
                            <button type="button" class="btn btn-sm btn-outline-success ml-1"
                              @click="downloadFile(attachment.file)" title="Download Attachment">
                              <em class="fa fa-download"></em>
                            </button>

                            <!-- end -->
                            <button type="button" class="btn btn-sm btn-outline-danger ml-2"
                              @click="removeAttachment(index)">
                              <em class="fa fa-times"></em>
                            </button>
                          </div>
                        </div>
                      </div>

                      <button type="button" class="emojibx" v-if="isSpinner">
                        <i class='fa fa-spinner fa-spin'></i>
                      </button>

                      <!-- In the reply message Screenshot button section -->
                      <div v-if="!isSpinner" class="ml-auto mt-2">
                        <button type="button" class="camerabutton" @click="takeScreenshot('Replay')"
                          title="Take Screenshot">
                          <em class="fa fa-camera"></em>
                        </button>

                        <button type="button" class="attachmentbutton" @click="triggerFileInput('Replay')"
                          title="Add Attachment">
                          <em class="fa fa-paperclip"></em>
                        </button>

                        <!-- <button type="button" class="sendbuttons" 
                        :disabled="!newMessageContent.trim() && attachments.length === 0"
                        @click="sendMessage(message, 'Replay')">
                        <em class="fa fa-paper-plane"></em>
                      </button> -->

                        <!-- Reply send -->
                        <button type="button" class="sendbuttons" :disabled="isSending || isSpinner"
                          @click="sendMessage(message, 'Replay')">
                          <em class="fa fa-paper-plane"></em>
                        </button>

                        <button type="button" class="clearbuttons"
                          :disabled="!newMessageContent.trim() && attachments.length === 0"
                          @click="newMessageContent = ''; attachments = []">
                          <em class="fa fa-refresh"></em>
                        </button>
                      </div>

                    </form>
                    <!-- Emoji Picker for Reply -->
                    <div v-if="showemoji && emojiContext === 'reply' && emojiReplyIndex === index"
                      class="reply-emoji-picker">
                      <VEmojiPicker @select="selectEmoji" />
                    </div>
                    <!-- Mention Dropdown for Reply -->
                    <div v-if="showMentionDropdown && mentionContext === 'reply' && mentionReplyIndex === index && !(isUserData && selectedUserId)"
                      class="mention-dropdown">



                      <div v-if="filteredMentionUsers.length > 0">
                        <!-- <div class="d-flex">
                      <div class="statuss">LS</div>
                      <div class="text-left">
                        <div class="fw-semibold">lakwinder singh</div>
                        <span class="text-muted font-11">PM</span>
                      </div>
                    </div> -->
                        <div v-for="(user, idx) in filteredMentionUsers" :key="user.UserId" class="mention-item d-flex"
                          :class="{ 'active': selectedMentionIndex === idx }"
                          @click="selectMention(user, 'reply', index)">

                          <div class="statuss text-center">{{ getInitials(user.UserName) }}</div>

                          <div class="text-left">
                            <strong>{{ user.UserName }}</strong>
                            <small class="text-muted d-block">{{ user.UserType || 'User' }}</small>
                          </div>

                        </div>

                      </div>




                      <div v-else class="mention-item text-muted">
                        No users found
                      </div>
                    </div>
                  </div>
                </div>

                <!-- Reply Ends Here... -->

              </div>
            </div>

            <div class="chatpanes_acts">
              <a href="javascript:;" @click="showAddMessageBox(index)" title="Reply">
                <em class="fa fa-comment-o font-16 text-warning fw-bold"></em>
              </a>
              <a v-if="message.user_id === LoginUserId" href="javascript:;" @click="showAddProjectMessage(message)"
                title="Edit">
                <em class="fa fa-edit font-16 text-success"></em>
              </a>
              <!-- @click="DeleteMessage(message.messageId)"  -->
              <a href="javascript:;" @click="DeleteMessageComment(message.user_id, message.messageId, 'MessageBoard')"
                title="Delete" >
                <em class="fa fa-trash-o font-16 text-danger"></em>
              </a>
            </div>
          </div>

          <!-- Empty States -->

          <div v-if="!activeDiscussion && !isUserData" class="text-center p-3">
            <img src="https://talygenv.github.io/Vue-UI-Content/images/nomess3.png" style="width:250px;" class="mt-4" />
            <p class="text-center text-muted mb-4 font-14">Select a discussion topic or user from the sidebar to view messages</p>
          </div>
          <div v-if="currentMessages.length === 0 && isUserData" class="text-center p-3">
            <img src="https://talygenv.github.io/Vue-UI-Content/images/nomess3.png" style="width:250px;" class="mt-4" />
            <p class="text-center text-muted mb-4 font-14">No messages yet. Start the conversation!</p>
          </div>
          <div v-if="currentMessages.length === 0 && activeDiscussion" class="text-center p-3">
            <img src="https://talygenv.github.io/Vue-UI-Content/images/nomess3.png" style="width:250px;" class="mt-4" />
            <p class="text-center text-muted mb-4 font-14">No messages yet. Start the conversation!</p>
          </div>

        </div>

        <!-- Message Input for both Discussions and Direct Messages -->
        <div class="border-top p-1 position-relative" v-if="activeDiscussion || isUserData">
          <form class="d-flex align-items-end  textareamsg " @submit.prevent="sendMessage(null, 'Discuss')"
            @keydown.enter.exact.prevent="sendMessage(null, 'Discuss')" @keydown.enter.shift.exact="onNewLine">

            <!-- File Input (Hidden) -->
            <input type="file" ref="fileInput" multiple style="display: none" @change="handleFileUpload">
            <button type="button" class="emojibx" @click="toggleEmojiPicker">
              <i class="fa fa-smile text-warning"></i>
            </button>

            <!-- Textarea with Attachment Preview -->
            <div class="flex-grow-1 position-relative border-left" >

                <textarea class="form-control" rows="2"  :class="['form-control chat-input', { 'edit-highlight': isEditing || isReplying }]"
                  ref="mainMessageTextarea"
                  :placeholder="editingMessageId ? 'Editing message...' : (isUserData ? 'Type your direct message...' : 'Type your message...')"
                  v-model="messageContent"
                   @input="handleMentionInput($event, 'main')"
                  @keydown="handleMentionKeydown($event, 'main')"
                  @keydown.esc="cancelEditMessage"></textarea>



              <!-- Attachment Preview -->
              <div v-if="attachments.length > 0 && isFiletype != 'Replay'"
                class="attachment-preview mt-2 p-2 border rounded bg-light">
                <div v-for="(attachment, index) in attachments" :key="index" class="d-flex align-items-center mb-1">
                  <span class="text-truncate flex-grow-1">
                    <em class="fa fa-paperclip mr-1"></em>
                    {{ attachment.name }}
                    <small class="text-muted">({{ formatFileSize(attachment.size) }})</small>
                  </span>

                  <!-- Attachment or screenshot download karne ka button -->

                  <button type="button" class="btn btn-sm btn-outline-success ml-1"
                    @click="downloadFile(attachment.file)" title="Download Attachment">
                    <em class="fa fa-download"></em>
                  </button>
                  <button type="button" class="btn btn-sm btn-outline-danger ml-2" @click="removeAttachment(index)">
                    <em class="fa fa-times"></em>
                  </button>
                </div>
              </div>
            </div>

            <div class="d-flex align-items-end btmbutton" style="gap: 2px">

              <!-- spinner -->
              <button type="button" class="emojibx" v-if="isSpinner">
                <i class='fa fa-spinner fa-spin'></i>
              </button>

              <div v-if="!isSpinner">
                <!-- Main Screenshot Button -->
                <button type="button" class="btn btn-sm" @click="takeScreenshot('Discuss')" title="Take Screenshot">
                  <em class="fa fa-camera"></em>
                </button>

                <!-- Attachment Button -->
                <button type="button" class="btn btn-sm" @click="triggerFileInput('Discuss')" title="Add Attachment">
                  <em class="fa fa-paperclip"></em>
                </button>

                <!-- Send Button -->
                <!-- <button type="button" class="sendbutton" :disabled="!messageContent.trim() && attachments.length === 0"
                @click="sendMessage(null, 'Discuss')">
                <em class="fa fa-paper-plane"></em>
              </button> -->

                <button type="button" class="sendbutton" :disabled="isSending || isSpinner"
                  @click="sendMessage(null, 'Discuss')">
                  <em class="fa fa-paper-plane"></em>
                </button>

              </div>
            </div>
          </form>
          <!-- Emoji Picker for Main Input -->
          <div v-if="showemoji && emojiContext === 'main'" class="main-emoji-picker">
            <VEmojiPicker @select="selectEmoji" />
          </div>
          <!-- Mention Dropdown for Main Input -->
          <div v-if="showMentionDropdown && mentionContext === 'main' && !(isUserData && selectedUserId)" class="mention-dropdown">

            <div v-if="filteredMentionUsers.length > 0">
              <div v-for="(user, idx) in filteredMentionUsers" :key="user.UserId" class="mention-item d-flex"
                :class="{ 'active': selectedMentionIndex === idx }" @click="selectMention(user, 'main')">
                <div class="statuss text-center">{{ getInitials(user.UserName) }}</div>
                <div class="text-left">
                  <strong>{{ user.UserName }}</strong>
                  <small class="text-muted d-block">{{ user.UserType || 'User' }}</small>
                </div>
              </div>
            </div>



            <div v-else class="mention-item text-muted">
              No users found
            </div>
          </div>
          <small class="text-muted font-12">{{ $t('PressEntertosend') }} <span class="font-weight-600 font-14">+</span>
            {{ $t('Enterfornewline') }}</small>
        </div>


      </div>
    </div>
    <div v-if="openReplyMessageModel">
      <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
          <div class="modal-dialog modal-dialog-centered mw-800">
            <div class="modal-content">
              <div class="modal-header theme-primary partition-full d-flex">
                <h4 class="modal-title">{{ $t('UpdateMessage') }}</h4>
                <button type="button" class="close" v-on:click="openReplyMessageModel = false">
                  <em class="fa fa-times" aria-hidden="true"></em>
                </button>
              </div>
              <div class="modal-body">
                <div class="mb-3">
                  <label for="discussiontitle" class="form-label">{{ $t('Message') }}</label>
                  <div class="input-group">
                    <textarea type="textarea" class="form-control border-start-0" id="discussiontitle"
                      placeholder="Discussion Title" v-model="newMessageContent" required rows="7" cols="50"></textarea>
                  </div>
                </div>
                <div class="d-flex justify-content-end mt-4">
                  <button type="submit" class="btn btn-success"
                    @click="sendMessage(showAddMessagePopupEditValue, 'Replay')"><em class="fa fa-save pr-2"></em>{{
                      $t('UpdateMessage') }}</button>
                  <button type="button" class="btn btn-danger ml-2" @click="openReplyMessageModel = false"><em
                      class="fa fa-close pr-2"></em>{{ $t('Close') }}</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <AddMessagepopup v-if="showAddMessagePopup" :MessegeId="MessegeId" :projectId="projectId"
      :DiscussionId="DiscussionId" @close="showAddMessagePopup = false" @message-saved="handleMessageSaved" />
    <DirectMessagepopup v-if="showDirectMessagePopup" :projectId="projectId" @close="showDirectMessagePopup = false" />
    <AddProjectMessage v-if="showAddProjectMessagePopup" :projectId="projectId"
      :discussionId="isUserData ? 0 : activeDiscussionId" :message="message"
      :discussionTitle="isUserData ? `Direct message to ${UserData.UserName}` : (activeDiscussion ? activeDiscussion.discussion_title : '')"
      :discussionType="isUserData ? 'direct' : (activeDiscussion ? activeDiscussion.discussion_type : 'public')"
      :MessegeId="MessegeId" :Userid="isUserData ? selectedUserId : 0" @close="showAddProjectMessagePopup = false"
      @message-saved="handleProjectMessageSaved" />
    <AddAttachmentAndSacreenShot v-if="showAttachmentAndSacreenPopup" :attachmentFileData="attachmentFileData">
    </AddAttachmentAndSacreenShot>
  </section>
</template>

<script>
import DataService from '../../../../services/DataService';
import AddProjectMessage from '../../../../components/Modal/AddProjectMessage.vue';
import AddMessagepopup from '../../../../components/Modal/AddMessagepopup.vue';
import DirectMessagepopup from '../../../../components/Modal/DirectMessagepopup.vue';
import jsPDF from 'jspdf';
import html2canvas from "html2canvas"
//npm run serve import html2pdf from 'html2pdf.js';
import { VEmojiPicker } from 'v-emoji-picker';
import AddAttachmentAndSacreenShot from '../../../../components/Modal/AddAttachmentAndSacreenShot.vue';


export default {
  components: {
    AddMessagepopup,
    DirectMessagepopup,
    AddProjectMessage,
    VEmojiPicker,
    AddAttachmentAndSacreenShot,
  },
  props: {
    projectId: {
      type: Number,
      required: true
    },
    checkPmUser: {
      type: Boolean,
      required: true
    },
     projectName: {
      type: String,
      required: true
    },
  },
  data() {
    return {
      showAddProjectMessagePopup: false,
      MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
      activeDiscussionId: null,
      isSpinner: false,
      MessegeId: 0,
      message: '',
      DiscussionId: 0,
      searchteamFilter: '',
      attachmentFileData: [],
      showemoji: false,
      emojiContext: 'main', // 'main' or 'reply'
      emojiReplyIndex: null, // Track which reply index the emoji picker is for
      txtMessage: '',
      reactionToUser: null,
      ReactionID: null,
      IsreactOnMessage: false,
      isShowDiscussionUsersPopover: false,
      openReplyMessageModel: false,
      showAttachmentAndSacreenPopup: false,
      isFiletype: '',
      showAddMessagePopup: false,
      showAddMessagePopupEditValue: '',
      showDirectMessagePopup: false,
      newMessageContent: '',
      messageContent: '',
      DirectMessageContent: '',
      isLoading: false,
      activeReplyIndex: null,
      PageSize: 100,
      CompanyId: null,
      PageNumber: 1,
      logged_usertype: null,
      LoginUserId: null,
      discussions: [],
      messages: [],
      messages2: [],
      directMessages: [],
      directMessages2: [],
      DirectUserData: [],
      DirectUserData2: [],
      isFirstLoad: true,
      isUserData: false,
      UserData: [],
      TeamMembers: [],
      Users: [],
      selectedUserId: null,
    isEditing: false,
    isReplying: false,
    editMessageId: null,
    replyMessageId: null,
    editingIndex: null,
  replyingIndex: null,

    messageText: "",
      MessageTypeName: '',
      searchFilter: '',
      typeFilter: '',
      discussionTypes: [
        { value: '', label: 'All' },
        { value: 'public', label: 'Public' },
        { value: 'private', label: 'Private' }
      ],
      messageLikes: {},
      TimeZone: '',
      attachments: [],
      screenshot: null,
      SelectedTeamMembers: [],
      index: 0,
      UserType: '',
      UserName: '',
      // Mention functionality
      showMentionDropdown: false,
      mentionSearchTerm: '',
      mentionPosition: null,
      mentionContext: 'main', // 'main' or 'reply'
      mentionReplyIndex: null,
      selectedMentionIndex: 0,
      editingMainMessage: false,
      isSending: false,
      hoveredLikeMessageId: null, // Track which message's like popover is being hovered
      editingMessageId: null, // Track which main message is being edited
      editingReplyId: null, // Track which reply is being edited
      editingReplyParentId: null, // Track parent message ID for the reply being edited
    };
  },
  computed: {
    activeDiscussion() {
      if (this.isUserData) {
        return null;
      } else {
        return this.discussions.find(d => d.discussion_id === this.activeDiscussionId) || null;
      }
    },

    currentMessages() {
      if (this.isLoading) {
        return [];
      }

      if (this.isUserData && this.selectedUserId) {
        return this.getMessagesForUser(this.selectedUserId);
      } else if (this.activeDiscussionId) {
        return this.getMessagesForDiscussion(this.activeDiscussionId);
      } else {
        return [];
      }
    },

    // Filtered discussions based on search and type filters
    filteredDiscussions() {
      let filtered = this.discussions;
      // Apply search filter
      if (this.searchFilter) {
        const searchTerm = this.searchFilter.toLowerCase();
        filtered = filtered.filter(discussion =>
          discussion.discussion_title.toLowerCase().includes(searchTerm) ||
          (discussion.discussion_description && discussion.discussion_description.toLowerCase().includes(searchTerm)) ||
          discussion.created_by_name.toLowerCase().includes(searchTerm)
        );
      }
      // Apply type filter
      if (this.typeFilter) {
        filtered = filtered.filter(discussion =>
          discussion.discussion_type === this.typeFilter
        );
      }
      return filtered;
    },

    // Filtered direct users based on search filter
    filteredDirectUsers() {
      let filtered = this.DirectUserData;
      // Apply search filter
      if (this.searchteamFilter) {
        const searchTerm = this.searchteamFilter.toLowerCase();
        filtered = filtered.filter(user =>
          user.UserName.toLowerCase().includes(searchTerm) ||
          user.UserType.toLowerCase().includes(searchTerm)
        );
      }
      return filtered;
    },

    // Filtered users for mention dropdown
    getDiscussionUsersList() {      
      if (!this.activeDiscussion || !this.activeDiscussion.UserNames) {
        return [];
      }
      return this.activeDiscussion.UserNames.split(',').map(name => name.trim()).filter(name => name !== '');
    },

    filteredMentionUsers() {
      if (!this.showMentionDropdown) return [];

      // For one-to-one chats, disable mentions completely
      if (this.isUserData && this.selectedUserId) {
        return [];
      }

      // Get available users based on discussion type
      let availableUsers = this.getAvailableUsersForMentions();
      
      if (!availableUsers || availableUsers.length === 0) {
        return [];
      }

      // Apply search filter
      let filtered = availableUsers;
      if (this.mentionSearchTerm) {
        const searchTerm = this.mentionSearchTerm.toLowerCase();
        filtered = filtered.filter(user =>
          user.UserName.toLowerCase().includes(searchTerm) ||
          (user.UserType && user.UserType.toLowerCase().includes(searchTerm))
        );
      }
      return filtered.slice(0, 10); // Limit to 10 results
    }
  },
  mounted() {
    this.initializeComponent();
    this.FetchTeam();
  },
  created() {
    debugger
    this.initializeComponent();
    this.FetchTeam();
    this.TimeZone = this.GetUserInfo.TimeZone;
    this.LoginUserId = this.GetUserInfo.ID;
    this.UserType = this.GetUserInfo.UserType;
    this.UserName = this.GetUserInfo.Name;
    this.CheckDisabled();
  },
  beforeDestroy() {
    // Clean up emoji outside-click handler
    document.removeEventListener('click', this.handleEmojiClickOutside);
    // Clean up mention outside-click handler
    document.removeEventListener('click', this.handleMentionClickOutside);
    // Clean up reply emoji picker scroll and resize handlers
    this.removeReplyEmojiPickerListeners();
  },
  methods: {
    // Helper to get available users for mentions based on discussion type
    getAvailableUsersForMentions() {
      // One-to-one chat: no mentions allowed
      if (this.isUserData && this.selectedUserId) {
        return [];
      }

      // Ensure DirectUserData exists
      if (!this.DirectUserData || !Array.isArray(this.DirectUserData)) {
        return [];
      }

      // Private group discussion: only group members
      if (this.activeDiscussion && this.activeDiscussion.discussion_type === 'private') {
        if (!this.activeDiscussion.UserIds || !this.activeDiscussion.UserIds.trim()) {
          return [];
        }
        
        const groupUserIds = this.activeDiscussion.UserIds
          .split(',')
          .map(id => id.trim())
          .filter(id => id !== '');
        
        return this.DirectUserData.filter(user => 
          user && user.UserId && groupUserIds.includes(String(user.UserId))
        );
      }

      // Public discussion: all users
      return this.DirectUserData;
    },
    CheckDisabled() {
      if ((this.UserType == 'CL' || this.UserType == 'NU') && this.checkPmUser) {
        return true;
      }
      else {
        if (this.UserType == 'CA' || this.UserType == 'PM') {
          return true;
        }
        else {
          return false;
        }

      }
    },
    renderMessageContent(text) {
      try {
        if (!text) return '';
        
        // For one-to-one chats, return plain text without mention highlighting
        if (this.isUserData && this.selectedUserId) {
          return String(text)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
        }
        
        // Normalize to string and escape HTML once
        const rawText = String(text);
        let escapedText = rawText
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#039;');
        
        let result = '';
        let i = 0;
        
        // Simple, linear scan to wrap @mentions; avoids any recursive or exponential behavior
        while (i < escapedText.length) {
          if (escapedText[i] === '@' && 
              (i === 0 || /\s/.test(escapedText[i - 1]))) {
            
            let mention = '@';
            let mentionText = '';
            let wordCount = 0;
            i++; // move past '@'
            
            while (i < escapedText.length) {
              const char = escapedText[i];
              
              if (/[a-zA-Z]/.test(char)) {
                mention += char;
                mentionText += char;
                i++;
              } 
              else if (char === ' ' && mention.length > 1 && !mention.endsWith(' ')) {
                if (i + 1 < escapedText.length && /[a-zA-Z]/.test(escapedText[i + 1])) {
                  mention += ' ';
                  mentionText += ' ';
                  i++;
                  wordCount++;
                  if (wordCount >= 2) { 
                    break;
                  }
                } else {
                  break;
                }
              } 
              else {
                break;
              }
            }
            
            // Always highlight syntactically valid @mentions so that
            // messages loaded from history are consistent for all users
            result += `<span class="mention-highlight" data-mention="${mentionText}">${mention}</span>`;
          } else {
            result += escapedText[i];
            i++;
          }
        }
        
        return result;
      } catch (e) {
        // Fail-safe: never break rendering; just return safely escaped text
        console.error('Error in renderMessageContent:', e);
        return String(text || '')
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#039;');
      }
    },
    toggleEmojiPicker() {
      // Toggle emoji picker for main input
      if (this.showemoji && this.emojiContext === 'main') {
        this.showemoji = false;
        this.emojiContext = 'main';
        this.emojiReplyIndex = null;
        document.removeEventListener('click', this.handleEmojiClickOutside);
      } else {
        this.emojiContext = 'main';
        this.emojiReplyIndex = null;
        this.showemoji = true;
        // Attach outside-click handler
        this.$nextTick(() => {
          document.addEventListener('click', this.handleEmojiClickOutside);
        });
      }
    },
    DownloadAttachment(itm) {
      this.attachmentFileData = itm;
      this.showAttachmentAndSacreenPopup = true;

    },
    toggleEmojiPickerForReply(index) {
      // Toggle emoji picker for reply box
      if (this.showemoji && this.emojiContext === 'reply' && this.emojiReplyIndex === index) {
        this.showemoji = false;
        this.emojiContext = 'main';
        this.emojiReplyIndex = null;
        document.removeEventListener('click', this.handleEmojiClickOutside);
        // Remove scroll and resize handlers
        this.removeReplyEmojiPickerListeners();
      } else {
        this.emojiContext = 'reply';
        this.emojiReplyIndex = index;
        this.showemoji = true;
        // Attach outside-click handler and position the picker
        this.$nextTick(() => {
          document.addEventListener('click', this.handleEmojiClickOutside);
          // Wait for picker to be fully rendered before positioning
          // Use double nextTick to ensure VEmojiPicker component is rendered
          this.$nextTick(() => {
            // Position the emoji picker relative to the replybase
            this.positionReplyEmojiPicker(index);
            // Add scroll and resize handlers to reposition on scroll/resize
            this.addReplyEmojiPickerListeners(index);
          });
        });
      }
    },
    addReplyEmojiPickerListeners(index) {
      // Store the index for the handler
      this._replyEmojiPickerIndex = index;
      // Create bound handlers
      this._replyEmojiPickerScrollHandler = () => {
        if (this.showemoji && this.emojiContext === 'reply' && this.emojiReplyIndex === index) {
          this.positionReplyEmojiPicker(index);
        }
      };
      this._replyEmojiPickerResizeHandler = () => {
        if (this.showemoji && this.emojiContext === 'reply' && this.emojiReplyIndex === index) {
          this.positionReplyEmojiPicker(index);
        }
      };
      // Add event listeners
      const scrollContainer = this.$el.querySelector('.flex-grow-1.overflow-auto');
      if (scrollContainer) {
        scrollContainer.addEventListener('scroll', this._replyEmojiPickerScrollHandler, { passive: true });
      }
      window.addEventListener('scroll', this._replyEmojiPickerScrollHandler, { passive: true });
      window.addEventListener('resize', this._replyEmojiPickerResizeHandler);
    },
    removeReplyEmojiPickerListeners() {
      const scrollContainer = this.$el.querySelector('.flex-grow-1.overflow-auto');
      if (scrollContainer && this._replyEmojiPickerScrollHandler) {
        scrollContainer.removeEventListener('scroll', this._replyEmojiPickerScrollHandler);
      }
      if (this._replyEmojiPickerScrollHandler) {
        window.removeEventListener('scroll', this._replyEmojiPickerScrollHandler);
      }
      if (this._replyEmojiPickerResizeHandler) {
        window.removeEventListener('resize', this._replyEmojiPickerResizeHandler);
      }
      this._replyEmojiPickerScrollHandler = null;
      this._replyEmojiPickerResizeHandler = null;
      this._replyEmojiPickerIndex = null;
    },
    positionReplyEmojiPicker(index) {
      const picker = this.$el.querySelector('.reply-emoji-picker');
      if (!picker) return;

      // Find the replybase for this specific reply
      const messageElements = this.$el.querySelectorAll('.chatpanes');
      if (!messageElements || !messageElements[index]) return;

      const messageElement = messageElements[index];
      const replybase = messageElement.querySelector('.replybase');
      if (!replybase) return;

      // Find the emoji button to position relative to it
      const emojiButton = replybase.querySelector('.emojibx');
      if (!emojiButton) return;

      // Function to actually position the picker
      const doPosition = () => {
        // Get picker dimensions - use actual height or fallback
        let pickerHeight = picker.offsetHeight;
        if (!pickerHeight || pickerHeight === 0) {
          // If height is not available yet, use a reasonable default
          pickerHeight = 300;
          // Try again after a short delay if height is still 0
          setTimeout(() => {
            const actualHeight = picker.offsetHeight;
            if (actualHeight > 0) {
              doPosition(); // Reposition with actual height
            }
          }, 50);
        }

        const spacing = 10; // Space between button and picker

        // Get the position of the emoji button relative to viewport
        const buttonRect = emojiButton.getBoundingClientRect();
        const viewportHeight = window.innerHeight;
        //const spaceAbove = buttonRect.top;
        const spaceBelow = viewportHeight - buttonRect.bottom;

        // Position picker above the button if there's enough space, otherwise below
        if (spaceAbove >= pickerHeight + spacing) {
          // Position above the button
          picker.style.left = buttonRect.left + 'px';
          //picker.style.top = (buttonRect.top - pickerHeight - spacing) + 'px';
          picker.style.bottom = 'auto';
        } else if (spaceBelow >= pickerHeight + spacing) {
          // Position below the button if not enough space above
          picker.style.left = buttonRect.left + 'px';
         // picker.style.top = (buttonRect.bottom + spacing) + 'px';
          picker.style.bottom = 'auto';
        } else {
          // If neither has enough space, position above anyway (may be partially visible)
          // But ensure it's at least visible near the button
          picker.style.left = buttonRect.left + 'px';
          //picker.style.top = Math.max(10, buttonRect.top - pickerHeight - spacing) + 'px';
          picker.style.bottom = 'auto';
        }

        // Ensure picker doesn't go off-screen horizontally
        const pickerWidth = picker.offsetWidth || 330;
        if (buttonRect.left + pickerWidth > window.innerWidth) {
          picker.style.left = (window.innerWidth - pickerWidth - 10) + 'px';
        }
      };

      // Wait for picker to be fully rendered before calculating dimensions
      // Use requestAnimationFrame to ensure DOM is ready
      requestAnimationFrame(() => {
        doPosition();
      });
    },
    selectEmoji(emoji, type = null) {
      const vm = this;
      if (type === 'delete') {
        vm.reactionToUser = emoji.item;
        vm.ReactionID = emoji.data[0].ReactionId;
        emoji.data = emoji.data[0].ReactionType;
      } else {
        // this.updateRecentEmojis(emoji);
      }

      // Send reaction if a user is selected
      if (this.reactionToUser != null && this.reactionToUser != '') {
        vm.IsreactOnMessage = false;
        var thisUser = vm.reactionToUser;
        this.IsreactOnMessage = false;
        vm.$socket.emit(
          'messageRactions',
          {
            smileImage: emoji.data,
            chatlog_id: thisUser.CHATLOG_ID,
            fromUser: vm.store.getUserInformation.ID,
            toUser: thisUser.TO_USER_ID,
            groupid: thisUser.GROUP_ID,
            message_token: thisUser.MESSAGE_TOKEN,
            reactionId: vm.ReactionID
          },
          function () { }
        );
      } else {
        // If no user selected, just append emoji to the correct input
        // Check emoji context to determine which field to update
        if (this.emojiContext === 'reply' && this.emojiReplyIndex !== null) {
          // When replying to a message, use newMessageContent
          vm.newMessageContent = (vm.newMessageContent || '') + emoji.data;
        } else {
          // For main discussion/direct message box use messageContent
          vm.messageContent = (vm.messageContent || '') + emoji.data;
        }
      }
      vm.showemoji = false;
      vm.emojiContext = 'main';
      vm.emojiReplyIndex = null;
      document.removeEventListener('click', this.handleEmojiClickOutside);

    },
    handleEmojiClickOutside(event) {
      try {
        // If emoji picker is not open, nothing to do
        if (!this.showemoji) return;

        const picker = this.$el.querySelector('.main-emoji-picker, .reply-emoji-picker');
        const isEmojiButton = event.target.closest('.emojibx');

        // If click is inside picker or on emoji button, do nothing
        if (picker && picker.contains(event.target)) return;
        if (isEmojiButton) return;

        // Otherwise, close emoji picker
        this.showemoji = false;
        this.emojiContext = 'main';
        this.emojiReplyIndex = null;
        document.removeEventListener('click', this.handleEmojiClickOutside);
        // Remove scroll and resize handlers for reply picker
        this.removeReplyEmojiPickerListeners();
      } catch (e) {
        // Fail-safe: remove listener to avoid leaks
        document.removeEventListener('click', this.handleEmojiClickOutside);
        this.removeReplyEmojiPickerListeners();
      }
    },
    clearteamSearchFilter() {
      this.searchteamFilter = '';
    },
    initializeComponent() {
      this.CompanyId = this.GetUserInfo.CompanyId;
      //this.userId = this.GetUserInfo.ID;
      this.logged_usertype = this.GetUserInfo.UserType;

      // Load discussions first, then messages for the selected discussion
      this.GetProjectDiscussions();
    },
    async exportToChat(messagesArray, projectName = "Chat Export Report") {
  try {
    projectName=`${this.projectName} Chat`;
    const formatDate = (date) => {
      return new Date(date).toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hour12: true,
      }).replace(',', '');
    };

    /* ---------- HTML ---------- */
    let html = `
      <div id="pdfContent" style="
        font-family: Arial, sans-serif;
        padding:20px;
        width:800px;
        line-height:1.6;
        font-size:13px;
        background:#ffffff;
      ">
    `;

    (messagesArray || []).forEach(msg => {

      html += `
        <div style="margin-bottom:15px;">
          <div style="color:#007bff; font-weight:bold;">
            ${msg.user_name || ''}
