          </div>

          <div style="font-size:11px; color:#777;">
            Date: ${formatDate(msg.created_at)}
          </div>
      `;

      if (msg.Reply && msg.Reply.length > 0) {
        html += `
          <div style="
            margin-top:8px;
            margin-left:15px;
            background:#f5f5f5;
            border-left:2px solid #25D366;
            padding:8px;
          ">
        `;

        msg.Reply.forEach(reply => {
          html += `
            <div style="margin-bottom:6px;">
              <div style="color:#007bff; font-weight:bold;">
                ${reply.comment_posted_by}
              </div>

              <div>
                ${reply.message_board_comment_text || ''}
              </div>

              <div style="font-size:10px; color:#777;">
                Date: ${formatDate(reply.created_at)}
              </div>
            </div>
          `;
        });

        html += `</div>`;
      }

      html += `</div>`;
    });

    html += `</div>`;

    /* ---------- DOM RENDER ---------- */
    const container = document.createElement("div");
    container.style.position = "fixed";
    container.style.left = "0";
    container.style.top = "0";
    container.style.width = "800px";
    container.style.opacity = "0";
    container.innerHTML = html;

    document.body.appendChild(container);

    const element = document.getElementById("pdfContent");

    await new Promise(r => setTimeout(r, 300));

    /* ---------- CANVAS ---------- */
    const canvas = await html2canvas(element, {
      scale: 2,
      useCORS: true,
      backgroundColor: "#ffffff"
    });

    const pdf = new jsPDF('p', 'mm', 'a4');

    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();

    const imgWidth = 190;

    // 🔥 FIXED LAYOUT ZONES
    const headerHeight = 15;
    const footerHeight = 10;
    const contentStartY = headerHeight + 5;
    const contentHeight = pageHeight - headerHeight - footerHeight - 5;

    const pxPageHeight = Math.floor((canvas.width * contentHeight) / imgWidth);

    let position = 0;
    let page = 1;

    /* ---------- HEADER ---------- */
    const addHeader = () => {
      pdf.setFontSize(12);
      pdf.setTextColor(40);

      pdf.text(projectName, pageWidth / 2, 10, { align: 'center' });

      pdf.setDrawColor(200);
      pdf.line(10, 13, pageWidth - 10, 13);
    };

    /* ---------- FOOTER ---------- */
    const addFooter = (pageNo) => {
      pdf.setFontSize(9);
      pdf.setTextColor(120);

      pdf.text(`Page ${pageNo}`, pageWidth / 2, pageHeight - 5, { align: 'center' });
    };

    /* ---------- PAGE LOOP ---------- */
    while (position < canvas.height) {

      if (page > 1) pdf.addPage();

      // slice canvas properly
      const pageCanvas = document.createElement("canvas");
      const ctx = pageCanvas.getContext("2d");

      pageCanvas.width = canvas.width;
      pageCanvas.height = pxPageHeight;

      ctx.drawImage(
        canvas,
        0,
        position,
        canvas.width,
        pxPageHeight,
        0,
        0,
        canvas.width,
        pxPageHeight
      );

      const imgData = pageCanvas.toDataURL("image/png");

      addHeader();

      const imgHeight = (pxPageHeight * imgWidth) / canvas.width;

      pdf.addImage(
        imgData,
        'PNG',
        10,
        contentStartY,
        imgWidth,
        imgHeight
      );

      addFooter(page);

      position += pxPageHeight;
      page++;
    }

    pdf.save(`${projectName}.pdf`);

    document.body.removeChild(container);

  } catch (error) {
    console.error("EXPORT ERROR:", error);
    alert(error.message || 'Export failed');
  }
