      // Determine which content to check based on type
      let content = type === 'Replay' ? this.newMessageContent : this.messageContent;
      if (!content.trim() && this.attachments.length === 0) {
        this.ShowAlert("Please enter a message or attach files", "warning", true, "Validation");
        this.isSending = false;
        this.isSpinner = false;
        return;
      }

      try {
        this.isFiletype = type;
        const attachmentData = await this.prepareAttachmentsForAPI();

        if (this.isUserData && this.selectedUserId) {
          if (type == 'Replay') {
            await this.sendDiscussionReplyMessage(data, attachmentData);
          }
          if (type == 'Discuss') {
            await this.sendDirectMessage(data, attachmentData);
          }
        } else if (this.activeDiscussionId != null) {
          if (type == 'Replay') {
            await this.sendDiscussionReplyMessage(data, attachmentData);
          }
          if (type == 'Discuss') {
            await this.sendDiscussionMessage(attachmentData);
          }
        } else {
          this.ShowAlert(this.$t("SelectDiscussion"), "warning", true, "Validation");
          return;
        }

        // Clear ONLY after successful send (prevents sub-method validation failure)
        if (type === 'Replay') {
          this.newMessageContent = '';
          this.activeReplyIndex = null; // Close reply box
        } else {
          this.messageContent = '';
        }
        this.attachments = []; // Clear attachments too

      } catch (error) {
        console.error('Error sending message:', error);
        this.ShowAlert("Error sending message", "failure", true, "Error");
        // Do NOT clear on error (user can retry)
      } finally {
        this.isSending = false;
        this.isSpinner = false;
      }
    },




    async prepareAttachmentsForAPI() {
      const avatarArray = [];

      for (const attachment of this.attachments) {
        try {
          const base64String = await this.fileToBase64(attachment.file);

          avatarArray.push({
            fileName: attachment.name,
            attachement_mime: attachment.type,
            base64String: base64String,
            fileSize: attachment.size.toString(),
            AttachmentTitle: attachment.name
          });
        } catch (error) {
          console.error('Error converting file to base64:', error);
          throw new Error('Failed to process attachments');
        }
      }

      return avatarArray;
    },
    // Convert file to base64
    fileToBase64(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => {
          // Remove the data:image/...;base64, prefix
          const base64 = reader.result.split(',')[1];
          resolve(base64);
        };
        reader.onerror = error => reject(error);
      });
    },
    // Upload attachments to server
    async uploadAttachments() {
      const uploadedUrls = [];

      for (const attachment of this.attachments) {
        const formData = new FormData();
        formData.append('file', attachment.file);
        formData.append('projectId', this.projectId);
        formData.append('uploadType', 'message_attachment');
        try {
          const response = await DataService.UploadFile(formData);
          if (response.data && response.data.fileUrl) {
            uploadedUrls.push(response.data.fileUrl);
          }
        } catch (error) {
          console.error('Error uploading attachment:', error);
          throw new Error('Failed to upload attachments');
        }
      }
      return uploadedUrls;
    },

