        this.isSpinner = true;
        const messageTitle = this.messageContent.trim();
        if (messageTitle === '' && avatarArray.length === 0) {
          return false;
        }
        
        let teamMembersArr = '';
        // FIX: Use UserIds from activeDiscussion for private discussions
        if (this.activeDiscussion && this.activeDiscussion.discussion_type === 'private') {
          // Use the UserIds from the activeDiscussion JSON
          if (this.activeDiscussion.UserIds && this.activeDiscussion.UserIds.trim()) {
            teamMembersArr = this.activeDiscussion.UserIds;
          }
        }
        else if (this.activeDiscussion && this.activeDiscussion.discussion_type === 'public') {
          if (this.DirectUserData2 && this.DirectUserData2.length > 0) {
            // Extract all UserIds from DirectUserData
            const allUserIds = this.DirectUserData2
              .map(user => user.UserId)
              .filter(id => id && id.toString().trim() !== '')
              .join(',');
            if (allUserIds) {
              teamMembersArr = allUserIds;
            } else {
              teamMembersArr = this.SelectedTeamMembers[0] || '';
            }
          }
        }
        else {
          // For public discussions, use SelectedTeamMembers
          teamMembersArr = this.SelectedTeamMembers[0] || '';
        }
