    customConfirm: function (message, options, callback) {
      // Remove any existing custom confirm modal first
      const existingModal = document.querySelector('.custom-confirm-modal');
      if (existingModal) {
        document.body.removeChild(existingModal);
      }

      // Create modal structure matching your existing style
      const modal = document.createElement('div');
      modal.className = 'modal fade show d-block my-popups custom-confirm-modal';
      modal.style.backgroundColor = 'rgba(0,0,0,0.5)';
      modal.style.zIndex = '1055'; // Higher than Bootstrap modals

      // Generate buttons HTML
      const buttonsHtml = options.map(option => {
        let btnClass = 'btn-success';
        let icon = 'fa-check';

        if (option.value === 'cancel') {
          btnClass = 'btn-danger';
          icon = 'fa-times';
        } else if (option.value === 'self') {
          btnClass = 'btn-outline-primary';
          icon = 'fa-user';
        } else if (option.value === 'all') {
          btnClass = 'btn-success';
          icon = 'fa-users';
        }

        return `
          <button type="button" 
                  class="btn ${btnClass} formbtn widthhalf"
                  data-option="${option.value}">
            <em class="fa ${icon} mr-1"></em>${option.text}
          </button>
        `;
      }).join('');

      // Modal HTML WITHOUT header
      modal.innerHTML = `
        <div class="modal-dialog modal-dialog-centered modal-me" style="margin-top: 100px;">
          <div class="modal-content">
            <!-- Header removed as requested -->
            <div class="modal-body p-0 notifybox">
              <div class="-body alert alert-warning p-3 mb-0">
                ${message}
              </div>
            </div>
            <div class="modal-footer my-0 py-2 modal-confirm-footer">
              ${buttonsHtml}
            </div>
          </div>
        </div>
      `;

      // Add to DOM
      document.body.appendChild(modal);

      // Event handler function
      const handleOption = (optionValue) => {
        // Remove modal
        if (modal.parentNode) {
          document.body.removeChild(modal);
        }
        // Execute callback
        if (typeof callback === 'function') {
          callback(optionValue);
        }
      };

      // Attach event listeners using event delegation
      modal.addEventListener('click', (e) => {
        const target = e.target;

        // Handle button clicks
        if (target.closest('button[data-option]')) {
          const button = target.closest('button[data-option]');
          const option = button.getAttribute('data-option');
          handleOption(option);
          e.stopPropagation();
          return;
        }

        // Handle background click
        if (target === modal) {
          handleOption('cancel');
          e.stopPropagation();
        }
      });

      // Also attach direct event listeners for reliability
      setTimeout(() => {
        const buttons = modal.querySelectorAll('button[data-option]');
        buttons.forEach(button => {
          button.addEventListener('click', (e) => {
            e.stopPropagation();
            const option = button.getAttribute('data-option');
            handleOption(option);
          });
        });
      }, 10);

      // Prevent default behavior
      modal.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
      });
    },

