      }
    },

    // Update a main message locally after edit so that rendering (including @mention highlighting)
    // immediately reflects the new content without waiting for a full reload.
    updateMessageInList(messageId, newTitle) {
      if (!messageId || newTitle === undefined || newTitle === null) {
        return;
      }

      const updateArray = (arr) => {
        if (!arr || !arr.length) return;
        const msg = arr.find(m => m.messageId === messageId);
        if (msg) {
          // Backend uses "content" for the main message text; keep any other fields intact.
          this.$set(msg, 'content', newTitle);
          // Some contexts may still read from "message"; keep it in sync just in case.
          if (Object.prototype.hasOwnProperty.call(msg, 'message')) {
            this.$set(msg, 'message', newTitle);
          }
          // Update title field as well for consistency
          if (Object.prototype.hasOwnProperty.call(msg, 'title')) {
            this.$set(msg, 'title', newTitle);
          }
        }
      };

      // Update in both discussion and direct-message collections
      updateArray(this.messages);
      updateArray(this.messages2);
    },

    async toggleLike(message) {
      try {
        
        const isCurrentlyLiked = message.is_liked_by_current_user || false;
        const jsonobj = {
          MessageBoardId: message.messageId,
          IsLiked: !isCurrentlyLiked
        };

        const params = JSON.stringify(jsonobj);
        const response = await DataService.SaveMessageBoardLike(params);

        // Check if we have the result data directly
        if (response.data && response.data.result) {
          const result = response.data.result;

          // Convert string values to numbers/booleans
          const likeCount = parseInt(result.like_count);
          const isLiked = parseInt(result.is_liked_by_current_user) === 1;

          // Update local state
          this.$set(this.messageLikes, message.messageId, {
            like_count: likeCount,
            is_liked_by_current_user: isLiked,
            like_id: result.like_id ? parseInt(result.like_id) : null
          });

          // Update the message object
          message.likes = likeCount;
          message.is_liked_by_current_user = isLiked;
        } else {
          this.ShowAlert("No response data received", "failure", true, "Error");
        }
      } catch (error) {
        console.error('Error toggling like:', error);
        this.ShowAlert("Error updating like. Please try again.", "failure", true, "Error");
      }
    },

    async fetchMessageLikes(messageIds, getDetails = false) {
      if (!messageIds || messageIds.length === 0) return;
      const messageIdsString = messageIds.join(',');
      const response = await DataService.GetMessageBoardLikes(messageIdsString, getDetails);

      let likeData = null;

      // Check different possible structures within result
      if (response.data.result && Array.isArray(response.data.result)) {
        // Structure: response.data.result is directly the array
        likeData = response.data.result;
      }
      else if (response.data.result && response.data.result.data && Array.isArray(response.data.result.data)) {
        // Structure: response.data.result.data is the array
        likeData = response.data.result.data;
      }

      // Process the like data
      likeData.forEach((item, index) => {
        
        if (item.message_board_id) {
          const messageId = parseInt(item.message_board_id);
          const likeCount = parseInt(item.like_count);
          const isLiked = parseInt(item.is_liked_by_current_user) === 1;
          const liked_name=item.LIKED_USER_NAME
          this.$set(this.messageLikes, messageId, {
            like_count: likeCount,
            is_liked_by_current_user: isLiked,
            liked_name:liked_name,
            like_id: item.user_like_id ? parseInt(item.user_like_id) : null
          });
        }
      });

      this.updateMessagesWithLikeData();
    },
    BackToList: function () {
      var ths = this;
      ths.$router.push({ name: 'ProjectList' });
    },
    getInitials(name) {
      if (!name) return '';
      return name
        .split(' ')
        .map((n) => n[0])
        .join('')
        .toUpperCase();
    },

    updateMessagesWithLikeData() {
      // Update messages with like data
      let updatedCount = 0;
      this.messages.forEach(message => {
        const likeData = this.messageLikes[message.messageId];
        if (likeData) {
          message.likes = likeData.like_count;
          message.liked_name=likeData.liked_name;
          message.is_liked_by_current_user = likeData.is_liked_by_current_user;
          updatedCount++;
        }
      });

      // Update messages2 with like data
      this.messages2.forEach(message => {
        const likeData = this.messageLikes[message.messageId];
        if (likeData) {
          message.likes = likeData.like_count;
          message.liked_name=likeData.liked_name;
          message.is_liked_by_current_user = likeData.is_liked_by_current_user;
          updatedCount++;
        }
      });
    },

    triggerFileInput(type) {
      this.isFiletype = type;
      this.$refs.fileInput.click();
    },
    // Handle file upload
    handleFileUpload(event) {
      const files = event.target.files;
      if (!files.length) return;

      Array.from(files).forEach(file => {
        // Validate file size (e.g., 10MB limit)
        if (file.size > 10 * 1024 * 1024) {
          this.ShowAlert("File size too large. Maximum size is 10MB.", "warning", true, "File Upload");
          return;
        }

        const blobUrl = URL.createObjectURL(file);
        this.attachments.push({
          file: file,
          name: file.name,
          size: file.size,
          type: file.type,
          filePath: blobUrl
        });
      });

      // Reset file input
      event.target.value = '';
    },

    // Remove attachment
    removeAttachment(index) {
      this.attachments.splice(index, 1);
    },

    async takeScreenshot(type) {
      this.isFiletype = type;
      this.isSpinner = true;
      await this.$nextTick();
      // Defer the heavy work to allow UI to render spinner immediately
      setTimeout(async () => {
        try {
          const html2canvas = (await import('html2canvas')).default;
          const canvas = await html2canvas(document.body, {
            useCORS: true,
            allowTaint: true,
            scale: 0.8, // Reduce size for better performance
          });
          canvas.toBlob((blob) => {
            const screenshotFile = new File([blob], `screenshot-${new Date().getTime()}.png`, {
              type: 'image/png',
            });
            // Update the attachments array
            this.attachments.push({
              file: screenshotFile,
              name: screenshotFile.name,
              size: screenshotFile.size,
              type: screenshotFile.type,
              isScreenshot: true,
            });
            // Force reactivity (just in case)
            this.$set(this, 'attachments', [...this.attachments]);
            this.isSpinner = false;
            //this.ShowAlert("Screenshot captured successfully!", "success", true, "Screenshot");
            
          }, 'image/png');
        } catch (error) {
          console.error('Error taking screenshot:', error);
          this.isSpinner = false;
          this.ShowAlert("Failed to capture screenshot", "failure", true, "Screenshot");
        }
      }, 0);
    },

    // Format file size
    formatFileSize(bytes) {
      if (bytes === 0) return '0 Bytes';
      const k = 1024;
      const sizes = ['Bytes', 'KB', 'MB', 'GB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    },

    // Handle @ mention detection in input
    handleMentionInput(event, context = 'main', replyIndex = null) {
       this.removeHighlight();
      // Disable mentions in one-to-one chats
      if (this.isUserData && this.selectedUserId) {
        this.showMentionDropdown = false;
        this.mentionSearchTerm = '';
        return;
      }

      const input = event.target;
      const value = input.value;
      const cursorPosition = input.selectionStart;

      // Find the last @ symbol before cursor
      const textBeforeCursor = value.substring(0, cursorPosition);
      const lastAtIndex = textBeforeCursor.lastIndexOf('@');

      if (lastAtIndex !== -1) {
        // Check if there's a space after @ (meaning @ is not active)
        const textAfterAt = textBeforeCursor.substring(lastAtIndex + 1);
        if (!textAfterAt.includes(' ') && !textAfterAt.includes('\n')) {
          // Check if we have available users for mentions
          const availableUsers = this.getAvailableUsersForMentions();
          if (availableUsers.length === 0) {
            // No users available, don't show dropdown
            this.showMentionDropdown = false;
            this.mentionSearchTerm = '';
            return;
          }

          // @ is active, show dropdown
          this.mentionSearchTerm = textAfterAt;
          this.mentionPosition = lastAtIndex;
          this.mentionContext = context;
          this.mentionReplyIndex = replyIndex;
          this.showMentionDropdown = true;
          this.selectedMentionIndex = 0;

          // Attach outside-click handler
          this.$nextTick(() => {
            document.addEventListener('click', this.handleMentionClickOutside);
          });
          return;
        }
      }

      // Close dropdown if @ is not active
      this.showMentionDropdown = false;
      this.mentionSearchTerm = '';
      document.removeEventListener('click', this.handleMentionClickOutside);
    },

    // Handle keyboard navigation in mention dropdown
    handleMentionKeydown(event, context = 'main', replyIndex = null) {
      // If dropdown is visible, handle navigation
      if (this.showMentionDropdown) {
        const filteredUsers = this.filteredMentionUsers;

        if (event.key === 'ArrowDown') {
          event.preventDefault();
          this.selectedMentionIndex = Math.min(this.selectedMentionIndex + 1, filteredUsers.length - 1);
        } else if (event.key === 'ArrowUp') {
          event.preventDefault();
          this.selectedMentionIndex = Math.max(this.selectedMentionIndex - 1, 0);
        } else if (event.key === 'Enter') {
          // IMPORTANT: Prevent form submission when selecting mention
          event.preventDefault();
          event.stopPropagation();

          if (filteredUsers.length > 0) {
            this.selectMention(filteredUsers[this.selectedMentionIndex], context, replyIndex);
          }
        } else if (event.key === 'Tab') {
          event.preventDefault();
          if (filteredUsers.length > 0) {
            this.selectMention(filteredUsers[this.selectedMentionIndex], context, replyIndex);
          }
        } else if (event.key === 'Escape') {
          event.preventDefault();
          this.showMentionDropdown = false;
        } else {
          // Let the input handle other keys
          this.$nextTick(() => {
            this.handleMentionInput(event, context, replyIndex);
          });
        }
        return; // Important: return early when dropdown is visible
      }

      // Check if @ was just typed
      if (event.key === '@') {
        this.$nextTick(() => {
          this.handleMentionInput(event, context, replyIndex);
        });
      }
    },

    // Select a user from mention dropdown
    selectMention(user, context = 'main', replyIndex = null) {
      if (!user) return;

      const mentionText = `@${user.UserName}`;

      this.$nextTick(() => {
        let inputElement;

        if (context === 'reply' && replyIndex !== null) {
          // Find the specific reply input element using ref
          const refName = `replyInput_${replyIndex}`;
          inputElement = this.$refs[refName];
        } else {
          // Main message textarea
          inputElement = this.$el.querySelector('textarea.form-control');
        }

        if (!inputElement) return;

        // Always use the live value from the input element to avoid desync
        const currentValue = inputElement.value || (context === 'reply' ? this.newMessageContent : this.messageContent) || '';
        const cursorPos = inputElement.selectionStart || currentValue.length;

        // Replace @searchTerm with @username
        const textBeforeCursor = currentValue.substring(0, this.mentionPosition);
        const textAfterAt = currentValue.substring(this.mentionPosition, cursorPos);
        const textAfterCursor = currentValue.substring(cursorPos);

        const newValue = textBeforeCursor + mentionText + ' ' + textAfterCursor;

        if (context === 'reply') {
          this.newMessageContent = newValue;
        } else {
          this.messageContent = newValue;
        }

        // Close dropdown
        this.showMentionDropdown = false;
        this.mentionSearchTerm = '';

        // Set cursor position after the mention
        this.$nextTick(() => {
          const newCursorPos = this.mentionPosition + mentionText.length + 1;
          if (inputElement) {
            inputElement.setSelectionRange(newCursorPos, newCursorPos);
            inputElement.focus();
          }
        });
      });
    },

    // Extract mentioned users from message text
    extractMentionedUsers(text) {
      if (!text) return [];

      // For one-to-one chats, don't extract mentions
      if (this.isUserData && this.selectedUserId) {
        return [];
      }

      // Get available users based on discussion type
      const availableUsers = this.getAvailableUsersForMentions();
      if (availableUsers.length === 0) {
        return [];
      }

      // Extract mentions with support for multi-word usernames
      const mentionRegex = /@([a-zA-Z]+(?:\s+[a-zA-Z]+)?)/g;
      const matches = text.match(mentionRegex);
      if (!matches) return [];

      const mentionedUserIds = [];
      matches.forEach(match => {
        const username = match.substring(1).trim(); // Remove @ and trim
        const user = availableUsers.find(u => {
          const userNameLower = u.UserName.toLowerCase();
          const mentionLower = username.toLowerCase();
          return userNameLower === mentionLower || 
                 userNameLower.includes(mentionLower) ||
                 mentionLower.includes(userNameLower);
        });
        if (user) {
          mentionedUserIds.push(user.UserId);
        }
      });

      return [...new Set(mentionedUserIds)]; // Remove duplicates
    },

    handleMentionClick(event, messageContent) {
      // Disable mention clicks in one-to-one chats
      if (this.isUserData && this.selectedUserId) {
        return;
      }

      const mentionElement = event.target.closest('.mention-highlight');
      if (!mentionElement) return;
      
      const mentionText = mentionElement.getAttribute('data-mention') || 
                          mentionElement.textContent.replace('@', '');
      
      if (!mentionText) return;
      
      // Get available users based on discussion type
      const availableUsers = this.getAvailableUsersForMentions();
      const user = availableUsers.find(u => 
        u.UserName.toLowerCase().includes(mentionText.toLowerCase()) ||
        mentionText.toLowerCase().includes(u.UserName.toLowerCase())
      );
      
      if (!user) {
        // For private groups, show specific message
        if (this.activeDiscussion && this.activeDiscussion.discussion_type === 'private') {
          this.ShowAlert(`User "${mentionText}" is not a member of this private discussion`, "warning", true, "User Not Found");
        } else {
          this.ShowAlert(`User "${mentionText}" not found`, "warning", true, "User Not Found");
        }
        return;
      }
      
      // Navigate to private chat with the mentioned user
      this.selectUser(null, user);
      
      setTimeout(() => {
        const chatContainer = this.$el.querySelector('.flex-grow-1.overflow-auto');
        if (chatContainer) {
          chatContainer.scrollTop = 0;
        }
      }, 100);
    },
    extractAllMentions(text) {
      if (!text) return [];
      
      const mentions = [];
      const mentionRegex = /@([a-zA-Z\s]+)/g;
      let match;
      
      while ((match = mentionRegex.exec(text)) !== null) {
        mentions.push({
          fullText: match[0],
          username: match[1].trim(),
          position: match.index
        });
      }
      
      return mentions;
    },

    showMentionTooltip(event, username) {
      
      
      const user = this.DirectUserData.find(u => 
        u.UserName.toLowerCase().includes(username.toLowerCase())
      );
      
      if (user) {
        this.ShowAlert(`User: ${user.UserName}\nRole: ${user.UserType}`, "info", true, "User Info");
      }
    },
    async refreshDiscussions() {
      try {
        this.isLoading = true;
        await this.GetProjectDiscussions();

        // If we have an active discussion, refresh its messages too
        if (this.activeDiscussionId) {
          await this.GetMessageListing();
        }

        //this.ShowAlert("Discussion Topics refreshed successfully", "success", true, "Refresh");
      } catch (error) {
        console.error('Error refreshing discussions:', error);
        this.ShowAlert("Failed to refresh discussions", "failure", true, "Error");
      } finally {
        this.isLoading = false;
      }
    },

    async refreshDirectUserList() {
      try {
        this.isLoading = true;

        // Refresh the team/direct user list
        await this.FetchTeam();

        // If we have a selected user, refresh their messages too
        if (this.isUserData && this.selectedUserId) {
          await this.GetUserMessages(this.UserData);
        }

        //this.ShowAlert("Direct Messages refreshed successfully", "success", true, "Refresh");
      } catch (error) {
        console.error('Error refreshing direct messages:', error);
        this.ShowAlert("Failed to refresh direct messages", "failure", true, "Error");
      } finally {
        this.isLoading = false;
      }
    },
    isUserInDiscussion(userId) {
      if (!this.activeDiscussion?.UserIds) return false;
      const ids = this.activeDiscussion.UserIds.split(',').map(s => s.trim()).filter(Boolean);
      return ids.includes(userId.toString());
    },

    showDiscussionUsers() {
      if (this.activeDiscussion && this.activeDiscussion.UserNames && this.activeDiscussion.UserNames.trim() !== '') {
        this.isShowDiscussionUsersPopover = true;
      }
    },

    hideDiscussionUsers() {
      this.isShowDiscussionUsersPopover = false;
    },

    TruncateStr(str, maxLength = 15) {
      if (!str) return '';
      return str.length > maxLength ? str.substring(0, maxLength) + '...' : str;
    },

    // Show liked by popover on hover
    showLikedByPopover(messageId) {
      this.hoveredLikeMessageId = messageId;
    },

    // Hide liked by popover on mouse leave
    hideLikedByPopover() {
      this.hoveredLikeMessageId = null;
    },

  }
  ,
  watch: {
    activeDiscussionId: {
      immediate: true,
      handler(newVal, oldVal) {
        // Only load messages if we have a valid discussion ID and not in user data mode
        if (newVal && !this.isUserData) {
          // Use a small delay to ensure everything is ready
          setTimeout(() => {
            this.GetMessageListing();
          }, 100);
        }
      }
    }
  }

};
